insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Regione del Veneto – U.O. Fitosanitario – Bollettini fitosanitari 2026','https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','semanal de marco a setembro para vite, olivo, frutticolo e orticolo; erbacee interrompida',NULL,'Cinco series semanais separadas com fase fenologica declarada: VITICOLO (n.20 de 27/08/2026, com tabela BBCH por vitigno), OLIVICOLO (n.29 de 02/09/2026, com % de infestacao por areal), FRUTTICOLO (n.24 de 26/08/2026: melo, pero, susino, actinidia), ORTICOLO (n.22 de 26/08/2026: pomodoro da industria, radicchio) e ERBACEE ED INDUSTRIALI (parada no n.02 de 05/06/2026).') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Fondazione Edmund Mach – CTT – Bollettini Difesa Integrata di Base','https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','semanal (sextas-feiras), de primavera a inicio de outono',NULL,'Boletim unico multicultura de 10 paginas com ''Stadio fenologico'' por cultura e por zona altimetrica (fondovalle / collina): melo, vite, olivo, susino, actinidia, piccoli frutti. N.25 de 28/08/2026 e o mais recente.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('ARSAC – Bollettino agrometeorologico e fitosanitario (Calabria)','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','semanal (semana 36 = 01 a 08/09/2026)',NULL,'Sintese regional semanal com fenologia declarada de olivo, vite, agrumi e kiwi, dividida em 8 zonas climaticamente homogeneas que cobrem todo o territorio calabres, mais PDF por area. Ha ainda serie separada ''Limone''.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Regione Campania – Servizio Fitosanitario Regionale – Bollettini fitosanitari 2026','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026.html',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','semanal de 1 de marco a 30 de setembro; olivo continua semanal ate fim de outubro',NULL,'Cinco boletins PROVINCIAIS (Avellino, Benevento, Caserta, Napoli, Salerno), n.24 de 26/08/2026, em PDF, com tabela por empresa/comune/variedade contendo ''Stadio fenologico'' e ''Stato fitosanitario'' com numero de capturas, para vite, olivo, pomodoro, actinidia, agrumi, ciliegio, castagno, fragola, nocciolo, noce, pesco, melanzana, melo, pero, patata.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Regione Liguria – C.A.A.R. – Bollettino Vite e Bollettino Olivo','https://sia.regione.liguria.it/index.php/ultimi-bollettini',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','semanal de abril a setembro, mensal de outubro a marco',NULL,'Sintese regional semanal em HTML mais quatro PDFs provinciais (GE, IM, SP, SV) por numero. Vite n.25 e Olivo n.16, ambos de 27/08/2026. Vite acompanha curva de maturacao (acucar, pH, acidez) com analise no laboratorio de Sarzana; olivo mantem rede de ~120 olivais de monitoramento de mosca.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('ALSIA – Servizio di Difesa Integrata – Bollettini fitosanitari Metapontino (Basilicata)','https://www.alsia.it/opencms/opencms/Servizi/Fito/Metapontino.html',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','aproximadamente quinzenal na estacao, cerca de 20 numeros por ano',NULL,'Boletim quinzenal de areal com a fase fenologica no cabecalho de cada cultura (agrumi, pesco, albicocco, susino, vite, olivo) e sintese do boletim agrometeorologico. N.16 de 20/08/2026, com validade declarada ate 02/09/2026.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Ente Nazionale Risi – Bollettini regionais de arroz','https://www.enterisi.it/servizi/Menu/dinamica.aspx?idSezione=17505&idArea=17525&idCat=30252&ID=30252&TipoElemento=Categoria',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','duas vezes por semana (segundas e quintas) na estacao',NULL,'Cinco series territoriais de boletim agrometeorologico com indice de risco de brusone: Piemonte, Lombardia, Mantova/Verona, Ferrara e Oristano. Ultima emissao 27/08/2026 (Lombardia, Mantova/Verona, Oristano) e 20/08/2026 (Piemonte).') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('CREA AA / Rete PAC – Rete Rurale Nazionale – Bollettino fenologico settimanale','https://www.reterurale.it/bollettinofeno',ARRAY['BOLETIM_FITOSSANITARIO','CIENCIA']::fonte_natureza[],'IT','semanal durante a estacao vegetativa',NULL,'Cartas nacionais de analise e previsao da fase fenologica de olivo, vite (cv Cabernet sauvignon e Chardonnay), robinia e castagno, em escala BBCH, com texto por macroarea que nomeia Sicilia e Sardegna. Baseado no modelo IPHEN interpolado sobre grade ICON-EU de ~6,5 km, calibrado com levantamentos de voluntarios. Emissao de 27/08/2026 disponivel em PDF.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('SIAS – Servizio Informativo Agrometeorologico Siciliano','http://www.sias.regione.sicilia.it',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT','declarada como previsional, mensal e decadica — nao verificavel',NULL,'Deveria publicar boletins agrometeorologicos previsionais e boletins de difesa fitosanitaria da Sicilia, a partir de rede de 96 estacoes automaticas.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Regione Lazio – Servizio Fitosanitario Regionale (rota antiga) e ARSIAL','https://www.arsial.it/difesa-integrata/bollettini-fitosanitari',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','nao verificavel',NULL,'Deveria publicar os boletins de difesa integrata obbligatoria do Lazio, inclusive a serie da vite do projeto ''Lazio DiSu''.') on conflict (url_base) do nothing;
