insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Copernicus Climate Data Store (CDS) — ERA5 / ERA5-Land','https://cds.climate.copernicus.eu',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT','ERA5 com ~5 dias de atraso; ERA5-Land mensal/diario',NULL,'Reanalise ERA5 e ERA5-Land: temperatura, precipitacao, umidade do solo por camada, evapotranspiracao, grade horaria/diaria desde 1940. E a fonte-mae de quase todo indice europeu.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Copernicus EDO — European Drought Observatory (via JRC "Current drought situation in Europe")','https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT','a cada 10 dias',NULL,'Combined Drought Indicator (CDI) por decadas de 10 dias, ~5 km, combinando SPI, anomalia de umidade do solo e anomalia de fAPAR; mais Low-Flow Index (LFI) e intensidade de onda de calor. Texto descritivo por pais/area em cada decada.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('JRC MARS Bulletin — Crop monitoring in Europe','https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT','mensal (Vol. 34 No 7 = agosto/2026, publicado em 24/08/2026; proxima edicao anunciada para 28/09/2026)',NULL,'Boletim agrometeorologico da UE: revisao meteorologica, indicadores de biomassa (fAPAR), estresse hidrico, fenologia simulada e previsao de produtividade por pais, com secao propria da Italia.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('open-meteo.org — Forecast API e Archive API (ERA5)','https://api.open-meteo.com/v1/forecast',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT','forecast atualizado varias vezes ao dia; archive com ~5 dias de atraso',NULL,'Serie diaria e horaria por coordenada: precipitacao, temperatura maxima/minima/media, umidade relativa, evapotranspiracao de referencia, umidade do solo por camada. O archive e ERA5 reanalisado; o forecast e mistura de modelos.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('ARPAV — Agenzia Regionale per la Prevenzione e Protezione Ambientale del Veneto','https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT','semanal (N. 21 de 01.09.2026, atualizado em 02.09)',NULL,'Bollettino Agrometeorologico Regionale semanal: mapas decadais de temperatura minima/maxima e precipitacao, numero de dias de chuva >=1 mm, evapotranspiracao potencial Penman-Monteith da planicie veneta, somas termicas, e dados de estacao com bagnatura fogliare (molhamento foliar) e temperatura do solo por profundidade. Traz tambem links para os boletins fitossanitarios da Regiao Veneto.') on conflict (url_base) do nothing;
