insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Giornate Fitopatologiche 2026 — programa e atas','https://giornatefitopatologiche.it/it/giornate-fitopatologiche/18/giornate-fitopatologiche-2026/89',ARRAY['OUTRA']::fonte_natureza[],'IT','bienal',NULL,'Programa e apresentacoes da edicao de 17 a 20 de marco de 2026 em Bolonha: 114 trabalhos experimentais, 60 relatores, com nome e afiliacao. Inclui sensibilidade de Stemphylium vesicarium da pera a fungicidas, defesa com baixo aporte de cobre contra Venturia oleaginea, flavescencia dourada e quatro novas substancias ativas. NAO foi aberto nesta rodada.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('GIRE — Linee guida diserbo (repositorio de PDFs por cultura)','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo',ARRAY['CIENCIA']::fonte_natureza[],'IT','atualizacao anual (marco)',NULL,'Linhas-guia de gestao de resistencia por sistema de cultivo (cereali autunno-vernini, riso, riso Clearfield, arboree), cada uma com tabela de principios ativos autorizados x grupo HRAC x EPOCA DE USO, e uma secao ''cosa fare se ho biotipi di X'' por especie daninha. As versoes vivas sao de MARCO DE 2026 — mais novas que a de 2023 que o acervo ja tinha.') on conflict (url_base) do nothing;
