insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Confirma que o dataflow 101_1015 e o cubo Coltivazioni e aponta a estrutura DCSP_COLTIVAZIONI v1.1. Traz tambem a anotacao LAST_UPDATE com a data de atualizacao do cubo.','https://esploradati.istat.it/SDMXWS/rest/dataflow/IT1/101_1015',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT',NULL,'SDMX-ML estrutura (Accept: application/vnd.sdmx.structure+xml;version=2.1)','Confirma que o dataflow 101_1015 e o cubo Coltivazioni e aponta a estrutura DCSP_COLTIVAZIONI v1.1. Traz tambem a anotacao LAST_UPDATE com a data de atualizacao do cubo.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Da a ordem das dimensoes da chave de consulta: FREQ.REF_AREA.DATA_TYPE.TYPE_OF_CROP.DESTINATION_WINEGRAPES.TIME_PERIOD. Sem isso nao da para montar URL de dado.','https://esploradati.istat.it/SDMXWS/rest/datastructure/IT1/DCSP_COLTIVAZIONI/1.1?references=none',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT',NULL,'SDMX-ML estrutura','Da a ordem das dimensoes da chave de consulta: FREQ.REF_AREA.DATA_TYPE.TYPE_OF_CROP.DESTINATION_WINEGRAPES.TIME_PERIOD. Sem isso nao da para montar URL de dado.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Dicionario das culturas: 872 codigos com nome em italiano e ingles. E onde se descobre que melo se busca por APPLE e nao por APPLET, e que vite se busca por WINEES (uva da vino).','https://esploradati.istat.it/SDMXWS/rest/codelist/IT1/CL_AGRI_MADRE',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT',NULL,'SDMX-ML estrutura','Dicionario das culturas: 872 codigos com nome em italiano e ingles. E onde se descobre que melo se busca por APPLE e nao por APPLET, e que vite se busca por WINEES (uva da vino).') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Dicionario dos indicadores. Os que interessam: ART = superficie totale - ettari; PA = superficie in produzione - ettari; HP_Q_EXT = produzione raccolta - quintali; TP_QUIN_EXT = produzione totale - qu','https://esploradati.istat.it/SDMXWS/rest/codelist/IT1/CL_TIPO_DATO5',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT',NULL,'SDMX-ML estrutura','Dicionario dos indicadores. Os que interessam: ART = superficie totale - ettari; PA = superficie in produzione - ettari; HP_Q_EXT = produzione raccolta - quintali; TP_QUIN_EXT = produzione totale - quintali.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('O endpoint de DADO. Com Accept ''application/vnd.sdmx.data+csv;version=1.0.0;labels=both'' devolve CSV ja com os rotulos em italiano ao lado de cada codigo, o que economiza cruzar codelist depois. Dimen','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.<REGIOES>.<INDICADORES>.<CULTURAS>.?startPeriod=2024',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT',NULL,'SDMX-CSV com rotulos','O endpoint de DADO. Com Accept ''application/vnd.sdmx.data+csv;version=1.0.0;labels=both'' devolve CSV ja com os rotulos em italiano ao lado de cada codigo, o que economiza cruzar codelist depois. Dimensao vazia = todos os valores.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Truque util: deixando a dimensao de cultura vazia, lista TODAS as culturas do cubo (281 linhas) com o nome em italiano. E o inventario do cubo — foi assim que achei que melo esta como APPLE.','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT.ART..?startPeriod=2025&endPeriod=2025',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT',NULL,'SDMX-CSV com rotulos','Truque util: deixando a dimensao de cultura vazia, lista TODAS as culturas do cubo (281 linhas) com o nome em italiano. E o inventario do cubo — foi assim que achei que melo esta como APPLE.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Deixando o territorio vazio, lista os 246 territorios do cubo: nacional, macroareas (ITC/ITD/ITE/ITF/ITG), 20 regioes, provincias autonomas e provincias. Foi assim que descobri que o ISTAT usa aqui os','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A..ART.MAIZE.?startPeriod=2025&endPeriod=2025',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT',NULL,'SDMX-CSV','Deixando o territorio vazio, lista os 246 territorios do cubo: nacional, macroareas (ITC/ITD/ITE/ITF/ITG), 20 regioes, provincias autonomas e provincias. Foi assim que descobri que o ISTAT usa aqui os codigos NUTS ANTIGOS (ITD3 Veneto, ITD5 Emilia-Romagna), nao os atuais (ITH3, ITH5).') on conflict (url_base) do nothing;
