insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Fora do meu bloco, mas confirmei de passagem que a rota esta viva.','https://www.ismeamercati.it',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML','Fora do meu bloco, mas confirmei de passagem que a rota esta viva.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Portal institucional ISMEA. Passou de 404 para 200 com a VPN. E majoritariamente financiamento e credito (ISMEA Investe, Generazione Terra, Piu Impresa). Tem ''Tutti i report'' em /flex/cm/pages/ServeBL','https://www.ismea.it',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML','Portal institucional ISMEA. Passou de 404 para 200 com a VPN. E majoritariamente financiamento e credito (ISMEA Investe, Generazione Terra, Piu Impresa). Tem ''Tutti i report'' em /flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/9524 e /mercati-filiere, mas os relatorios de mercado apontam de volta para ismeamercati.it.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Padrao universal de pagina do CMS Flex. Todo conteudo (precos, relatorios, tabelas) e acessivel por este molde. IDs uteis mapeados: 853 cereais preco semanal por produto · 854 por variedade · 3111 cer','https://www.ismeamercati.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/{ID}',ARRAY['MERCADO','CIENCIA']::fonte_natureza[],'IT',NULL,'HTML com tabelas','Padrao universal de pagina do CMS Flex. Todo conteudo (precos, relatorios, tabelas) e acessivel por este molde. IDs uteis mapeados: 853 cereais preco semanal por produto · 854 por variedade · 3111 cereais por praca · 13899 CUN frumento duro · 928/930 semi oleosi semanal/mensal · 960/961 vinho comum semanal · 956 vinho por praca · 652/654/656 azeite · 501/507 ortaggi · 558/559 frutta · 2208/2210/22') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Cotacao detalhada de UMA praca em UMA data. Os pares (ID_PRACA, TIMESTAMP) sao lidos da tabela ''Ultime quotazioni'' da propria pagina 3111. IDs confirmados: Cuneo 2 · Torino 7 · Novara 11 · Vercelli 14','https://www.ismeamercati.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/3111/ISUQC5/{ID_PRACA}/DT5/{TIMESTAMP_UNIX}',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML com tabela de cotacoes','Cotacao detalhada de UMA praca em UMA data. Os pares (ID_PRACA, TIMESTAMP) sao lidos da tabela ''Ultime quotazioni'' da propria pagina 3111. IDs confirmados: Cuneo 2 · Torino 7 · Novara 11 · Vercelli 14 · Mantova 19 · Alessandria 20 · Milano 26 · Pavia 35 · Mortara 36 · Cremona 37 · Rovigo 38 · Foggia 118 · Bologna 62 · Treviso 67 · Macerata 79 · Siena 80 · Avellino 82 · Brescia 84 · Verona 94 · Mod') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('ENDPOINT DE DADO REAL. XML de serie temporal (formato FusionCharts) com os valores anuais de superficie, producao e rendimento por produto e por regiao. Cada <set label="ANO" value="VALOR"> e um ponto','https://www.ismeamercati.it/flex/tmp/FlexFCharts/{HASH}',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'XML','ENDPOINT DE DADO REAL. XML de serie temporal (formato FusionCharts) com os valores anuais de superficie, producao e rendimento por produto e por regiao. Cada <set label="ANO" value="VALOR"> e um ponto; o atributo yAxisName da a unidade (ha, t, t/ha) e caption da o recorte (ex.: ''Soia - Veneto''). O HASH esta no atributo data-relxml da pagina de producao correspondente.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Planilha XLSX com os mesmos dados da tabela ou do grafico da pagina. O HASH esta em data-relxls (paginas de producao) ou no link ''Scarica i dati in formato excel'' (tabelas de preco). ATENCAO: os hashe','https://www.ismeamercati.it/flex/tmp/xls/{HASH}.xlsx',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'XLSX','Planilha XLSX com os mesmos dados da tabela ou do grafico da pagina. O HASH esta em data-relxls (paginas de producao) ou no link ''Scarica i dati in formato excel'' (tabelas de preco). ATENCAO: os hashes ficam em /flex/tmp/ e sao regerados; a URL de hoje pode nao valer amanha. NAO baixei nenhum arquivo — deixo a URL para o dono decidir.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('PDF integral dos relatorios Tendenze e AgriMercati. Ex.: o Tendenze Frutta Focus Mele (ID 13723) tem PDF neste padrao. NAO baixei — download de arquivo precisa de autorizacao explicita do dono.','https://www.ismeamercati.it/flex/cm/pages/ServeAttachment.php/L/IT/D/{PATH}/P/BLOB%3AID%3D{ID_PAGINA}/E/pdf?mode=download',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'PDF','PDF integral dos relatorios Tendenze e AgriMercati. Ex.: o Tendenze Frutta Focus Mele (ID 13723) tem PDF neste padrao. NAO baixei — download de arquivo precisa de autorizacao explicita do dono.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Busca do site. Exige POST multipart/form-data com os campos text=<termo>, btnOK=, HaveDataF1=1. Um POST urlencoded comum retorna 200 com ZERO resultados (falso negativo perigoso). Retorna contagem de ','https://www.ismeamercati.it/flex/cm/FixedPages/Common/Search.v3.php/L/IT/s/1',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML','Busca do site. Exige POST multipart/form-data com os campos text=<termo>, btnOK=, HaveDataF1=1. Um POST urlencoded comum retorna 200 com ZERO resultados (falso negativo perigoso). Retorna contagem de paginas e facetas por setor — foi assim que confirmei a ausencia de filiera de acucar.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Banco de dados de precos na origem, com 4 visoes (produto/variedade, produto/praca, produto/praca+condicao, praca/produto), drilldown por ano, mes, semana, regiao e praca, e exportacao declarada em xl','https://www.ismeamercati.it/prezzi-agroalimentari/origine/banca-dati',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML + iframe','Banco de dados de precos na origem, com 4 visoes (produto/variedade, produto/praca, produto/praca+condicao, praca/produto), drilldown por ano, mes, semana, regiao e praca, e exportacao declarada em xls, csv e pdf. O gemeo para atacado esta em /prezzi-agroalimentari/ingrosso/banca-dati.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Servidor de relatorios ASP.NET que serve o banco de dados de precos dentro do iframe. Sem o token de sessao no caminho, a chamada e redirecionada para outra pagina do ismeamercati. Seria o caminho par','https://report.ismea.it/(S(TOKEN_DE_SESSAO))/ReportPREZZI.aspx?report=PO_Tab01',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML (report viewer)','Servidor de relatorios ASP.NET que serve o banco de dados de precos dentro do iframe. Sem o token de sessao no caminho, a chamada e redirecionada para outra pagina do ismeamercati. Seria o caminho para extracao em massa das series historicas de preco por praca — nao consegui abrir nesta janela.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Banco de dados de comercio exterior agroalimentar, com 4 visoes (sintese, foco setor/produto, foco area/pais, mapa dos fluxos), anual e mensal/acumulado, exportavel em xls, csv, pdf. Mesma arquitetura','https://www.ismeamercati.it/dati-agroalimentare/commercio-estero',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML + iframe','Banco de dados de comercio exterior agroalimentar, com 4 visoes (sintese, foco setor/produto, foco area/pais, mapa dos fluxos), anual e mensal/acumulado, exportavel em xls, csv, pdf. Mesma arquitetura de iframe do banco de precos.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Indice dos relatorios Tendenze (analise e previsao por filiera), filtravel por ano de 2023 a 2026. E onde estao os relatorios de pomodoro da industria, mele, olio, vino, frumento tenero, frumento duro','https://www.ismeamercati.it/report-analisi-agroalimentare/tendenze?YY={ANO}',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML','Indice dos relatorios Tendenze (analise e previsao por filiera), filtravel por ano de 2023 a 2026. E onde estao os relatorios de pomodoro da industria, mele, olio, vino, frumento tenero, frumento duro e mais-soia-orzo.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Indice do AgriMercati, relatorio trimestral de conjuntura com indices de preco, consumo e trocas. Mais recente lido: IV trimestre de 2025, publicado em 05/05/2026 (ID 13895).','https://www.ismeamercati.it/report-analisi-agroalimentare/agrimercati',ARRAY['MERCADO']::fonte_natureza[],'IT',NULL,'HTML','Indice do AgriMercati, relatorio trimestral de conjuntura com indices de preco, consumo e trocas. Mais recente lido: IV trimestre de 2025, publicado em 05/05/2026 (ID 13895).') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Lista as estacoes ARPAV que medem um sensor. Devolve JSON com codseqst, nome da estacao, provincia, latitude/longitude e altitude. Codigos de sensor: 18=temperatura do ar, 23=precipitacao, 19=umidade ','https://api.arpa.veneto.it/REST/v1/meteo_60gg?coordcd={COD}',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT',NULL,'JSON','Lista as estacoes ARPAV que medem um sensor. Devolve JSON com codseqst, nome da estacao, provincia, latitude/longitude e altitude. Codigos de sensor: 18=temperatura do ar, 23=precipitacao, 19=umidade relativa, 22=radiacao solar, 20008=temperatura do solo, 20004=bagnatura fogliare (folha molhada), 20066=ET0 Hargreaves, 20058=freatimetria.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Dado DIARIO dos ultimos 60 dias de uma estacao, todos os sensores de uma vez. Cada linha traz nome_stazione, nome_sensore, dataora, valore, unitnm, tipo e o carimbo de atualizacao.','https://api.arpa.veneto.it/REST/v1/meteo_60gg_tabella?codseqst={CODSEQST}',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT',NULL,'JSON','Dado DIARIO dos ultimos 60 dias de uma estacao, todos os sensores de uma vez. Cada linha traz nome_stazione, nome_sensore, dataora, valore, unitnm, tipo e o carimbo de atualizacao.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Report meteoclimatici da ARPAV: mensais, sazonais e anuais. Desde janeiro de 2026 absorveram o antigo ''Agrometeo mese''. O mensal tem uma secao 6 inteira de agrometeorologia: ETP, balanco hidroclimatic','https://www.arpa.veneto.it/temi-ambientali/meteo/rapporti',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT',NULL,'HTML + PDF','Report meteoclimatici da ARPAV: mensais, sazonais e anuais. Desde janeiro de 2026 absorveram o antigo ''Agrometeo mese''. O mensal tem uma secao 6 inteira de agrometeorologia: ETP, balanco hidroclimatico (BIC), SPEI e somatoria termica — com a anomalia calculada pela propria ARPAV contra a normal 1991-2020.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Open data historico oficial da ARPAV, licenca Creative Commons Atribuicao 4.0: chuva anual, dias de chuva, radiacao solar, temperatura do ar a 2m (media das minimas/medias/maximas), umidade relativa a','https://www.arpa.veneto.it/dati-ambientali/open-data/clima/principali-variabili-meteorologiche',ARRAY['AGROMETEOROLOGIA','CIENCIA']::fonte_natureza[],'IT',NULL,'ZIP de CSV','Open data historico oficial da ARPAV, licenca Creative Commons Atribuicao 4.0: chuva anual, dias de chuva, radiacao solar, temperatura do ar a 2m (media das minimas/medias/maximas), umidade relativa a 2m, vento — por mes e por ano, por estacao. Em 2023 eram 210 estacoes.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Categoria de open data da ARPAV chamada ''Fitosanitari'' — provavelmente dados de venda/uso de produtos fitossanitarios, nao de doenca.','https://www.arpa.veneto.it/dati-ambientali/open-data/fitosanitari',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'NAO_SEI','Categoria de open data da ARPAV chamada ''Fitosanitari'' — provavelmente dados de venda/uso de produtos fitossanitarios, nao de doenca.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('ARPAE Emilia-Romagna: familia inteira de boletins agrometeorologicos — bollettini agrometeo, bollettini agrofenologici, bollettini nitrati e rapporti agrometeo.','https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'HTML (listagem via JS)','ARPAE Emilia-Romagna: familia inteira de boletins agrometeorologicos — bollettini agrometeo, bollettini agrofenologici, bollettini nitrati e rapporti agrometeo.') on conflict (url_base) do nothing;
