insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('Veneto Agricoltura — era o caminho alternativo sugerido para achar boletim fitossanitario fora do regione.veneto.it.','https://www.venetoagricoltura.org/home',ARRAY['OUTRA']::fonte_natureza[],'IT',NULL,'HTML vazio (SPA)','Veneto Agricoltura — era o caminho alternativo sugerido para achar boletim fitossanitario fora do regione.veneto.it.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('LAZIO. Boletim de mosca da oliveira em 5 zonas. O numero final da URL e sequencial (196, 197... 204 = 31/08/2026), entao da para andar para tras e para frente na serie so mudando o numero. Os PDFs est','https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'HTML com links diretos para 5 PDFs','LAZIO. Boletim de mosca da oliveira em 5 zonas. O numero final da URL e sequencial (196, 197... 204 = 31/08/2026), entao da para andar para tras e para frente na serie so mudando o numero. Os PDFs estao em /public/news_file/<id>.pdf.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('LIGURIA. API WordPress oficial do C.A.A.R. da Regione Liguria. Devolve em JSON, com data-hora exata, os Bollettino Olivo, Bollettino Vite e Agrometeo. E o jeito limpo de pegar a serie sem raspar HTML.','https://sia.regione.liguria.it/wp-json/wp/v2/posts?per_page=8&orderby=date&order=desc&_fields=date,link,title',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'JSON (WP REST API)','LIGURIA. API WordPress oficial do C.A.A.R. da Regione Liguria. Devolve em JSON, com data-hora exata, os Bollettino Olivo, Bollettino Vite e Agrometeo. E o jeito limpo de pegar a serie sem raspar HTML. Ultimo: Olivo n.16 e Vite n.25, ambos 27/08/2026.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('MOLISE. Pagina ''Bollettini - Comunicati fitosanitari''. Lista os Comunicati fitosanitari de 2026 (n.1 a n.5) e os Bollettini di vigilanza. Os anexos saem por ServeAttachment.php e baixam normal.','https://www.regione.molise.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/18077',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'HTML + PDF por ServeAttachment.php','MOLISE. Pagina ''Bollettini - Comunicati fitosanitari''. Lista os Comunicati fitosanitari de 2026 (n.1 a n.5) e os Bollettini di vigilanza. Os anexos saem por ServeAttachment.php e baixam normal.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('ITALIA INTEIRA. Diretorio com a URL canonica do boletim de todas as 20 regioes e ~100 provincias. E o mapa que resolve a descoberta de fonte de uma vez. Salvo em C:\eame-sintonia\data\samples\IT-BOLLE','https://fitogest.imagelinenetwork.com/it/pan-piano-uso-sostenibile/bollettini-tecnici-provinciali-zonali',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'HTML','ITALIA INTEIRA. Diretorio com a URL canonica do boletim de todas as 20 regioes e ~100 provincias. E o mapa que resolve a descoberta de fonte de uma vez. Salvo em C:\eame-sintonia\data\samples\IT-BOLLETTINI-VPN-2026\IT-DIRETORIO-NACIONAL-BOLETINS-FITOGEST.json') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('SICILIA. O corpo real do boletim de difesa do SIAS. A pagina de entrada (frameset_difesa.htm) e um frameset antigo e nao mostra nada; o conteudo esta neste arquivo, cujo NOME carrega a data. Serve com','http://www.sias.regione.sicilia.it/corpo_difesa_20190722.htm',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'HTML dentro de frameset (ISO-8859-1)','SICILIA. O corpo real do boletim de difesa do SIAS. A pagina de entrada (frameset_difesa.htm) e um frameset antigo e nao mostra nada; o conteudo esta neste arquivo, cujo NOME carrega a data. Serve como prova de que o canal parou em 22/07/2019.') on conflict (url_base) do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais, periodicidade, formato, observacao) values ('SARDEGNA. Arquivo dos notiziari fitosanitari da Agenzia Laore.','https://www.agenzialaore.it/servizionline/notiziarifitosanitari.nsf/xpNotiziariViewArchivio.xsp',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT',NULL,'XPages/Domino','SARDEGNA. Arquivo dos notiziari fitosanitari da Agenzia Laore.') on conflict (url_base) do nothing;
