insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione del Veneto – U.O. Fitosanitario – Bollettino fitosanitario VITE n. 20','https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d' or 'https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d' like url_base||'%' order by length(url_base) desc limit 1),'O Servizio Fitosanitario do Veneto declara que as variedades de maturacao media atingiram a plena maturacao e estao em colheita, e as tardias seguem para a plena maturacao, com cerca de uma semana de antecipacao em relacao a 2025.',coalesce('2026-08-27'::date,'2026-09-02'),'Veneto','REGIONAL',ARRAY['VITE']::text[],true,'BBCH 85-89 (tabela por vitigno: Pinot/Chardonnay 89; Glera 85-89; Garganega/Cabernet S. 85 em ambiente tardio e 89 em precoce)','Fase fenologica: Le varietà a media maturazione hanno raggiunto la loro piena maturazione e sono in corso di raccolta. Le varietà tardive (ad es. i Rabosi, ecc.) proseguono il processo di addolcimento degli acini verso la piena maturazione. Si conferma anche per quest''ultime l''anticipo di circa una settimana rispetto alla stagione scorsa.','https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione del Veneto – U.O. Fitosanitario – Bollettino fitosanitario VITE n. 20','https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d' or 'https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d' like url_base||'%' order by length(url_base) desc limit 1),'O mesmo boletim do Veneto recomenda continuar os controles de plantas com Giallumi e decapita-las a espera da erradicacao outono-invernal, conforme o Decreto de Lotta Obbligatoria vigente.',coalesce('2026-08-27'::date,'2026-09-02'),'Veneto','REGIONAL',ARRAY['VITE']::text[],true,NULL,'Flavescenza dorata: Aldilà delle popolazioni del vettore, come sempre, si raccomanda di continuare ad eseguire periodicamente i controlli sulla presenza di piante colpite da Giallumi e di capitozzarle prontamente in attesa dell''estirpazione autunno-invernale, come stabilito dal vigente Decreto di Lotta Obbligatoria contro la Flavescenza dorata.','https://www.regione.veneto.it/documents/11979050/14345303/Bollettino_vite_20_270826.pdf/bac2bf94-b6c1-46d6-a608-1ff9cb82264d','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione del Veneto – U.O. Fitosanitario – Bollettino fitosanitario OLIVO n. 29','https://www.regione.veneto.it/documents/11979050/14331610/Olivicolo_2026_29.pdf/bdef0eb2-2857-4cd6-b2b1-9ac18eba2c83',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.veneto.it/documents/11979050/14331610/Olivicolo_2026_29.pdf/bdef0eb2-2857-4cd6-b2b1-9ac18eba2c83' or 'https://www.regione.veneto.it/documents/11979050/14331610/Olivicolo_2026_29.pdf/bdef0eb2-2857-4cd6-b2b1-9ac18eba2c83' like url_base||'%' order by length(url_base) desc limit 1),'O boletim olivicola do Veneto de 02/09/2026 declara a fase ''inolizione – inicio de invaiatura'' e da percentual de infestacao ativa de mosca por areal.',coalesce('2026-09-02'::date,'2026-09-02'),'Veneto','REGIONAL',ARRAY['OLIVO']::text[],true,'3–4% de infestacao (mesmo valor declarado em Alto lago di Garda, Medio e basso lago di Garda, Entroterra gardesano, Colline veronesi Nord/Centrali/Sud, Colli Berici, Colli Euganei)','Bollettino n. 29 del 02/09/2026 – FENOLOGIA E STATO PRODUTTIVO – Inolizione – inizio invaiatura.','https://www.regione.veneto.it/documents/11979050/14331610/Olivicolo_2026_29.pdf/bdef0eb2-2857-4cd6-b2b1-9ac18eba2c83','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione del Veneto – U.O. Fitosanitario – Bollettino fitosanitario FRUTTICOLO n. 24','https://www.regione.veneto.it/documents/11979050/14333679/Frutticolo_2026_24.pdf/1775bf60-54f5-4a7d-97f7-d4ed018700ce',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.veneto.it/documents/11979050/14333679/Frutticolo_2026_24.pdf/1775bf60-54f5-4a7d-97f7-d4ed018700ce' or 'https://www.regione.veneto.it/documents/11979050/14333679/Frutticolo_2026_24.pdf/1775bf60-54f5-4a7d-97f7-d4ed018700ce' like url_base||'%' order by length(url_base) desc limit 1),'O boletim frutticolo do Veneto declara terminada a colheita das variedades do grupo Gala e reporta terceiro voo de Cydia pomonella terminado com danos em aumento tambem em pomares de manejo integrado.',coalesce('2026-08-26'::date,'2026-09-02'),'Veneto','REGIONAL',ARRAY['MELO']::text[],true,NULL,'MELO – Fase fenologica: terminata la raccolta delle varietà del gruppo Gala. […] Cydia pomonella: terzo volo terminato. Presenza di danni in aumento anche nei frutteti a gestione integrata. L''aggressività del fitofago appare, quest''anno, particolarmente elevata.','https://www.regione.veneto.it/documents/11979050/14333679/Frutticolo_2026_24.pdf/1775bf60-54f5-4a7d-97f7-d4ed018700ce','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione del Veneto – U.O. Fitosanitario – Bollettino fitosanitario ORTICOLO n. 22','https://www.regione.veneto.it/documents/11979050/14337132/Orticolo_2026_22.pdf/da94340c-e810-41b4-ab76-eafbf8a72edd',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.veneto.it/documents/11979050/14337132/Orticolo_2026_22.pdf/da94340c-e810-41b4-ab76-eafbf8a72edd' or 'https://www.regione.veneto.it/documents/11979050/14337132/Orticolo_2026_22.pdf/da94340c-e810-41b4-ab76-eafbf8a72edd' like url_base||'%' order by length(url_base) desc limit 1),'O boletim horticola do Veneto reporta chuvas na semana 17–23 de agosto que criaram condicoes ideais para novas infeccoes de Peronospora e Alternaria em tomate industrial, e recomenda tratamento nos lotes com colheita prevista em 25–30 dias.',coalesce('2026-08-26'::date,'2026-09-02'),'Veneto','REGIONAL',ARRAY['POMODORO']::text[],true,NULL,'POMODORO DA INDUSTRIA – Nella settimana dal 17 al 23 agosto si sono verificate precipitazioni sia all''inizio sia alla fine del periodo. L''umidità fogliare prolungata e l''abbassamento termico hanno creato le condizioni ideali per lo sviluppo di nuove infezioni di Peronospora e Alternaria. Si consiglia di eseguire un trattamento con Cimoxanil e Rame nei lotti in cui la raccolta è prevista tra 25-30 giorni.','https://www.regione.veneto.it/documents/11979050/14337132/Orticolo_2026_22.pdf/da94340c-e810-41b4-ab76-eafbf8a72edd','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione del Veneto – Bollettini fitosanitari 2026 (indice)','https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026' or 'https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026' like url_base||'%' order by length(url_base) desc limit 1),'O boletim Colture Erbacee do Veneto (a fonte que cobriria milho e soja) tem apenas dois numeros em 2026, o ultimo em 05/06/2026 — nao ha edicao de agosto nem de setembro.',coalesce('2026-06-05'::date,'2026-09-02'),'Veneto','REGIONAL',ARRAY['SOIA / MAIS']::text[],true,NULL,'Bollettino erbacee ed industriali — N°02 del 05/06/2026; N°01 del 06/03/2026','https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026','HISTORICAL') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Fondazione Edmund Mach – Centro Trasferimento Tecnologico – Bollettino Difesa Integrata di Base N.25','https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf' or 'https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf' like url_base||'%' order by length(url_base) desc limit 1),'A Fondazione Edmund Mach declara, para o fundovale trentino, estadio de engrossamento de frutinhos com diametro medio de 75–80 mm em Golden Delicious e crescimento de cerca de 0,20 mm por dia.',coalesce('2026-08-28'::date,'2026-09-02'),'Trentino (Provincia autonoma di Trento)','PROVINCIAL',ARRAY['MELO']::text[],true,'75–80 mm (fundovale); 73–78 mm nas zonas de colina precoces e 70–73 mm nas tardias','Zone di fondovalle – Stadio fenologico: Siamo allo stadio fenologico di ingrossamento frutticini, il diametro medio per la varietà Golden D. è di circa 75-80 mm con un accrescimento medio di circa 0,20 mm al giorno.','https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Fondazione Edmund Mach – Centro Trasferimento Tecnologico – Bollettino Difesa Integrata di Base N.25','https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf' or 'https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf' like url_base||'%' order by length(url_base) desc limit 1),'No mesmo boletim trentino, a vindima esta em curso e antecipada em relacao ao ano anterior, e os sintomas de flavescencia dourada estao bem visiveis.',coalesce('2026-08-28'::date,'2026-09-02'),'Trentino (Provincia autonoma di Trento)','PROVINCIAL',ARRAY['VITE']::text[],true,NULL,'VITE – Stadio fenologico: Proseguono le vendemmie, in anticipo rispetto allo scorso anno. Flavescenza dorata: Sono ben visibili i sintomi di fitoplasmosi (flavescenza dorata), si ribadisce l''importanza di un attento e costante monitoraggio dei vigneti e di una tempestiva eliminazione delle piante sintomatiche.','https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Fondazione Edmund Mach – Centro Trasferimento Tecnologico – Bollettino Difesa Integrata di Base N.25','https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf' or 'https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf' like url_base||'%' order by length(url_base) desc limit 1),'O boletim trentino tambem cobre olivo: endocarpo da drupa endurecido e frutos em crescimento por distensao celular, fase em que as drupas passam a ser receptivas a mosca.',coalesce('2026-08-28'::date,'2026-09-02'),'Trentino (Provincia autonoma di Trento)','PROVINCIAL',ARRAY['OLIVO']::text[],true,NULL,'OLIVO – Stadio fenologico: L''olivo presenta l''endocarpo della drupa indurito e i frutti si stanno accrescendo per distensione cellulare. Insetti: Da indurimento del nocciolo le drupe non sono più sensibili alle punture trofiche della cimice asiatica, ma diventano ricettive agli attacchi della mosca dell''olivo.','https://ctt.fmach.it/ocmultibinary/download/2219/54197/232/fea9dafb6d164f6951ce645995a35f9d.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARSAC – Bollettino agrometeorologico e fitosanitario, settimana 36','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026' or 'https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/' like url_base||'%' order by length(url_base) desc limit 1),'A ARSAC declara que todos os olivais observados na Calabria completaram o endurecimento do caroco e alguns iniciaram a invaiatura, com temperaturas altas inibindo a mosca e umidade alta favorecendo infeccoes fungicas tardias.',coalesce('2026-09-02'::date,'2026-09-02'),'Calabria','REGIONAL',ARRAY['OLIVO']::text[],true,NULL,'Olivo: tutti gli oliveti osservati hanno completato l''indurimento nocciolo ed alcuni hanno iniziato l''invaiatura. Le temperature alte hanno inibito gli attacchi di mosca, l''umidità molto alta ha favorito lo sviluppo di tardive infezioni fungine come l''occhio di pavone','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARSAC – Bollettino agrometeorologico e fitosanitario, settimana 36','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026' or 'https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/' like url_base||'%' order by length(url_base) desc limit 1),'Na Calabria a vindima ja comecou em diversos vinhedos, e a costa jonica meridional registra cicadelas, com a cicalina verde da vite responsavel pelas infestacoes mais graves.',coalesce('2026-09-02'::date,'2026-09-02'),'Calabria','REGIONAL',ARRAY['VITE']::text[],true,NULL,'Vite: in diversi vigneti si è iniziata la vendemmia. Si segnala nelle aree della costa ionica meridionale la presenza delle cicaline, in particolare la cicalina verde della vite è responsabile delle infestazioni più gravi.','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARSAC – Bollettino agrometeorologico e fitosanitario, settimana 36','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026' or 'https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/' like url_base||'%' order by length(url_base) desc limit 1),'Em toda a Calabria os citros estao em engrossamento de frutos, com mosca-do-mediterraneo acima do limiar de intervencao em Valencia na area 7 (Tirreno Reggino).',coalesce('2026-09-02'::date,'2026-09-02'),'Calabria','REGIONAL',ARRAY['AGRUMI']::text[],true,NULL,'Agrumi: in tutta la regione ci troviamo alla fase di ingrossamento dei frutti. Su alcuni agrumeti si segnala la presenza della mosca mediterranea della frutta, in particolare su Valencia in area 7, si segnalando superamenti delle soglie d''intervento, con presenze critiche di questo parassita','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARSAC – Bollettino agrometeorologico e fitosanitario, settimana 35','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026' or 'https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026/' like url_base||'%' order by length(url_base) desc limit 1),'Na semana anterior (25/08 a 01/09), a ARSAC declarou mais de 90% dos vinhedos observados em fase de maturacao, com infestacoes de cicadela por vezes graves atribuidas a reducao de biodiversidade e a substituicao de inseticidas por confusao sexual.',coalesce('2026-08-25'::date,'2026-09-02'),'Calabria','REGIONAL',ARRAY['VITE']::text[],true,'mais de 90% dos vinhedos observados','In oltre il 90% dei vigneti osservati la coltura si trova nella fase fenologica di maturazione, mentre dal punto di vista fitopatologico, si osservano infestazioni di cicalina anche gravi, in buona parte dei vigneti monitorati.','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Campania – UOS 207.03.03 Difesa delle Colture, Servizio Fitosanitario Regionale – Bollettino fitosanitario della provincia di Salerno N° 24','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' or 'https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' like url_base||'%' order by length(url_base) desc limit 1),'O Servizio Fitosanitario Regionale da Campania publica boletim provincial de Salerno n.24 com tabela por empresa/variedade: vite em maturacao em Tramonti (Piedirosso) e Torchiara (Fiano), com 5 capturas de Lobesia botrana e 5 de Scaphoideus.',coalesce('2026-08-26'::date,'2026-09-02'),'Campania (provincia di Salerno)','PROVINCIAL',ARRAY['VITE']::text[],true,'5 capturas de Lobesia botrana e 5 de Scaphoideus (1 ponto, Tramonti)','COLTURA VITE — TRAMONTI, Capitignano, APICELLA P., Piedirosso, Maturazione; 5 catture di Lobesia Botrana, n.5 catture di Scafoide, n. 0 catture di Gnidiella. TORCHIARA, Stazione di Torchiara, CARDONE F., Fiano, Maturazione — Nessun rilievo','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Campania – Servizio Fitosanitario Regionale – Bollettino fitosanitario della provincia di Salerno N° 24','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' or 'https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' like url_base||'%' order by length(url_base) desc limit 1),'No mesmo boletim de Salerno, o olivo esta em ''completo indurimento nocciolo'' e ''accrescimento del frutto'', com capturas minimas de mosca em Campagna e nulas em Agropoli.',coalesce('2026-08-26'::date,'2026-09-02'),'Campania (provincia di Salerno)','PROVINCIAL',ARRAY['OLIVO']::text[],true,NULL,'COLTURA OLIVO — 1 Campagna, Località Santa Maria La Nova, Reppuccia G., Rotondella: Completo indurimento nocciolo — Minime cattura di mosca. 2 Agropoli, Palombe, Cardone F., Salella-Frantoio-Leccino: Accrescimento — Nulla','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Campania – Servizio Fitosanitario Regionale – Bollettino fitosanitario della provincia di Salerno N° 24','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' or 'https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' like url_base||'%' order by length(url_base) desc limit 1),'O boletim de Salerno registra tomate San Marzano em Sarno com a colheita em curso e 5 capturas de Tuta absoluta, zero de Helicoverpa.',coalesce('2026-08-26'::date,'2026-09-02'),'Campania (provincia di Salerno)','PROVINCIAL',ARRAY['POMODORO']::text[],true,'5 capturas de Tuta absoluta; 0 de Helicoverpa armigera (1 ponto)','COLTURA POMODORO — 1 Sarno, San Vito, Raimo Aniello, San Marzano: Prosegue la raccolta — Tuta Absoluta: n. 5 catture. Helicoverpa A. n. 0 catture','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Liguria – C.A.A.R. – Bollettino Vite n. 25','https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2' or 'https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2/' like url_base||'%' order by length(url_base) desc limit 1),'O Centro di Agrometeorologia Applicata Regionale da Liguria reporta que os acucares nao subiram de forma relevante por causa das chuvas, que as acidezes seguem caindo mais nas castas brancas, e que em diversas areas a colheita ja esta em curso.',coalesce('2026-08-27'::date,'2026-09-02'),'Liguria','REGIONAL',ARRAY['VITE']::text[],true,NULL,'Questa settimana non si è osservato un aumento rilevante della concentrazione zuccherina, anche a causa delle recenti precipitazioni, ma si continua a rilevare un progressivo calo delle acidità, generalmente più accentuato nei vitigni bianchi. In alcuni casi i valori sono già idonei alla vendemmia e in diverse aree proseguono le raccolte, anche per evitare cali troppo marcati delle acidità.','https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Liguria – C.A.A.R. – Bollettino Olivo n. 16','https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16' or 'https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16/' like url_base||'%' order by length(url_base) desc limit 1),'O boletim olivicola da Liguria de 27/08/2026 declara que o monitoramento nao mostra infestacoes relevantes em curso, apesar de a semana ter tido clima mais favoravel a mosca, com algumas situacoes de alerta.',coalesce('2026-08-27'::date,'2026-09-02'),'Liguria','REGIONAL',ARRAY['OLIVO']::text[],true,NULL,'Attualmente dalle attività di monitoraggio non emergono infestazioni rilevanti in corso, nonostante nel corso della settimana le condizioni meteo siano risultate più favorevoli all''attività della mosca. Si rilevano comunque alcune situazioni di allerta per le quali si consiglia di prestare attenzione al prossimo comunicato','https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ALSIA – Servizio di Difesa Integrata – Bollettino fitosanitario n. 16','http://www.alsia.it/opencms/export/sites/alsia/.allegati/Bollettini/Fito/Bollettino_fitosanitario_n16_20_08_2026.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='http://www.alsia.it/opencms/export/sites/alsia/.allegati/Bollettini/Fito/Bollettino_fitosanitario_n16_20_08_2026.pdf' or 'http://www.alsia.it/opencms/export/sites/alsia/.allegati/Bollettini/Fito/Bollettino_fitosanitario_n16_20_08_2026.pdf' like url_base||'%' order by length(url_base) desc limit 1),'A ALSIA publica boletim fitossanitario do Metapontino n.16 com a fase fenologica no cabecalho de cada cultura: agrumi em engrossamento de fruto, pessego entre engrossamento e maturacao, ameixeira em invaiatura-maturacao, vite em maturacao e olivo em engrossamento de drupas.',coalesce('2026-08-20'::date,'2026-09-02'),'Basilicata (areal Metapontino)','AREAL',ARRAY['VITE / OLIVO / AGRUMI / PESCO / SUSINO']::text[],true,NULL,'AGRUMI: ingrossamento frutto — PESCO: ingrossamento frutto-invaiatura-maturazione — SUSINO: invaiatura-maturazione — VITE: maturazione — OLIVO: ingrossamento drupe','http://www.alsia.it/opencms/export/sites/alsia/.allegati/Bollettini/Fito/Bollettino_fitosanitario_n16_20_08_2026.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Ente Nazionale Risi – Bollettino Oristano','https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119121&IDc=784',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119121&IDc=784' or 'https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119121&IDc=784' like url_base||'%' order by length(url_base) desc limit 1),'O Ente Nazionale Risi publica boletim semanal para Oristano (Sardegna) dizendo que o risco de brusone na panicula se mantem baixo, com dados da estacao de Massama.',coalesce('2026-08-27'::date,'2026-09-02'),'Sardegna (areal de Oristano)','AREAL',ARRAY['RISO']::text[],true,'Massama: temp. media 29 °C, max 39 °C, min 20,7 °C, UR 62%, bagnatura foliar 1800 min, precipitacao 2,2 mm','ENTE NAZIONALE RISI — Data 27/08/2026 — Bollettino AgroMeteorologico — Dal 20/08/2026 al 27/08/2026 — Oristano - Note Tecniche — Il rischio di brusone sulla pannocchia si mantiene basso.','https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119121&IDc=784','CURRENT') on conflict do nothing;
