insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119110&IDc=784' or 'https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119110&IDc=784' like url_base||'%' order by length(url_base) desc limit 1),'O mesmo servico publica boletim para a Lombardia com cinco estacoes (Bereguardo, Castello d''Agogna, Landriano, Mede, Zinasco) indicando ainda baixo risco de brusone na panicula.',coalesce('2026-08-27'::date,'2026-09-02'),'Lombardia','REGIONAL',ARRAY['RISO']::text[],true,'5 estacoes; temperaturas medias 23,1–23,7 °C, UR 77–79%, precipitacao 22,2–46,5 mm','Lombardia - Note Tecniche — I modelli indicano ancora un basso rischio di brusone sulla pannocchia sul territorio.','https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119110&IDc=784','CURRENT') on conflict do nothing;
