insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119115&IDc=784' or 'https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119115&IDc=784' like url_base||'%' order by length(url_base) desc limit 1),'O Ente Nazionale Risi tambem emite boletim para Mantova/Verona, o que toca o territorio do Veneto pelo lado veronese.',coalesce('2026-08-27'::date,'2026-09-02'),'Veneto (Verona) / Lombardia (Mantova)','REGIONAL',ARRAY['RISO']::text[],true,'Bigarello (MN): temp. media 23,7 °C, max 31,8 °C, UR 77%, precipitacao 34,8 mm','Mantova/Verona - Note Tecniche — Il rischio di brusone sulla pannocchia si mantiene basso.','https://www.enterisi.it/servizi/funzioni/download.aspx?ID=119115&IDc=784','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('CREA AA / Rete PAC – Rete Rurale Nazionale – Bollettino fenologico del 27 agosto 2026','https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898',ARRAY['BOLETIM_FITOSSANITARIO','CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898' or 'https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898' like url_base||'%' order by length(url_base) desc limit 1),'O boletim fenologico nacional do CREA / Rete Rurale de 27/08/2026 da a carta de analise do olivo por macroarea, nomeando explicitamente Sardegna e Sicilia — as duas ilhas que nao tinham nenhum boletim regional lido por nos.',coalesce('2026-08-27'::date,'2026-09-02'),'Italia (nacional, com detalhe por macroarea incluindo Sicilia e Sardegna)','AREAL',ARRAY['OLIVO']::text[],true,'BBCH 73 a 79 conforme a macroarea; 15 sitios de levantamento em toda a Italia','Al Sud il quadro è variabile, con fasi comprese tra la BBCH 75 e BBCH 77. Nelle Isole la situazione è differenziata: in Sardegna il riferimento è la BBCH 75, con la BBCH 77 lungo le coste; in Sicilia le fasce costiere sono invece ancora in fase BBCH 75 e le aree interne in fase BBCH 73, drupe al 30% delle dimensioni finali.','https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('CREA AA / Rete PAC – Rete Rurale Nazionale – Bollettino fenologico del 27 agosto 2026','https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898',ARRAY['BOLETIM_FITOSSANITARIO','CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898' or 'https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898' like url_base||'%' order by length(url_base) desc limit 1),'O mesmo boletim nacional da a fenologia da vite (cv Cabernet sauvignon): no Norte invaiatura generalizada em fase 85, no Centro proxima do fim com setores ja em maturacao de colheita, e no Sul e nas Ilhas quadro avancado e uniforme na fase 83.',coalesce('2026-08-27'::date,'2026-09-02'),'Italia (nacional, macroareas Nord / Centro / Sud e Isole)','MACROAREA',ARRAY['VITE']::text[],true,'BBCH 83 a 89 conforme macroarea; apenas 3 sitios de levantamento nesta semana','Al Nord l''invaiatura è generalizzata su tutta la pianura padana ed è ormai in fase avanzata, con il quadro attestato sulla fase 85, fine invaiatura, e margini pedecollinari ancora all''inizio invaiatura. […] Al Sud e nelle Isole il quadro è avanzato e piuttosto uniforme, con la fase 83 diffusa, e alcuni settori che hanno raggiunto la maturazione di raccolta.','https://www.reterurale.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/27898','CURRENT') on conflict do nothing;
