insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='http://www.sias.regione.sicilia.it' or 'http://www.sias.regione.sicilia.it/' like url_base||'%' order by length(url_base) desc limit 1),'O SIAS (Servizio Informativo Agrometeorologico Siciliano), a fonte que publicaria os boletins de difesa fitosanitaria da Sicilia, nao respondeu nem em HTTPS nem em HTTP.',coalesce('2026-09-02'::date,'2026-09-02'),'Sicilia','REGIONAL','{}',true,NULL,'connect ECONNREFUSED 93.41.160.6:443 — curl: (28) Failed to connect to www.sias.regione.sicilia.it:80 after 21096 ms: Could not connect to server','http://www.sias.regione.sicilia.it/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Siciliana – Dipartimento Agricoltura – Servizio Fitosanitario Regionale – Difesa fitosanitaria','https://www.regione.sicilia.it/istituzioni/regione/strutture-regionali/assessorato-agricoltura-sviluppo-rurale-pesca-mediterranea/dipartimento-agricoltura/servizi/servizio-fitosanitario-regionale/difesa-fitosanitaria',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
