insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Abruzzo – AgroAmbiente – Bollettini Difesa Integrata','https://agroambiente.regione.abruzzo.it/node/3',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://agroambiente.regione.abruzzo.it/node/3' or 'https://agroambiente.regione.abruzzo.it/node/3' like url_base||'%' order by length(url_base) desc limit 1),'A pagina ''Bollettini'' da plataforma AgroAmbiente da Regione Abruzzo abre e lista 2026 inteiro, mas todas as entradas de 2026 sao ''Agrometeo'' e a pagina de cada uma contem apenas duas imagens (mapa agrometeo e indice de Winkler) — nao ha boletim de difesa integrata com fenologia em 2026.',coalesce('2026-09-01'::date,'2026-09-02'),'Abruzzo','REGIONAL','{}',true,NULL,'Agrometeo 1-09-2026 — Bollettino AgroMeteo — Martedì, Settembre 1, 2026 [conteudo: sites/default/files/Agrometeo20260901.JPG e Winkler20260901.JPG]','https://agroambiente.regione.abruzzo.it/node/3','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('AgroMeteoPuglia – ARIF Puglia – Bollettini','https://www.agrometeopuglia.it/bollettini',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.agrometeopuglia.it/bollettini' or 'https://www.agrometeopuglia.it/bollettini' like url_base||'%' order by length(url_base) desc limit 1),'O AgroMeteoPuglia/ARIF — a fonte natural para trigo duro na maior regiao produtora — declara na propria pagina de boletins que desde 2018 nao redige mais a secao de fitopatologia e que os boletins territoriais nao estao mais disponiveis.',coalesce('2018-04-11'::date,'2026-09-02'),'Puglia','REGIONAL',ARRAY['FRUMENTO DURO']::text[],true,NULL,'Dal Notiziario Agrometeorologico Regionale n. 15 del 11/04/2018, la sezione dedicata alla Fitopatologia non viene più redatta poiché le competenze sono in fase di trasferimento all''Agenzia Regionale Attività Irrigue e Forestali (ARIF), come stabilito dalla Legge Regionale n. 33 del 07/08/2017 e ss.mm.ii., così come non sono più disponibili i bollettini territoriali.','https://www.agrometeopuglia.it/bollettini','CURRENT') on conflict do nothing;
