insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.ismeamercati.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/960' or 'https://www.ismeamercati.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/960' like url_base||'%' order by length(url_base) desc limit 1),'VITE / VINHO','ITALIA (media nacional de origem)','NACIONAL','PRECO','Vini bianchi comuni 4,45 (variacao sobre a semana do ano anterior -21,3%) · Vini rossi e rosati comuni 4,02 (-25,3%) · por gradacao: bianchi 12/13 graus 4,10 (-28,7%), rossi 12/13 graus 4,09 (-30,8%)',NULL,'EUR por Ettogrado (euro por hectolitro por grau alcoolico)','2026-8-4 (ano-mes-semana, na notacao da propria fonte)',coalesce('2026-09-02 (lido nesta data; a fonte data a semana, nao a publicacao)'::date,'2026-01-01'),coalesce('2026-09-02 (lido nesta data; a fonte data a semana, nao a publicacao)'::date,'2026-12-31'),'CURRENT','Prodotto | Anno-Mese-Sett. | Prezzo | Variaz. su Sett. Prec. | Variaz. su Sett. Anno Prec. — Vini bianchi comuni | 2026-8-4 | 4,45 €/Ettogrado | 0,0% | -21,3%','https://www.ismeamercati.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/960','2026-09-02 (lido nesta data; a fonte data a semana, nao a publicacao)'::date,'PRECO DE VINHO NAO E PRECO DE UVA. O que o viticultor recebe pela uva e outra coisa, e essa serie nao mede. ''Ettogrado'' NAO e euro por hectolitro: e euro por hectolitro por grau alcoolico — comparar com os 61,75 EUR/HL da serie da Comissao sem converter e comparar duas unidades diferentes. NAO prova causa da queda.') on conflict do nothing;
