insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' or 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' like url_base||'%' order by length(url_base) desc limit 1),'VITE','ITALIA (nacional)','NACIONAL','AREA_PRODUCAO','uva total: area 2025 = 723,68 mil ha (era 702,67 em 2021), producao 2025 = 7.681,2 mil t | uva para vinho: area 2025 = 672,66 mil ha, producao 2025 = 6.679,37 mil t',NULL,'MIL HECTARES e MIL TONELADAS','2021 a 2025 (2026 ainda sem valor)',coalesce('2026-08-28'::date,'2026-01-01'),coalesce('2026-08-28'::date,'2026-12-31'),'HISTORICAL','crops=W1000 ''Grapes'' AR_THS_HA IT 2025 = 723.68 ; crops=W1100 ''Grapes for wines'' AR_THS_HA IT 2025 = 672.66','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021','2026-08-28'::date,'NAO prova que nao va encolher: o efeito do preco baixo de 2024 e 2025 sobre arranquio de vinhedo, se houver, aparece com atraso e nao esta nesta serie. O rendimento (YLD) vem vazio para uva neste dataset.') on conflict do nothing;
