insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://agronotizie.imagelinenetwork.com/agricoltura-economia-politica/2025/12/23/barbabietola-da-zucchero-fissato-il-prezzo-per-il-2026/88686' or 'https://agronotizie.imagelinenetwork.com/agricoltura-economia-politica/2025/12/23/barbabietola-da-zucchero-fissato-il-prezzo-per-il-2026/88686' like url_base||'%' order by length(url_base) desc limit 1),'BARBABIETOLA DA ZUCCHERO','filiera Coprob (Italia)','NACIONAL','PRECO','ate 97 EUR/t para a barbabietola biologica e ate 56 EUR/t para a convencional, aiuti accoppiati JA INCLUIDOS',NULL,'EUR por tonelada de barbabietola, com ajuda acoplada incluida','campanha 2026 (anunciado antes das semeaduras)',coalesce('2025-12-23'::date,'2026-01-01'),coalesce('2025-12-23'::date,'2026-12-31'),'CURRENT','Il prezzo e stato reso noto, grazie alla delibera all''unanimita del Consiglio di Amministrazione di Coprob Italia Zuccheri, che ha comunicato la conferma del prezzo industriale gia fissato nel 2025. Ovvero fino ad un massimo di 97 euro per tonnellata (compresi gli aiuti accoppiati) per la barbabietola a coltivazione biologica e fino a 56 euro per tonnellata (compresi gli aiuti accoppiati) per la barbabietola convenzionale.','https://agronotizie.imagelinenetwork.com/agricoltura-economia-politica/2025/12/23/barbabietola-da-zucchero-fissato-il-prezzo-per-il-2026/88686','2025-12-23'::date,'''FINO AD UN MASSIMO DE'' NAO E O PRECO PAGO: e um teto. O agricultor pode receber menos conforme grau polarimetrico e outras clausulas que a materia nao detalha. NAO cobre a Italia inteira, so a filiera Coprob. E a fala do presidente sobre ''taglio di mezzi di difesa'' e OPINIAO DE DIRIGENTE, nao medicao — NAO CONVERTER EVENTO REGULATORIO EM OPORTUNIDADE COMERCIAL.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat apro_cpsh1','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' or 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' like url_base||'%' order by length(url_base) desc limit 1),'BARBABIETOLA DA ZUCCHERO','ITALIA (nacional)','NACIONAL','AREA_PRODUCAO_RENDIMENTO','area: 2024 = 29,23 · 2025 = 18,68 · 2026 = 19,41 mil ha (queda de 33,6% de 2024 para 2026) | producao: 2024 = 1.534,44 · 2025 = 914,03 mil t | rendimento 2025 = 48,93 t/ha',NULL,'MIL HECTARES · MIL TONELADAS de raiz · TONELADAS POR HECTARE','2021 a 2026',coalesce('2026-08-28'::date,'2026-01-01'),coalesce('2026-08-28'::date,'2026-12-31'),'HISTORICAL','crops=R2000 ''Sugar beet (excluding seed)'' AR_THS_HA IT: 2021=27.91, 2022=25.79, 2023=23.49, 2024=29.23, 2025=18.68, 2026=19.41','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021','2026-08-28'::date,'NAO prova causa. NAO prova que a queda continua em 2027. E area de barbabietola NAO E AREA TRATADA. A producao de 2026 ainda nao foi publicada, entao a queda de 2025 pode ser de area, de rendimento ou das duas coisas — a serie mostra as duas caindo juntas, mas nao explica.') on conflict do nothing;
