insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.ec.europa.eu/agrifood/api/sugar/prices?memberStateCodes=IT' or 'https://www.ec.europa.eu/agrifood/api/sugar/prices?memberStateCodes=IT' like url_base||'%' order by length(url_base) desc limit 1),'BARBABIETOLA / ACUCAR','UNIAO EUROPEIA, por regiao de preco 1, 2 e 3','REGIONAL','PRECO','EU Average 501,4009 · Region 1 506,0622 · Region 2 494,0552 · Region 3 547,2198',NULL,'EUR por tonelada de acucar branco','junho de 2026 (ym = 2026/06), contrato tipo ''Monthly data''',coalesce('2026-07-30 (data impressa no PDF oficial da mesma serie)'::date,'2026-01-01'),coalesce('2026-07-30 (data impressa no PDF oficial da mesma serie)'::date,'2026-12-31'),'CURRENT','{"sugarRegion": "Region 3", "price": "547.2198", "unit": "Tonne", "ym": "2026/06", "marketingYear": "2025/2026", "marketingYearMonth": "Jun", "weight": 66282.86, "contractType": "Monthly data"}','https://www.ec.europa.eu/agrifood/api/sugar/prices?memberStateCodes=IT','2026-07-30 (data impressa no PDF oficial da mesma serie)'::date,'PRECO DE ACUCAR BRANCO NAO E PRECO DE BARBABIETOLA — sao dois elos diferentes da cadeia; o que o bieticultor recebe e o preco Coprob de 56/97 EUR/t. NAO SEI quais paises compoem a Regiao 3: nem a API nem o PDF oficial nomeiam a composicao, e a soma de Italia (140.284 t) mais Espanha (417.434 t) nao fecha o total da Regiao 3 em 2024/25 (708.228 t), entao ha pelo menos um terceiro pais dentro. REGIAO NAO REPRESENTA O PAIS.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('European Commission — Short-term outlook for EU agricultural markets, edicao de verao 2026','https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en' or 'https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en' like url_base||'%' order by length(url_base) desc limit 1),'BARBABIETOLA DA ZUCCHERO','UNIAO EUROPEIA','REGIONAL','OUTLOOK','sem numero para acucar; o texto da o cereal em 273,7 milhoes de t e diz que acucar declina',NULL,'texto qualitativo','campanha 2026/27',coalesce('2026-07-03'::date,'2026-01-01'),coalesce('2026-07-03'::date,'2026-12-31'),'OUTLOOK','Production of protein crops is forecast to slightly decline but to remain above average, while EU sugar production may decline due to lower sugar beet area.','https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en','2026-07-03'::date,'UE NAO E ITALIA. O proprio documento avisa que ''this report does not take into account the ongoing heatwaves which are severely affecting farmers all across Europe'' — ou seja, o dado e anterior as ondas de calor de julho e agosto de 2026. E a edicao de outono, que corrigiria isso, ainda nao tinha saido em 02/09/2026.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('European Commission — Agri-food Data Portal, fruitAndVegetable/pricesSupplyChain','https://www.ec.europa.eu/agrifood/api/fruitAndVegetable/pricesSupplyChain?memberStateCodes=IT&products=Apples',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.ec.europa.eu/agrifood/api/fruitAndVegetable/pricesSupplyChain?memberStateCodes=IT&products=Apples' or 'https://www.ec.europa.eu/agrifood/api/fruitAndVegetable/pricesSupplyChain?memberStateCodes=IT&products=Apples' like url_base||'%' order by length(url_base) desc limit 1),'MELO','ITALIA — o proprio campo market diz ''National average (IT)''','REGIONAL','PRECO','todas as variedades 100,18 · Golden delicious 100,18 · Braeburn 122,00 (junho) · Fuji 103,44 (junho) · Granny smith 101,75 (junho) · Red delicious e outras vermelhas 95,00 (junho). Compra do varejo em julho: 164,76',NULL,'EUR por 100 kg','semana de 20 a 26/07/2026 (a mais recente publicada); mes de julho e junho de 2026 para as demais',coalesce('2026-09-02 (data da leitura)'::date,'2026-01-01'),coalesce('2026-09-02 (data da leitura)'::date,'2026-12-31'),'CURRENT','20/07/2026 -> 26/07/2026 €100.18 €/100Kg calc= Y reg= Y market= National average (IT)','https://www.ec.europa.eu/agrifood/api/fruitAndVegetable/pricesSupplyChain?memberStateCodes=IT&products=Apples','2026-09-02 (data da leitura)'::date,'A SERIE SEMANAL NAO E SEMANAL DE VERDADE: o campo isCalculated vem ''Y'' e o mesmo valor se repete por quatro semanas seguidas (04/05 a 31/05 todas 104,37; 29/06 a 26/07 todas 100,18) — e um valor mensal espalhado pelas semanas. Tratar como quatro observacoes independentes e contar a mesma coisa quatro vezes. NAO e preco recebido pelo produtor: ''Ex-packaging station'' e depois da central de embalagem. O vao de 26/07 a 02/09 NAO e serie parada: em 2025 a serie seguia em agosto, entao e atraso de publicacao.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Fruitbook Magazine, sobre dados Assomela, CSO Italy e WAPA apresentados no Prognosfruit','https://www.fruitbookmagazine.it/mele-raccolto-europeo-ai-minimi-da-9-anni-italia-in-calo-del-2-ma-prospettive-positive',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.fruitbookmagazine.it/mele-raccolto-europeo-ai-minimi-da-9-anni-italia-in-calo-del-2-ma-prospettive-positive' or 'https://www.fruitbookmagazine.it/mele-raccolto-europeo-ai-minimi-da-9-anni-italia-in-calo-del-2-ma-prospettive-positive/' like url_base||'%' order by length(url_base) desc limit 1),'MELO','UNIAO EUROPEIA e ITALIA','NACIONAL','OUTLOOK','UE 9,5 milhoes de t (-16% sobre 2025, -14% sobre a media de tres anos, a menor colheita em nove anos) · Italia 2,27 milhoes de t (-2%) · Polonia 2,7 milhoes de t (-30%)',NULL,'MILHOES DE TONELADAS','campanha 2026/27',coalesce('2026-08-07'::date,'2026-01-01'),coalesce('2026-08-07'::date,'2026-12-31'),'OUTLOOK','Per l''Unione europea la produzione di mele e stimata in 9,5 milioni di tonnellate, con una flessione del 16% rispetto al 2025 e del 14% rispetto alla media degli ultimi tre anni. Si tratta del raccolto piu basso degli ultimi nove anni.','https://www.fruitbookmagazine.it/mele-raccolto-europeo-ai-minimi-da-9-anni-italia-in-calo-del-2-ma-prospettive-positive/','2026-08-07'::date,'E PREVISAO, feita em agosto, antes da colheita fechar — nao e producao medida. A materia e de imprensa especializada citando Assomela e WAPA; NAO li o comunicado primario da Assomela nem a tabela WAPA. O texto tambem diz que faltam ''strumenti per fronteggiare patogeni e fitopatie'' — isso e LEITURA DE ASSOCIACAO, nao medicao de perda por doenca, e NAO deve virar oportunidade comercial automatica.') on conflict do nothing;
