insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' or 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' like url_base||'%' order by length(url_base) desc limit 1),'MELO','ITALIA (nacional)','NACIONAL','AREA_PRODUCAO','area: 2021 = 54,47 · 2025 = 53,82 mil ha | producao: 2021 = 2.211,74 · 2025 = 2.412,92 mil t',NULL,'MIL HECTARES e MIL TONELADAS','2021 a 2025 (2026 sem valor)',coalesce('2026-08-28'::date,'2026-01-01'),coalesce('2026-08-28'::date,'2026-12-31'),'HISTORICAL','crops=F1110 ''Apples'' AR_THS_HA IT 2025 = 53.82 ; HPRD_HUMD_EU_THS_T IT 2025 = 2412.92','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021','2026-08-28'::date,'O campo de rendimento vem VAZIO para maca neste dataset; o ganho de produtividade e conta minha a partir de area e producao, nao numero da fonte. NAO explica se veio de variedade, de manejo, de idade do pomar ou de clima.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('AgroNotizie, autor Dario Del Bene, sobre nota de imprensa da Anicav de 30/03/2026','https://agronotizie.imagelinenetwork.com/agricoltura-economia-politica/2026/03/31/pomodoro-da-industria-siglato-al-nord-l-accordo-quadro-per-la-campagna-2026/89091',ARRAY['IMPRENSA_TECNICA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://agronotizie.imagelinenetwork.com/agricoltura-economia-politica/2026/03/31/pomodoro-da-industria-siglato-al-nord-l-accordo-quadro-per-la-campagna-2026/89091' or 'https://agronotizie.imagelinenetwork.com/agricoltura-economia-politica/2026/03/31/pomodoro-da-industria-siglato-al-nord-l-accordo-quadro-per-la-campagna-2026/89091' like url_base||'%' order by length(url_base) desc limit 1),'POMODORO DA INDUSTRIA','Bacino Nord Italia (Piacenza, Parma, Reggio Emilia, Cremona, Mantova)','REGIONAL','PRECO','137 EUR/t em 2026, contra 142,50 EUR/t em 2025 (queda de 5,50 EUR/t)',NULL,'EUR por tonelada, ja incluindo servicos e premiacoes ligadas ao momento da colheita','campanha de transformacao 2026',coalesce('2026-03-31'::date,'2026-01-01'),coalesce('2026-03-31'::date,'2026-12-31'),'CURRENT','Secondo la nota dell''Anicav "La sottoscrizione dell''Accordo, che prevede un prezzo medio di riferimento di 137 euro alla tonnellata, comprensivo di servizi e di premialita legate ai tempi di raccolta, rappresenta un importante risultato a tutela e salvaguardia dell''equilibrio e della centralita della filiera del pomodoro da industria".','https://agronotizie.imagelinenetwork.com/agricoltura-economia-politica/2026/03/31/pomodoro-da-industria-siglato-al-nord-l-accordo-quadro-per-la-campagna-2026/89091','2026-03-31'::date,'E PRECO MEDIO DE REFERENCIA, nao preco de contrato individual — o proprio texto diz que a queda de 5,50 EUR/t vem em parte de premiacoes de ate 2,50 EUR/t que em 2025 eram separadas e em 2026 foram comprimidas dentro do valor, entao a queda liquida e menor que 5,50. VALE SO PARA O NORTE: o Centro-Sul e outro bacino e outro acordo, e o proprio presidente da Anicav diz que esperava ''recuperare il dialogo di filiera anche al Centro Sud'' — nao verifiquei o desfecho. NAO e preco pago a nenhum produtor em particular.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat apro_cpsh1','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' or 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' like url_base||'%' order by length(url_base) desc limit 1),'POMODORO DA INDUSTRIA','ITALIA (nacional)','NACIONAL','AREA_PRODUCAO','industria (V3120): area 2024 = 76,86 mil ha, producao 2024 = 4.833,76 mil t (era 5.595,4 em 2021) | mesa (V3110): area 2024 = 25,94 mil ha, producao 1.189,03 mil t | total tomate: area 2026 = 108,39 mil ha',NULL,'MIL HECTARES e MIL TONELADAS','2021 a 2024 para o corte industria/mesa; 2026 so para o total',coalesce('2026-08-28'::date,'2026-01-01'),coalesce('2026-08-28'::date,'2026-12-31'),'HISTORICAL','crops=V3120 ''Tomatoes for processing'' AR_THS_HA IT 2024 = 76.86 ; HPRD_HUMD_EU_THS_T IT 2024 = 4833.76','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021','2026-08-28'::date,'O corte industria versus mesa PARA EM 2024: para 2025 e 2026 so existe o total. Usar o total de 2026 (108,39 mil ha) como se fosse industria e inflar em cerca de 30 mil ha. O campo de rendimento vem vazio para tomate.') on conflict do nothing;
