insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.ec.europa.eu/agrifood/api/rice/production?memberStateCodes=IT' or 'https://www.ec.europa.eu/agrifood/api/rice/production?memberStateCodes=IT' like url_base||'%' order by length(url_base) desc limit 1),'RISO','ITALIA','NACIONAL','AREA_PRODUCAO','Long grain A: 118.543 ha e 386.500 t · Round grain: 56.820 ha e 223.100 t · Long grain B: 46.278 ha e 172.500 t · Medium grain: 13.091 ha e 38.000 t. Soma das areas = 234.732 ha',NULL,'HECTARES e TONELADAS em equivalente de arroz lavorado (campo milledRiceEquivalentQuantity)','ano 2025',coalesce('2026-09-02 (data da leitura)'::date,'2026-01-01'),coalesce('2026-09-02 (data da leitura)'::date,'2026-12-31'),'HISTORICAL','{"year": 2025, "product": "(3) Long grain A paddy rice", "area": 118543.0, "areaUnit": "hectares", "milledRiceEquivalentQuantity": 386500.0, "riceHuskQuantity": 676913.0, "quantityUnit": "Tonnes"}','https://www.ec.europa.eu/agrifood/api/rice/production?memberStateCodes=IT','2026-09-02 (data da leitura)'::date,'A quantidade e em EQUIVALENTE DE ARROZ LAVORADO, nao em risone: o risone esta no campo riceHuskQuantity, que e maior. Trocar os dois subestima a colheita em cerca de 40%. E 2025 NAO E 2026 — a rota production nao tem 2026.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('European Commission — Agri-food Data Portal, oilseeds/prices','https://www.ec.europa.eu/agrifood/api/oilseeds/prices?memberStateCodes=IT',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.ec.europa.eu/agrifood/api/oilseeds/prices?memberStateCodes=IT' or 'https://www.ec.europa.eu/agrifood/api/oilseeds/prices?memberStateCodes=IT' like url_base||'%' order by length(url_base) desc limit 1),'SOIA','Milano, Bologna, Treviso','REGIONAL','PRECO','grao: Bologna 472,50 (semana 27/07-02/08/2026) e Milano 478,50 (20-26/07/2026) | farelo: Treviso 497,50, Milano 426,50 (24-30/08/2026) | oleo de soja bruto Milano 1.160,00 (24-30/08/2026)',NULL,'EUR por tonelada (campo unit = ''national currency/ton''; a moeda nacional da Italia e o euro)','semanas indicadas, campanha 2026/2027',coalesce('2026-09-02 (data da leitura)'::date,'2026-01-01'),coalesce('2026-09-02 (data da leitura)'::date,'2026-12-31'),'CURRENT','{"beginDate": "27/07/2026", "endDate": "02/08/2026", "price": "€472.50", "unit": "national currency/ton", "product": "Soya beans", "marketStage": "DELFIRST", "market": "Bologna", "marketingYear": "2026/2027"}','https://www.ec.europa.eu/agrifood/api/oilseeds/prices?memberStateCodes=IT','2026-09-02 (data da leitura)'::date,'O GRAO esta cinco semanas atras do FARELO: o farelo foi cotado ate 30/08 e o grao so ate 02/08. Comparar o grao de agosto com o farelo de setembro e comparar duas datas. A serie de Treviso com estagio DEPPROD (saida da producao) parou em 21/06/2026 — estagios diferentes tem vidas diferentes. O Eurostat NAO tem preco anual de soja para a Italia (campo ''02130000 Soya'' vem vazio), entao NAO ha como cruzar com serie anual independente.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat apro_cpsh1','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' or 'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021' like url_base||'%' order by length(url_base) desc limit 1),'SOIA','ITALIA (nacional)','NACIONAL','AREA_PRODUCAO_RENDIMENTO','area: 2022 = 342,53 · 2025 = 297,78 · 2026 = 301,99 mil ha | producao 2025 = 1.104,54 mil t | rendimento: 2022 = 2,75 · 2025 = 3,71 t/ha',NULL,'MIL HECTARES · MIL TONELADAS · TONELADAS POR HECTARE','2021 a 2026',coalesce('2026-08-28'::date,'2026-01-01'),coalesce('2026-08-28'::date,'2026-12-31'),'HISTORICAL','crops=I1130 ''Soya'' AR_THS_HA IT 2026 = 301.99 ; YLD_HUMD_EU_T_HA IT 2025 = 3.71','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?geo=IT&format=JSON&lang=EN&sinceTimePeriod=2021','2026-08-28'::date,'O rendimento de 2026 AINDA NAO EXISTE nesta serie — e a advertencia do JRC sobre calor e falta de agua no Norte e Centro da Italia em 2026 sugere que ele nao vai repetir 2025, mas isso e PROJECAO, nao medicao. NAO usar 3,71 t/ha como se fosse o rendimento corrente.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('European Commission Joint Research Centre — MARS crop monitoring','https://joint-research-centre.ec.europa.eu/jrc-news-and-updates/exceptionally-dry-and-hot-weather-threatens-summer-crops-2026-08-24_en',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://joint-research-centre.ec.europa.eu/jrc-news-and-updates/exceptionally-dry-and-hot-weather-threatens-summer-crops-2026-08-24_en' or 'https://joint-research-centre.ec.europa.eu/jrc-news-and-updates/exceptionally-dry-and-hot-weather-threatens-summer-crops-2026-08-24_en' like url_base||'%' order by length(url_base) desc limit 1),'TRANSVERSAL (culturas de verao: RISO, SOIA, POMODORO, BARBABIETOLA)','UNIAO EUROPEIA, com Norte e Centro da Italia nomeados na lista de impacto severo','MACROAREA','OUTLOOK','previsao de rendimento das culturas de verao da UE reduzida em ate 14% abaixo da media de cinco anos',NULL,'variacao percentual sobre a media de cinco anos','campanha 2026, boletim de agosto de 2026',coalesce('2026-08-24'::date,'2026-01-01'),coalesce('2026-08-24'::date,'2026-12-31'),'OUTLOOK','France, southern Germany, northern and central Italy, Austria, Czechia, Slovakia, Hungary and western Romania: High temperatures combined with insufficient rainfall strongly affected summer crops, particularly during flowering and yield formation. ... Yields will be significantly reduced, and crop failure is likely locally in these regions.','https://joint-research-centre.ec.europa.eu/jrc-news-and-updates/exceptionally-dry-and-hot-weather-threatens-summer-crops-2026-08-24_en','2026-08-24'::date,'CLIMA E CONDICAO, NAO PRESENCA DE DOENCA NEM PERDA MEDIDA. O texto fala de calor e deficit hidrico, e nao diz uma palavra sobre praga, doenca ou daninha — transformar isso em pressao fitossanitaria seria inventar. O numero de -14% e da UE, NAO da Italia: o comunicado NAO traz tabela de rendimento por cultura por pais, e o PDF do boletim de agosto de 2026 nao foi alcancado. ''Northern and central Italy'' NAO e regiao administrativa: nao da para dizer Lombardia ou Emilia-Romagna a partir dele.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('European Commission — Short-term outlook for EU agricultural markets, edicao de verao 2026','https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.mercado_observacao (fonte_id, crop_literal, praca, nivel, indicador, valor_texto, valor_numerico, unidade, qualidade, periodo_inicio, periodo_fim, classe, citacao_literal, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en' or 'https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en' like url_base||'%' order by length(url_base) desc limit 1),'TRANSVERSAL','UNIAO EUROPEIA','REGIONAL','INDICADOR_DE_CUSTO','sem numero; ''fertiliser affordability dropping to levels observed in 2022''',NULL,'texto qualitativo','2026',coalesce('2026-07-03'::date,'2026-01-01'),coalesce('2026-07-03'::date,'2026-12-31'),'CURRENT','In this context, producer margins remain under pressure, with fertiliser affordability dropping to levels observed in 2022. To address these concerns, the Commission''s Fertiliser Action Plan adopted in May 2026 aims to ease short-term cost pressures while bolstering long-term resilience','https://agriculture.ec.europa.eu/media/news/short-term-outlook-eu-agricultural-markets-eu-agriculture-remains-robust-amidst-uncertainties-and-2026-07-03_en','2026-07-03'::date,'E DA UE, NAO DA ITALIA. Fertilizante NAO E DEFENSIVO: nada aqui diz sobre custo de protecao de cultivo. E o pacote ja tem o indice de preco de insumo da Italia (Eurostat apri_pi_inq, ja coletado) — este registro NAO substitui aquele, so da o contexto europeu com data.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1500&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITC1&geo=ITC4&geo=ITH3',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','mais','21 regiões NUTS-2 italianas','Área e produção de milho grão por região italiana em 2024: Veneto 122,91 mil ha (24,8% da área nacional), Lombardia 115,82 mil ha (23,4%), Piemonte 115,75 mil ha (23,4%), Emilia-Romagna 51,41 mil ha (10,4%), Friuli-Venezia Giulia 33,06 mil ha (6,7%). Produção: Piemonte 1.359,36 mil t, Lombardia 1.244,30 mil t, Veneto 1.206,16 mil t. Nacional: 495,35 mil ha e 4.940,53 mil t.','nacional 495,35 mil ha / 4.940,53 mil t; 4 regiões concentram 81,9% da área','mil hectares (área) e mil toneladas (produção)','2024','HISTORICAL','"Crop production in EU standard humidity by NUTS 2 region" · crops C1500 = "Grain maize and corn-cob-mix" · strucpro AR_THS_HA = "Area (sown/harvested/production) - thousand hectares" · HPRD_HUMD_EU_THS_T = "Harvested production in EU standard humidity - thousand tonnes"','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1500&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITC1&geo=ITC4&geo=ITH3','2026-05-28'::date,'ALTA','Área plantada NÃO é demanda, NÃO é receita, NÃO é presença de praga e NÃO é presença da ADAMA. A participação é da ÁREA no total nacional, não do VALOR — o Eurostat não publica valor aqui, e eu não estimei. O dado é de 2024: não prova o que está plantado hoje (02/09/2026). Participação regional na área nacional não diz nada sobre quanto daquela área é tratada, com o quê, nem por quem.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1120&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITF4&geo=ITG1',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','frumento duro','21 regiões NUTS-2 italianas','Área e produção de trigo duro por região italiana em 2024: Puglia 338,50 mil ha (28,8% da área nacional), Sicilia 277,55 mil ha (23,6%), Basilicata 115,16 mil ha (9,8%), Marche 72,82 mil ha (6,2%), Emilia-Romagna 69,54 mil ha (5,9%). Produção: Puglia 792,76 mil t, Sicilia 767,70 mil t, Emilia-Romagna 398,95 mil t. Nacional: 1.177,44 mil ha e 3.633,97 mil t.','nacional 1.177,44 mil ha / 3.633,97 mil t; Puglia + Sicilia = 52,4% da área','mil hectares (área) e mil toneladas (produção)','2024','HISTORICAL','"Crop production in EU standard humidity by NUTS 2 region" · crops C1120 = "Durum wheat" · strucpro AR_THS_HA = "Area (sown/harvested/production) - thousand hectares"','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1120&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITF4&geo=ITG1','2026-05-28'::date,'ALTA','Área não é demanda nem receita. Produção alta por região não significa rendimento alto: a Emilia-Romagna produz 398,95 mil t em 69,54 mil ha enquanto a Basilicata produz 298,91 mil t em 115,16 mil ha — mas o rendimento por região NÃO é publicado pelo Eurostat, então dividir um pelo outro seria cálculo meu, não dado da fonte. Não prova nada sobre a safra corrente de 2026.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1110&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITH5&geo=ITH3',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','frumento tenero','21 regiões NUTS-2 italianas','Área e produção de trigo comum por região italiana em 2024: Emilia-Romagna 131,52 mil ha (25,3% da área nacional), Veneto 94,67 mil ha (18,2%), Piemonte 72,71 mil ha (14,0%), Lombardia 63,10 mil ha (12,1%), Umbria 28,90 mil ha (5,6%). Produção: Emilia-Romagna 797,30 mil t, Veneto 519,81 mil t, Piemonte 403,69 mil t. Nacional: 520,31 mil ha e 2.617,80 mil t.','nacional 520,31 mil ha / 2.617,80 mil t; 4 regiões do Norte = 69,6% da área','mil hectares (área) e mil toneladas (produção)','2024','HISTORICAL','"Crop production in EU standard humidity by NUTS 2 region" · crops C1110 = "Common wheat and spelt"','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1110&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITH5&geo=ITH3','2026-05-28'::date,'ALTA','Área não é demanda nem receita. Não prova presença de doença nem janela de aplicação. Não prova a safra 2026.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C2000&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITC1&geo=ITC4',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','riso','21 regiões NUTS-2 italianas','Área e produção de arroz por região italiana em 2024: Piemonte 117,67 mil ha (52,0% da área nacional), Lombardia 95,51 mil ha (42,2%), Emilia-Romagna 5,25 mil ha (2,3%), Sardegna 3,60 mil ha (1,6%), Veneto 3,35 mil ha (1,5%). Produção: Piemonte 791,29 mil t, Lombardia 584,44 mil t. Nacional: 226,13 mil ha e 1.448,76 mil t.','nacional 226,13 mil ha / 1.448,76 mil t; Piemonte + Lombardia = 94,2% da área','mil hectares (área) e mil toneladas (produção)','2024','HISTORICAL','"Crop production in EU standard humidity by NUTS 2 region" · crops C2000 = "Rice" · strucpro HUMD_EU_PC para arroz = 13,0% (os cereais usam 14,0%)','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C2000&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITC1&geo=ITC4','2026-05-28'::date,'ALTA','Concentração de área não prova concentração de problema, de gasto com defensivo, nem de valor. Não prova a safra 2026. A umidade padrão do arroz (13%) é diferente da dos outros cereais (14%) — comparar produção de arroz com produção de trigo em tonelada bruta não é comparação limpa.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=I1130&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITH3&geo=ITH4',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','soia','21 regiões NUTS-2 italianas','Área e produção de soja por região italiana em 2024: Veneto 160,14 mil ha (47,6% da área nacional), Friuli-Venezia Giulia 66,59 mil ha (19,8%), Lombardia 52,50 mil ha (15,6%), Emilia-Romagna 44,36 mil ha (13,2%), Piemonte 12,37 mil ha (3,7%). Produção: Veneto 552,03 mil t, Friuli-Venezia Giulia 182,35 mil t. Nacional: 336,74 mil ha e 1.125,58 mil t.','nacional 336,74 mil ha / 1.125,58 mil t; 5 regiões = 99,9% da área','mil hectares (área) e mil toneladas (produção)','2024','HISTORICAL','"Crop production in EU standard humidity by NUTS 2 region" · crops I1130 = "Soya"','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=I1130&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITH3&geo=ITH4','2026-05-28'::date,'ALTA','Área não é demanda nem receita. Zero na tabela do Eurostat é o que a fonte publicou, e não prova que não existe um hectare de soja na Puglia — prova que a fonte registrou zero naquele corte. Não prova a safra 2026.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=R2000&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITH5&geo=ITH3',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','barbabietola da zucchero','21 regiões NUTS-2 italianas','Área e produção de beterraba açucareira por região italiana em 2024: Emilia-Romagna 16,36 mil ha (56,0% da área nacional), Veneto 7,70 mil ha (26,3%), Marche 2,40 mil ha (8,2%), Lombardia 2,05 mil ha (7,0%), Piemonte 0,39 mil ha (1,3%), Friuli-Venezia Giulia 0,32 mil ha (1,1%), Umbria 0,02 mil ha (0,1%). As outras 14 regiões: 0,0. Nacional: 29,23 mil ha e 1.534,44 mil t.','nacional 29,23 mil ha / 1.534,44 mil t; apenas 7 regiões com área > 0','mil hectares (área) e mil toneladas (produção)','2024','HISTORICAL','"Crop production in EU standard humidity by NUTS 2 region" · crops R2000 = "Sugar beet (excluding seed)" · strucpro YLD_HUMD_EU_T_HA nacional = 52,5','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=R2000&time=2024&strucpro=AR_THS_HA&strucpro=HPRD_HUMD_EU_THS_T&geo=IT&geo=ITH5&geo=ITH3','2026-05-28'::date,'ALTA','Área pequena NÃO prova valor pequeno — beterraba tem rendimento de 52,5 t/ha (nacional), muito acima dos cereais, e o valor por hectare não foi medido aqui e não pode ser inferido da área. Não prova demanda nem receita. 0,0 nas outras 14 regiões é registro da fonte, não certeza sobre o mundo.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr (cálculo de conferência do Sintonia)','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1500&time=2024&strucpro=AR_THS_HA&geo=IT',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','6 culturas com dado regional completo','Itália (21 regiões NUTS-2)','Teste de completude que eu mesmo rodei: somei as 21 regiões e comparei com o total nacional que a própria fonte publica, para as 6 culturas. Milho: soma 495,38 vs nacional 495,35 (dif +0,03). Trigo duro: 1.177,45 vs 1.177,44 (+0,01). Trigo tenero: 520,32 vs 520,31 (+0,01). Beterraba: 29,24 vs 29,23 (+0,01). Arroz: 226,13 vs 226,13 (0,00). Soja: 336,74 vs 336,74 (0,00). Mesmo resultado para produção.','diferença máxima +0,03 mil ha em 12 comparações (6 culturas × área e produção)','mil hectares e mil toneladas','2024','HISTORICAL',NULL,'https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1500&time=2024&strucpro=AR_THS_HA&geo=IT','2026-05-28'::date,'ALTA','A soma bater NÃO prova que os números estão certos — prova que estão consistentes entre si dentro da mesma fonte. Se o Eurostat errar, ele erra coerente. E a conferência vale só para 2024 e só para estas 6 culturas; não vale para vite, olivo, melo nem pomodoro, que vieram de outras rotas.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — vit_t1','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/vit_t1?format=JSON&lang=en&vinetype=TOTAL&unit=HA&time=2020&geo=IT&geo=ITG1&geo=ITH3&geo=ITF4',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','vite','21 regiões NUTS-2 italianas','Área de vinhedo por região italiana em 2020, por uma rota DIFERENTE (levantamento vitivinícola, não o de lavouras): Sicilia 124.787 ha (18,1% do nacional), Veneto 95.026 ha (13,8%), Puglia 90.306 ha (13,1%), Toscana 60.462 ha (8,8%), Emilia-Romagna 53.714 ha (7,8%), Piemonte 43.942 ha (6,4%), Abruzzo 32.544 ha (4,7%). Nacional do levantamento: 688.985 ha. A soma das 21 regiões dá 688.986 ha — fecha.','nacional 688.985 ha; 7 regiões = 72,7% da área','hectares','2020','HISTORICAL','"Wine-grower holdings by production" · vinetype TOTAL = "Total area under vines (in/not yet in production)" · unit HA = "Hectare"','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/vit_t1?format=JSON&lang=en&vinetype=TOTAL&unit=HA&time=2020&geo=IT&geo=ITG1&geo=ITH3&geo=ITF4','2024-01-10'::date,'MEDIA','⚠️ NÃO é o mesmo número do outro dataset e não pode ser misturado com ele. Este levantamento dá 688.985 ha para a Itália em 2020; o apro_cpsh1 dá 703,9 mil ha para a Itália no MESMO ano de 2020 — 15 mil ha de diferença, porque são levantamentos com definições diferentes (''área total sob videira, em produção ou ainda não'' aqui, ''área de produção'' lá). Aplicar estes percentuais de 2020 sobre o total nacional de 2024 (715,79 mil ha) seria juntar duas réguas diferentes. Também: é dado de 2020, seis anos antes da data de referência — não prova o vinhedo de hoje. E área de vinhedo não é produção de uva, não é demanda e não é receita.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — orch_olives1','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/orch_olives1?format=JSON&lang=en&time=2017&age=TOTAL&density=TOTAL&unit=HA&fruitvar=OLI&geo=IT&geo=ITF&geo=ITG&geo=ITI',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','olivo','5 macro-áreas NUTS-1 (NÃO são regiões)','Área de oliveira por MACRO-ÁREA em 2017 — o corte mais fino que achei: Sud 697.125 ha (65,1% do nacional), Centro 182.501 ha (17,0%), Isole 171.684 ha (16,0%), Nord-Ovest 11.259 ha (1,1%), Nord-Est 8.265 ha (0,8%). Nacional 1.070.834 ha. A soma das 5 fecha com o nacional.','nacional 1.070.834 ha; Sud + Isole + Centro = 98,1%','hectares','2017','HISTORICAL','"Olive trees - Area by age classes (area in ha)" · fruitvar OLI = "Olive trees" · age TOTAL = "Total" · geo ITF = "Sud", ITG = "Isole", ITI = "Centro (IT)"','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/orch_olives1?format=JSON&lang=en&time=2017&age=TOTAL&density=TOTAL&unit=HA&fruitvar=OLI&geo=IT&geo=ITF&geo=ITG&geo=ITI','2024-01-10'::date,'MEDIA','⚠️ MACRO-ÁREA NÃO É REGIÃO. ''Sud'' junta Abruzzo, Molise, Campania, Puglia, Basilicata e Calabria num número só — não dá para dizer quanto é da Puglia. Pela mesma lei que diz que boletim provincial não representa a região, macro-área não representa região: transformar ''Sud 65,1%'' em ''Puglia 65,1%'' seria inventar recorte que a fonte não publica. Além disso o dado é de 2017, nove anos antes da data de referência, e a série PARA em 2017. Área de oliveira não é produção de azeite, não é demanda e não é receita.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — orch_apples1','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/orch_apples1?format=JSON&lang=en&time=2017&age=TOTAL&density=TOTAL&unit=HA&fruitvar=APD&geo=IT&geo=ITH&geo=ITC&geo=ITF',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','melo','5 macro-áreas NUTS-1 (NÃO são regiões)','Área de macieira (variedades de mesa) por MACRO-ÁREA em 2017: Nord-Est 40.546 ha (72,7% do nacional), Nord-Ovest 8.797 ha (15,8%), Sud 4.211 ha (7,5%), Centro 1.662 ha (3,0%), Isole 594 ha (1,1%). Nacional 55.810 ha.','nacional 55.810 ha; Nord-Est = 72,7%','hectares','2017','HISTORICAL','"Apple and pears trees - Area by age classes and group of varieties (area in ha)" · fruitvar APD = "Dessert apple trees" · geo ITH = "Nord-Est"','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/orch_apples1?format=JSON&lang=en&time=2017&age=TOTAL&density=TOTAL&unit=HA&fruitvar=APD&geo=IT&geo=ITH&geo=ITC&geo=ITF','2024-01-10'::date,'MEDIA','⚠️ MACRO-ÁREA NÃO É REGIÃO: ''Nord-Est 72,7%'' não permite dizer quanto é de Bolzano (que é onde a literatura aponta a concentração real). Sem o corte regional, essa atribuição seria invenção minha. Dado de 2017, série parada. ''Dessert apple trees'' é maçã de mesa: não inclui maçã para processamento, então 55.810 ha não é toda a macieira italiana — o nacional total de macieira em 2024 é 53.380 ha por outra rota, com definição diferente, e os dois números NÃO são comparáveis entre si.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr (teste de ausência)','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=V0000_S0000&time=2024&strucpro=AR_THS_HA&geo=IT&geo=ITH5&geo=ITF4',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','pomodoro','regiões italianas','Não achei NENHUMA rota pública gratuita com área ou produção de tomate por região italiana. Testei: apro_cpshr (dataset regional de lavouras) — tomate não está na lista de 79 culturas dele; o agregado que existe lá, V0000_S0000 ''Fresh vegetables (including melons) and strawberries'', devolveu 1 único valor, o nacional (419,36 mil ha em 2024), sem nenhuma região; orch_* (pomares) não cobre hortaliça; ef_lus_main (estrutura agrária NUTS-2) só tem agregados de uso da terra, não tomate.','0 valores regionais em todas as rotas testadas','—','tentativa em 02/09/2026','CURRENT','resposta da API para o agregado de hortaliças com as 21 regiões pedidas: "nvals 1" — só o registro nacional 419.36; nenhuma região retornou valor','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=V0000_S0000&time=2024&strucpro=AR_THS_HA&geo=IT&geo=ITH5&geo=ITF4','2026-09-02'::date,'ALTA','NÃO prova que o dado não existe no mundo. A rota que normalmente teria isso é a ISTAT, que está inacessível deste IP (registro separado). Ausência na minha leitura não é ausência no mundo — isto é NÃO SEI, não é ''não existe''.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpshr (teste de ausência)','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1500&time=2024&strucpro=YLD_HUMD_EU_T_HA&geo=ITC4&geo=ITH3&geo=ITF4&geo=ITC1',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','todas as culturas do piloto','regiões italianas','O Eurostat NÃO publica rendimento (t/ha) por região. Testei o código YLD_HUMD_EU_T_HA no dataset regional para milho, trigo duro e arroz em 2024, pedindo Lombardia, Veneto, Puglia e Piemonte: as três consultas voltaram com zero valores. O código EXISTE no dicionário do dataset, mas vem vazio no nível NUTS-2. Rendimento só no nacional.','0 valores em 3 culturas × 4 regiões','toneladas por hectare','2024','CURRENT','strucpro YLD_HUMD_EU_T_HA = "Yield in EU standard humidity - tonnes per hectare" · resposta regional: "nvals 0 {}" para C1500, C1120 e C2000','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpshr?format=JSON&lang=en&crops=C1500&time=2024&strucpro=YLD_HUMD_EU_T_HA&geo=ITC4&geo=ITH3&geo=ITF4&geo=ITC1','2026-05-28'::date,'ALTA','Não prova que rendimento regional não existe em nenhum lugar — prova que não está neste dataset. E o cálculo produção ÷ área, se for feito, NÃO vira dado publicado: continua sendo conta nossa, e precisa entrar na ferramenta rotulada como tal.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpsh1','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?format=JSON&lang=en&geo=IT&time=2025&crops=C1500',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','as 10 culturas do piloto','Itália (nacional)','O nacional já vai até 2025, e o acervo dizia que parava em 2024. Área (mil ha) e produção (mil t) em 2025: mais 540,95 / 5.529,06 (rend. 10,22 t/ha); frumento duro 1.134,23 / 3.756,67 (3,31); frumento tenero 511,24 / 2.564,57 (5,02); vite 723,68 / 7.681,20; olivo 1.097,68 / 2.486,81; barbabietola 18,68 / 914,03 (48,93); riso 234,73 / 1.408,70 (6,00); soia 297,78 / 1.104,54 (3,71); melo 53,82 / 2.412,92; pomodoro 107,21 / 6.625,60.','10 culturas com área, produção e (em 6 delas) rendimento para 2025','mil hectares, mil toneladas, toneladas por hectare','2025','HISTORICAL','"Crop production in EU standard humidity" · updated "2026-08-28T23:00:00+0200" · strucpro AR_THS_HA, HPRD_HUMD_EU_THS_T, YLD_HUMD_EU_T_HA','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?format=JSON&lang=en&geo=IT&time=2025&crops=C1500','2026-08-28'::date,'ALTA','É 2025, não 2026: NÃO prova o que está no campo hoje (02/09/2026). E é NACIONAL — não tem recorte regional, então não serve para dar peso a região nenhuma. Área e produção não são demanda, receita nem presença de praga.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Eurostat — apro_cpsh1 (variações são cálculo do Sintonia sobre os valores publicados)','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?format=JSON&lang=en&geo=IT&time=2025&crops=R2000',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','barbabietola da zucchero','Itália (nacional)','A beterraba açucareira encolheu de 29,23 mil ha (2024) para 18,68 mil ha (2025) — queda de 10,55 mil ha, ou 36,1%. A produção caiu de 1.534,44 para 914,03 mil t (−40,4%). O rendimento também caiu, de 52,50 para 48,93 t/ha (−6,8%). A soja caiu 11,6% em área no mesmo período (336,74 → 297,78 mil ha); o milho SUBIU 9,2% (495,35 → 540,95).','área −36,1%; produção −40,4%; rendimento −6,8%','variação percentual de um ano para o outro','2024 → 2025','HISTORICAL','apro_cpsh1 R2000 "Sugar beet (excluding seed)" — 2024: AR_THS_HA 29.23, HPRD_HUMD_EU_THS_T 1534.44, YLD_HUMD_EU_T_HA 52.5 · 2025: AR_THS_HA 18.68, HPRD_HUMD_EU_THS_T 914.03, YLD_HUMD_EU_T_HA 48.93','https://ec.europa.eu/eurostat/api/dissemination/statistics/1.0/data/apro_cpsh1?format=JSON&lang=en&geo=IT&time=2025&crops=R2000','2026-08-28'::date,'ALTA','NÃO explica a causa. Queda de área pode ser preço, contrato com açucareira, rotação, clima, política — a fonte publica o número, não o motivo, e eu não perguntei a ninguém. NÃO é oportunidade nem ameaça comercial: converter ''área caiu'' em leitura de mercado seria exatamente o pulo que a regra proíbe. E dois anos não são tendência.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT (teste de acesso)','https://esploradati.istat.it/databrowser',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','peso-economico','estatistica_agricola','todas (rota que resolveria pomodoro, olivo e melo por região)','Itália','A ISTAT — que é a fonte primária de área e produção da Itália, e a única rota provável para tomate/oliveira/macieira POR REGIÃO — continua fora do alcance deste IP. Testei três portas: o navegador de dados esploradati.istat.it não conecta; dati.istat.it dá redirecionamento e depois falha no aperto de mão de segurança; sdmx.istat.it (a porta de API) entra em redirecionamento infinito. Só o site institucional www.istat.it abre (HTTP 200), e ele não serve dado.','3 de 4 portas falharam; a que abre não tem dado','—','testado em 02/09/2026','CURRENT','esploradati.istat.it → "curl: (28) Failed to connect to esploradati.istat.it:443 after 21090 ms: Could not connect to server" (HTTP=000) · dati.istat.it → "<urlopen error [SSL: SSLV3_ALERT_HANDSHAKE_FAILURE] sslv3 alert handshake failure (_ssl.c:1010)>" · sdmx.istat.it/SDMXWS/rest/dataflow/IT1 → "HTTP Error 302: The HTTP server returned a redirect error that would lead to an infinite loop." e por curl "(56) schannel: server closed abruptly (missing close_notify)"','https://esploradati.istat.it/databrowser/','2026-09-02'::date,'ALTA','NÃO prova que a ISTAT não publica o dado. Fonte bloqueada por IP não é fonte inexistente. De outro ponto de rede (ou por alguém na Itália) o dado provavelmente abre — o que muda a classificação desta lacuna de ''não existe'' para ''não alcançada daqui''.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ADAMA Italia — sitemap oficial + 51 fichas de produto','https://www.adama.com/italia/it/sitemap.xml',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto',NULL,'Italia (site nacional adama.com/italia/it)','O catalogo publico da ADAMA Italia tem 51 fichas de produto, distribuidas em 4 categorias: ERBICIDI 26, FUNGICIDI 14, INSETTICIDI 6, SPECIALI 5.','26 / 14 / 6 / 5','fichas de produto por categoria (total 51)','leitura de 02/09/2026','CURRENT','<loc>https://www.adama.com/italia/it/prodotti-adama/fungicidi/mirador-sc</loc>','https://www.adama.com/italia/it/sitemap.xml','2026-09-02'::date,'ALTA','NAO prova que a ADAMA Italia comercializa exatamente 51 produtos. Catalogo e vitrine, nao lista de vendas. Um produto vendido pode nao ter ficha, e uma ficha pode continuar publicada depois de o produto sair de linha. NAO prova nada sobre volume, preco, disponibilidade ou presenca em loja. NAO prova que esta lista e identica a que o visitante ve na pagina de listagem, porque essa pagina esta bloqueada e nao pude compara-la.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ADAMA Italia — ficha Folpan Energy','https://www.adama.com/italia/it/prodotti/erbicidi/folpan-energy',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto','Vite da vino','Italia','O segmento de URL nao e a categoria do produto: contar pelo caminho da URL da 27/13/6/5, contar pela etiqueta impressa na ficha da 26/14/6/5. A divergencia e um unico produto, Folpan Energy, que mora em /prodotti/erbicidi/ mas cuja ficha o rotula ''Fungicidi''.','1 produto divergente em 51','produtos com caminho de URL discordante da etiqueta em pagina','leitura de 02/09/2026','CURRENT','Una combinazione unica tra due fungicidi antiperonosporici: uno con attività di contatto multisito ed uno sistemico che si distribuisce rapidamente in tutta la pianta','https://www.adama.com/italia/it/prodotti/erbicidi/folpan-energy','2026-09-02'::date,'ALTA','NAO prova que a ADAMA classifica errado o produto no seu proprio sistema; prova apenas que o caminho publicado e a etiqueta publicada discordam entre si. NAO prova que a categoria em pagina coincide com a classificacao regulatoria do Ministero — sao duas classificacoes de universos diferentes.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ADAMA Italia — fichas da categoria Speciali','https://www.adama.com/italia/it/prodotti-adama/speciali/brevis',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto','Brevis: Melo, Pero · Exelgrow: 43 culturas incl. Vite da vino, Olivo, Pomodoro · Budge: Girasole, Mais, Barbabietola da zucchero, Colza, Cereali, Riso, Soia · Powerfilm: Riso · Parleaf: nenhuma cultura declarada na ficha','Italia','Os cinco produtos da categoria SPECIALI do catalogo ADAMA Italia sao: Brevis, Budge, Exelgrow, Parleaf e Powerfilm.','5','fichas na categoria SPECIALI','leitura de 02/09/2026','CURRENT','Brevis è la soluzione di Adama a base di Metamitron, semplice ed efficace per il dirado di melo e pero.','https://www.adama.com/italia/it/prodotti-adama/speciali/brevis','2026-09-02'::date,'ALTA','NAO prova que os cinco pertencem ao mesmo regime regulatorio — nao pertencem. Brevis, Parleaf e Powerfilm tem numero de registro fitossanitario; Budge e Exelgrow carregam numero do registro de fertilizantes. NAO prova que SPECIALI seja uma categoria regulatoria: e uma prateleira comercial do site.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Ministero della Salute — Banca dati dei prodotti fitosanitari','https://www.fitosanitari.salute.gov.it/fitosanitariws_new/FitosanitariServlet',ARRAY['BOLETIM_FITOSSANITARIO','REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto',NULL,'Italia','Seis produtos do catalogo ADAMA Italia tem a autorizacao fitossanitaria registrada em nome de OUTRA empresa: Mirador SC, Mavita 250 EC, Zakeo 250 SC e Timeline Trio sao da SYNGENTA CROP PROTECTION AG; Clematis e da ALBAUGH TKI D.O.O; Parleaf e da MICROCIDE LTD.','6','produtos de catalogo com titular de autorizacao nao-ADAMA','consulta ao Ministero em 02/09/2026','CURRENT','015111 | MIRADOR SC | SYNGENTA CROP PROTECTION AG | 25/03/2011 | 31/05/2027 | FUNGICIDA | SC | AZOXYSTROBIN | 23.2 g | Ri-registrato','https://www.fitosanitari.salute.gov.it/fitosanitariws_new/FitosanitariServlet','2026-09-02'::date,'ALTA','NAO prova qualquer relacao comercial, licenca, contrato de distribuicao, co-marketing ou aquisicao entre a ADAMA e a Syngenta, a Albaugh ou a Microcide. O registro diz quem e o titular da autorizacao, e nada mais. NAO prova que a ADAMA vende esses produtos — prova que os publica no proprio catalogo italiano. NAO prova que a Syngenta ''perdeu'' ou ''cedeu'' nada. O porque e NAO_SEI.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ADAMA Italia — fichas Budge e Exelgrow','https://www.adama.com/italia/it/prodotti-adama/speciali/exelgrow',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto','Exelgrow: 43 culturas (Vite da vino, Vite da tavola, Olivo, Pomodoro, Melo, Pero, Fragola, Actinidia e outras) · Budge: Girasole, Mais, Barbabietola da zucchero, Colza, Cereali, Riso, Soia','Italia','Budge e Exelgrow, dois dos cinco SPECIALI, nao sao produtos fitossanitarios: publicam numero do registro de fertilizantes, em formato diferente (sete digitos com barra e ano), e nao do registro fitossanitario.','2','fichas de catalogo fora do regime fitossanitario','leitura de 02/09/2026','CURRENT','Exelgrow è il biostimolante (Regolamento europeo 2019/1009) non microbico di Adama a base di filtrato di crema dell''alga Ascofillum nodosum','https://www.adama.com/italia/it/prodotti-adama/speciali/exelgrow','2026-09-02'::date,'ALTA','NAO prova que os numeros citados foram conferidos por mim no registro de fertilizantes — nao foram; li o numero na ficha da ADAMA e reconheci o formato. NAO prova eficacia, nem que biostimulante substitua defensivo. NAO prova que nao existam outros biostimulantes ADAMA sem ficha no catalogo.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Ministero della Salute — Banca dati dei prodotti fitosanitari','https://www.fitosanitari.salute.gov.it/fitosanitariws_new/FitosanitariServlet',ARRAY['BOLETIM_FITOSSANITARIO','REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto','Riso','Italia','A ficha do Powerfilm publica o numero de registro n° 17052, que na base do Ministero pertence a COCTEL GOLD, da LAINCO S.A. O Powerfilm da ADAMA e o registro 017852.','1','ficha com numero de registro conflitante','consulta ao Ministero em 02/09/2026','CURRENT','017052 | COCTEL GOLD | LAINCO S.A. | 15/12/2023 | 15/12/2034 | DISERBANTE | SL | MCPAGLYPHOSATE — 017852 | POWERFILM | ADAMA ITALIA S.R.L. | 01/06/2021 | 31/10/2041 | COADIUVANTE | AL | PLANT OILS / RAPE SEED OIL','https://www.fitosanitari.salute.gov.it/fitosanitariws_new/FitosanitariServlet','2026-09-02'::date,'ALTA','NAO prova que a ADAMA errou de proposito nem que ha problema regulatorio. NAO prova que e erro de digitacao — e a leitura mais provavel pela coincidencia da data, mas nao foi confirmada pela empresa. NAO prova que outras fichas nao tenham o mesmo defeito: conferi no Ministero apenas 8 dos 51 numeros.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Ministero della Salute — Banca dati dei prodotti fitosanitari','https://www.fitosanitari.salute.gov.it/fitosanitariws_new/FitosanitariServlet',ARRAY['BOLETIM_FITOSSANITARIO','REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto','Riso','Italia','FullPage e Max-Ace sao marcas de SISTEMA, nao produtos registrados: cada uma publica o numero de registro de um produto de nome diferente. FullPage usa o 017868, que e POSTSCRIPT 80 XL; Max-Ace usa o 017995, que e HIGHCARD — e Highcard tem ficha propria no mesmo catalogo.','2','marcas de catalogo sem registro proprio','consulta ao Ministero em 02/09/2026','CURRENT','017868 | POSTSCRIPT 80 XL | ADAMA AGAN LTD | 08/05/2023 | 30/06/2027 | DISERBANTE | SL | IMAZAMOX — 017995 | HIGHCARD | ADAMA AGAN LTD | 08/02/2024 | 28/02/2028 | DISERBANTE-ANTIDOTO AGRONOMICO | EC | QUIZALOFOP-P-ETHYLISOXADIFEN ETHYL','https://www.fitosanitari.salute.gov.it/fitosanitariws_new/FitosanitariServlet','2026-09-02'::date,'ALTA','NAO prova que FullPage e Max-Ace sejam ''so'' um herbicida: sao apresentados como sistemas de cultivo do arroz, que combinam variedade e herbicida, e o registro cobre apenas a parte quimica. NAO prova o que mais compoe o sistema, porque nao li essa parte. NAO prova que POSTSCRIPT 80 XL nao seja comercializado — so que nao tem ficha propria.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ADAMA Italia — ficha Nimrod 250 EW; Ministero della Salute','https://www.adama.com/italia/it/prodotti/fungicidi/nimrodr-250-ew',ARRAY['REGULATORIO','CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto','Fragola, Melone, Melo, Melanzana, Laucoceraso, Albicocco, Cocomero, Cetriolo, Cetriolino, Nettarino, Peperone, Pesco, Pomodoro, Rosa, Vite da tavola, Vite da vino, Zucca, Zucchino','Italia','O produto Nimrod 250 EW esta no catalogo publico, mas o arquivo normalizado o marca IN_PUBLIC_CATALOG=false. Sua ficha e a unica das 51 que nao publica numero de registro nenhum.','1 de 41','registros com flag de catalogo errada','leitura de 02/09/2026','CURRENT','013771 | NIMROD 250 EW | ADAMA MAKHTESHIM LTD | 02/04/2007 | 31/01/2027 | FUNGICIDA | EW | BUPIRIMATE | 23.8 g | Ri-registrato','https://www.adama.com/italia/it/prodotti/fungicidi/nimrodr-250-ew','2026-09-02'::date,'MEDIA','Confianca MEDIA porque o casamento e por NOME, nao por numero: a ficha nao traz numero e o Ministero mostra dois Nimrod ADAMA vigentes com o mesmo ingrediente e a mesma validade (002983 NIMROD e 013771 NIMROD 250 EW). O nome exato aponta o 013771, mas NAO_SEI com certeza a qual dos dois registros a ficha se refere. NAO prova que existam outras flags erradas nao detectadas.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Cruzamento entre o corpus regulatorio ADAMA IT (163) e o censo do catalogo publico (51)','https://www.adama.com/italia/it/sitemap.xml',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto',NULL,'Italia','Dos 163 produtos do registro, 41 tem ficha no catalogo publico e 122 nao tem. Entre os 122: 68 herbicidas, 36 fungicidas, 17 inseticidas e 2 outros.','122 de 163','produtos do registro sem ficha no catalogo publico','registro capturado em 30/08/2026 (versao PROD_FTS_6_20260824); catalogo lido em 02/09/2026','CURRENT','IN_PUBLIC_CATALOG=false NAO significa fora de mercado — significa que a pagina publica nao o lista.','https://www.adama.com/italia/it/sitemap.xml','2026-09-02'::date,'ALTA','NAO prova que os 122 foram descontinuados, retirados do mercado ou nao sao vendidos. Ausencia na nossa leitura nao e ausencia no mundo: e NAO_SEI. Frase proibida: ''a ADAMA nao vende mais X na Italia''. Frase permitida: ''nesta leitura de 02/09/2026 nao encontramos ficha de X no catalogo publico''. Tambem NAO prova o inverso — nao converte a ausencia em oportunidade comercial, porque nao ha aqui nenhum dado de demanda, de canal ou de concorrencia.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ADAMA Italia — pagina de listagem do catalogo','https://www.adama.com/italia/it/products/crop-protection',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','catalogo','catalogo_produto',NULL,'Italia','A pagina indice do catalogo da ADAMA Italia esta bloqueada por WAF Akamai e responde 403 Access Denied, enquanto a sitemap e as 51 fichas de produto do mesmo dominio abrem normalmente.','403','codigo HTTP na pagina de listagem do catalogo','tentativas em 02/09/2026','CURRENT','<h1>Access Denied</h1> <p>You don''t have permission to access this resource on this server.</p> <p>Reference #0.dd041abd.1788361071.826bd96</p>','https://www.adama.com/italia/it/products/crop-protection','2026-09-02'::date,'ALTA','NAO prova que a ADAMA bloqueia deliberadamente esta coleta, nem que o bloqueio seja permanente ou dirigido a nos: e uma regra de WAF que pode mudar a qualquer momento. Fonte bloqueada nao e fonte inexistente. NAO prova que a lista da sitemap seja identica a que o visitante veria nessa pagina — nao pude comparar as duas.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database (DG SANTE) — assets/env-json-config.json','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/assets/env-json-config.json',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/assets/env-json-config.json' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/assets/env-json-config.json' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','ROTA_DE_FONTE','A API do EU Pesticides Database é pública e aberta, mas a base dela não está no bundle JS: está num arquivo de configuração de runtime que o app carrega depois. Sem esse arquivo, o palpite /api devolve uma página de erro cacheada.','leitura de 02/09/2026'::date,false,'{"modules":{"envLabel":"","core":{"base":"https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/backend/api","userDetails":"/user-details"}}}','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/assets/env-json-config.json','2026-09-02 (data de leitura)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que a rota fique estável; é config de runtime e o Publications Office pode trocá-la sem aviso. E o caminho ingênuo /api devolve HTTP 200 com uma página estática ''Server temporarily unavailable'' vinda do CloudFront (Age 3.023.375 s na nossa leitura) — quem não conferir o corpo da resposta acha que o serviço caiu.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database — active-substances.module-62ZYYHIV.js','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/active-substances.module-62ZYYHIV.js',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/active-substances.module-62ZYYHIV.js' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/active-substances.module-62ZYYHIV.js' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','CONTRATO_DE_BUSCA','O POST de busca do EU Pesticides Database exige o objeto de critérios completo; com {} ou com um nome ele devolve HTTP 500. O corpo correto está no chunk da rota do app.',NULL::date,false,'clearFilters(){this.searchValues={type:[],status:[],legislation:[],authorisedIn:[],hazardClass:[],classification:[],approvalFrom:[],approvalTo:[],expiryFrom:[],expiryTo:[],cfs:[],adi_from:[],adi_to:[],arfd_from:[],arfd_to:[],aoel_from:[],aoel_to:[],aaoel_from:[],aaoel_to:[]}}','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/active-substances.module-62ZYYHIV.js','2026-09-02 (data de leitura)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que a filtragem por substância seja feita no servidor — a filtragem por nome no site é feita no navegador (textFilter sobre AS_NAME), então quem quiser filtrar tem de baixar tudo e filtrar localmente') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database — active substances (1.483 registros) cruzado com adama-italy-products.json (163 produtos, registro do Ministero PROD_FTS_6_20260824)','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances',ARRAY['REGULATORIO','CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','todas as culturas do portfólio','Das 53 substâncias ativas declaradas nos 163 registros ADAMA Itália, 50 aparecem na lista europeia de substâncias ativas/protetores/sinérgicos e 39 delas (78% das casadas) estão com a aprovação PRORROGADA: a data original de expiração já passou e foi substituída por uma data de extensão.',NULL::date,false,'Active substances, safeners and synergists (1483 matching records)','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances','2026-09-02 (leitura da base)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que essas prorrogações vão continuar acontecendo, nem que alguma renovação será negada. Prorrogação é ato de procedimento, não decisão de mérito. E o casamento por nome pode falhar em sinônimos: as 3 não encontradas são protetores (safeners), ver registro próprio.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regulamento de Execução (UE) 2026/1826 da Comissão, de 28 de julho de 2026','http://data.europa.eu/eli/reg_impl/2026/1826/oj',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='http://data.europa.eu/eli/reg_impl/2026/1826/oj' or 'http://data.europa.eu/eli/reg_impl/2026/1826/oj' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','MECANISMO_LEGAL','O ato europeu explica por escrito por que prorroga: a aprovação vai vencer antes de a renovação ser decidida, e o atraso é atribuído a causas fora do controle do requerente. É o texto que separa EXPIRY de WITHDRAWAL.',NULL::date,false,'As the approvals of these active substances are likely to expire before decisions have been taken on their renewal as part of the ongoing renewal procedures, the Commission inquired with the rapporteur Member States concerned and the European Food Safety Authority (the ''Authority'') on the reasons for the delays in the renewal procedures of these active substances. […] The information available, including that provided by the rapporteur Member States and the Authority, shows that the reasons for the delays in each of these renewal procedures are beyond the control of the applicants.','http://data.europa.eu/eli/reg_impl/2026/1826/oj','2026-07-29 (JO L, 2026/1826)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que toda substância prorrogada será renovada. O próprio 2026/1826 prorroga phenmedipham e fludioxonil, e para as duas há projeto de NÃO-renovação em cima da mesa (registros abaixo).') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database — Metamitron (AS_ID 209)','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/209',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/209' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/209' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','BARBABIETOLA (GOLTIX, NORTIM, GOLD-BEET, GOLTIX 700 SC, GOLTIX SUPER, GOLDBEET SUPER, GOLTIX BETA, GOLTIX TOP) e MELO (B','Metamitron: a aprovação europeia expira em 30/11/2026. Os 9 produtos ADAMA Itália com metamitron vencem exatamente na mesma data.','horizonte 3 meses'::date,false,'"AS_NAME":"Metamitron","AS_STATUS":"Approved","APPROVAL_DT":"01\/09\/2009","EXPIRY_OF_APPROVAL_DT":"31\/08\/2023","EXTENSION_OF_APPROVAL_DT":"30\/11\/2026","EXPIRY_DT":"30\/11\/2026"','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/209','2026-09-02 (leitura da base)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que os produtos saem do mercado em 30/11/2026. Existe projeto de nova prorrogação em discussão (ver registro PLAN/2026/1408). E não li o rótulo de 8 dos 9 produtos linha a linha — o próprio pacote avisa que 88,3% dos rótulos têm ZERO linha de uso lida.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database — Flonicamid (IKI-220)','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','MELO e POMODORO (APYZA WG, APYZA 500 WG — os 2 únicos produtos ADAMA IT com linha de uso lida: 4 cada)','Flonicamid (IKI-220): aprovação europeia expira 30/11/2026, mesma data dos 2 produtos ADAMA Itália. A renovação já tem relatório do Estado-relator entregue (05/12/2023) mas ainda sem conclusão da EFSA registrada.','horizonte 3 meses'::date,false,'"AS_NAME":"Flonicamid (IKI-220)","EXPIRY_OF_APPROVAL_DT":"31\/08\/2023","EXTENSION_OF_APPROVAL_DT":"30\/11\/2026","EXPIRY_DT":"30\/11\/2026"','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances','2026-09-02 (leitura da base)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova retirada; a substância está no projeto de prorrogação PLAN/2026/1408') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Standing Committee on Plants, Animals, Food and Feed, Section Phytopharmaceuticals – Legislation, Summary Report da reunião de 29-30 de junho de 2026 (ref. sante.g.3(2026)7890641)','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','ATO_EM_PREPARO','Há um projeto de regulamento europeu que prorroga metamitron, flonicamid (IKI-220) e sulcotrione — as três substâncias que vencem em 30/11/2026 no portfólio. Foi apresentado na reunião do SCoPAFF de 29-30/06/2026 como ponto C.08 (troca de opiniões, ainda sem votação), com comentários dos Estados-Membros até 17/07/2026. Até 02/09/2026 ele NÃO aparece publicado no Jornal Oficial na nossa leitura do CELLAR.','horizonte 3 meses'::date,false,'C.08 Exchange of views of the Committee on a draft Commission Implementing Regulation (EU) amending Implementing Regulation (EU) No 540/2011 as regards the extension of the approval periods of the active substances […] flonicamid (IKI-220), […] metamitron, […] sulcotrione, […] (PLAN/2026/1408) The Commission presented the draft Implementing Regulation. […] Member States were invited to send comments on the draft Implementing Regulation by 17 July 2026','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova que a prorrogação vai sair, nem por quanto tempo. É troca de opiniões, não votação: dois Estados-Membros já declararam voto contrário (por fenoxaprop-P e halosulfuron-methyl, não pelas nossas substâncias) e outros três apoiaram essas objeções. E não sei se o ato foi publicado depois da nossa leitura de 02/09/2026.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','1 produto ADAMA Itália: SEEDRON (FLUDIOXONIL + TEBUCONAZOLE), reg. 016152, vencimento nacional 30/09/2026, conciante de ','Fludioxonil: a Comissão disponibilizou em 09/07/2026 um PROJETO de regulamento de NÃO-RENOVAÇÃO da aprovação, com prazo de comentários dos Estados-Membros até 03/09/2026 — um dia depois da nossa data de referência. Na mesma temporada, o Reg. 2026/1826 esticou a aprovação para 30/09/2027.','horizonte 3 meses'::date,false,'On 9 July 2026, the Commission made available via CIRCABC a draft Implementing Regulation for non-renewal of fludioxonil and a draft Renewal Report. Member States were invited to send comments by 3 September 2026.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30, com atualização de 2026-07-09 no próprio relatório'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova que a não-renovação será adotada — é projeto em consulta, e o próprio relatório registra que os requerentes apresentaram três artigos revisados por pares defendendo a renovação. Também não transforma isso em oportunidade comercial: o SEEDRON da ADAMA é ele próprio um dos produtos atingidos.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','BARBABIETOLA — 2 produtos ADAMA Itália: CONTATTO 320 (reg. 009790) e CONTATTO DOUBLE SC (reg. 011734), ambos com vencime','Phenmedipham: a Comissão apresentou o projeto de Relatório de Revisão para a NÃO-RENOVAÇÃO da aprovação e, na mesma reunião, propôs uma prorrogação de um ano até 30/09/2027 — prorrogação que depois virou o Reg. 2026/1826. Um Estado-Membro apoiou a não-renovação, outro se opôs, invocando a importância do phenmedipham no controle de infestantes da beterraba e no manejo de resistência.','horizonte 12 meses'::date,false,'8. Phenmedipham The Commission presented the draft Review Report on the non-renewal of phenmedipham and summarised the written comments received. One Member State supported a non-renewal of the approval; one Member State opposed the non-renewal of approval. The latter Member State and two associations stressed the importance of phenmedipham for sugar beet weed control and resistance management. […] The Commission proposed a one-year extension of approval until 30 September 2027.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova a decisão final. O relatório registra que a Comissão rejeitou o pedido de derrogação do Artigo 4(7) por prazos perdidos e por falta de base legal para considerar razões socioeconômicas, mas o processo ainda vai a notificação OMC/TBT e a ponto C em reunião futura.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','CEREAIS — 10 produtos ADAMA Itália com clodinafop, todos com vencimento nacional 31/07/2027: TOPIK 240 EC, TOPIK 80 EC, ','Clodinafop: a EFSA identificou uma área crítica de preocupação — risco alto para grandes mamíferos herbívoros — e a Comissão declarou em ata que uma não-renovação ''provavelmente seria proposta''. Comentários dos Estados-Membros pedidos até 31/08/2026.','horizonte 12 meses'::date,false,'9. Clodinafop The Commission explained that EFSA identified a critical area of concern: clodinafop poses a high risk to large herbivorous mammals. EFSA also could not finalise several issues not finalised in the risk assessment. As no scientifically proven mitigation measures can address these risks, the Commission noted that a non-renewal would likely be proposed considering the recent outcome of the cypermethrin court case. […] Member States were invited to send comments on the EFSA Conclusion and their preliminary positions by 31 August 2026.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30; EFSA Conclusion publicada em 2026-03'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova que a não-renovação foi proposta nem adotada. A própria frase é condicional (''would likely be proposed'') e o relatório diz que o projeto de Relatório de Renovação só será apresentado quando a validação política interna terminar. Também não sei se o clodinafop dos produtos ADAMA está sempre acompanhado do protetor cloquintocet-mexyl.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026, ponto A.20 AoB','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','5 produtos ADAMA Itália com tebuconazole: CUSTODIA ULTRA, VINETO, SEEDRON, BLAISE ULTRA, MIRADOR TURBO (vencimentos naci','Tebuconazole: a Comissão ABRIU uma revisão nos termos do Artigo 21 do Reg. 1107/2009 sobre a aprovação, porque a substância deve ser classificada como Tóxica para a Reprodução, categoria 1B. Os requerentes foram convidados a apresentar dados sobre exposição negligenciável e sobre a derrogação do Artigo 4(7); depois a EFSA será mandatada para avaliar.','horizonte 24 meses'::date,false,'Article 21 review of tebuconazole The Commission informed that it had launched an Article 21 review of the approval of tebuconazole and the letter to the applicants had been uploaded on CIRCABC. As tebuconazole is to be classified as Toxic for Reproduction, category 1B the applicants were invited to provide data on the applicability of a possible derogation based on negligible exposure with respect to the representative uses underpinning the current approval or those in the renewal application. They were also invited to provide data on the applicability of the derogation under Article 4(7) of Regulation (EC) No 1107/2009. Once the data will be submitted, EFSA will be mandated to evaluate it, together with the Rapporteur Member States.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova retirada nem restrição já decidida. Artigo 21 é revisão; pode terminar sem alteração, com condições novas, ou com retirada. E a classificação 1B é descrita como algo que ''está para ser'' feito, não como já feita.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regulamento de Execução (UE) 2026/1826 da Comissão, de 28 de julho de 2026 — ANEXO','http://data.europa.eu/eli/reg_impl/2026/1826/oj',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='http://data.europa.eu/eli/reg_impl/2026/1826/oj' or 'http://data.europa.eu/eli/reg_impl/2026/1826/oj' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','BARBABIETOLA (phenmedipham), diversas (pirimicarb, fosetyl), sementes (fludioxonil), colza (metazachlor)','O Reg. 2026/1826, de 28/07/2026, moveu a data de expiração de 6 substâncias do portfólio ADAMA Itália, uma por uma, no Anexo do Reg. 540/2011.',NULL::date,false,'(2) in the sixth column, expiration of approval, of row 88, Phenmedipham, the date is replaced by ''30 September 2027''; […] (4) in the sixth column, expiration of approval, of row 124, Pirimicarb, the date is replaced by ''31 July 2027''; […] (6) in the sixth column, expiration of approval, of row 131, Fosetyl, the date is replaced by ''31 January 2028''; […] (10) in the sixth column, expiration of approval, of row 161, Fludioxonil, the date is replaced by ''30 September 2027''; […] (13) in the sixth column, expiration of approval, of row 217, Metazachlor, the date is replaced by ''31 May 2029''; […] (16) in the sixth column, expiration of approval, of row 304, Metalaxyl, the date is replaced by ''30 June 2029''','http://data.europa.eu/eli/reg_impl/2026/1826/oj','2026-07-29 (JO L, 2026/1826)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que o registro italiano já refletiu essas datas: o dataset nacional é de 24/08/2026 e para phenmedipham e fludioxonil ele ainda traz 30/09/2026, um ano antes da data europeia nova') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regulamento de Execução (UE) 2026/1421 da Comissão, de 30 de junho de 2026 — ANEXO','http://data.europa.eu/eli/reg_impl/2026/1421/oj',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
