insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','pendimethalin: cereais, milho, videira, batata, soja, girassol, tomate · bupirimate: videira, macieira, tomate · tau-flu','O pico de 22 produtos vencendo em jan/27 no calendário nacional é a soma de três relógios europeus: pendimethalin (15/01/2027, 10 produtos), bupirimate (31/01/2027, 5 produtos) e tau-fluvalinate (31/01/2027, 7 produtos).','horizonte 6 meses'::date,false,'"AS_NAME":"Pendimethalin","EXPIRY_DT":"15\/01\/2027" · "AS_NAME":"Bupirimate","EXPIRY_DT":"31\/01\/2027" · "AS_NAME":"tau-Fluvalinate","EXPIRY_DT":"31\/01\/2027"','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances','2026-09-02 (leitura da base)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que os 22 produtos sairão do mercado. Para as três substâncias a renovação está em avaliação; e o pendimethalin é Candidato à Substituição, o que muda o rito mas não decide o resultado.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database — detalhes do processo de renovação (AS_ID 1373 e 485)','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/1373',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/1373' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/1373' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','REQUERENTE_DECLARADO','O registro europeu da renovação de tau-fluvalinate e de bupirimate nomeia a ADAMA como quem submeteu o dossiê — informação pública, no campo de observação do processo de renovação.','horizonte 6 meses'::date,false,'Application under 844/2012 originally submitted on 18/05/2018. By Reg EU 2020/1740 the application and the dossier are submitted jointly; ADAMA submitted via IUCLID','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/1373','2026-09-02 (leitura da base)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não é dado interno da ADAMA e não deve ser tratado como tal: é o que a Comissão publica sobre quem submeteu. Não diz o estado do dossiê, nem se há conclusão da EFSA (não há data de conclusão registrada para nenhuma das duas), nem o resultado esperado.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database — active_substance/details (campos SUBMISSION_DRAR_DT, EFSA_OUTPUT_DT, ADMISSIBILITY_DT)','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/713',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/713' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/713' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','ESTADO_DA_RENOVACAO','Estado do processo de renovação das substâncias prioritárias, lido no registro europeu: quem já tem relatório do Estado-relator entregue, quem já tem conclusão da EFSA, e quem não tem nada.',NULL::date,false,'"SUBMISSION_DRAR_DT": "2018-02-22 00:00:00", "EFSA_OUTPUT_DT": "2025-07-08 15:57:51", "INITIAL_EXPIRY_OF_APPROVAL_DT": "2018-07-31 00:00:00", "REMARK": "DRAR expected: 15/01/2021; ED submission DL: 15/04/2023 (Not ED for humans)"','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances/details/713','2026-09-02 (leitura da base)'::date,'MEDIA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova nada sobre o resultado. Campo vazio na base NÃO significa que o marco não aconteceu no mundo — significa que não foi registrado ali. Por isso a confiança é MÉDIA, não alta.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EFSA Journal — Peer review of the pesticide risk assessment of the active substance prothioconazole; e SCoPAFF Summary Report 29-30/06/2026','https://doi.org/10.2903/j.efsa.2025.9593',ARRAY['REGULATORIO','CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://doi.org/10.2903/j.efsa.2025.9593' or 'https://doi.org/10.2903/j.efsa.2025.9593' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','CEREAIS — 5 produtos ADAMA Itália: MAGANIC, MAXENTIS, AVASTEL, SORATEL, KOJAMI (vencimentos nacionais 31/03/2027 a 31/03','Prothioconazole tem conclusão de revisão por pares publicada pela EFSA em agosto de 2025; e na reunião de 29-30/06/2026 a Comissão informou que recebeu da EFSA os esclarecimentos sobre a lacuna de dados dos co-formulantes, de modo que o processamento do dossiê pode continuar.','horizonte 12 meses'::date,false,'7. Prothioconazole The Commission informed the Committee that the requested clarifications from EFSA regarding the data gap on co-formulants had been recently received so that the processing of the dossier can be continued.','https://doi.org/10.2903/j.efsa.2025.9593','EFSA: 2025-08 · SCoPAFF: reunião de 2026-06-29/30'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que a renovação sairá antes de 31/03/2027, nem que sairá. Ter a conclusão da EFSA é condição para decidir, não é a decisão.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026, ponto 15','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','6 produtos ADAMA Itália: DAUPHIN 45, BADGER 45% WG, CARSON 45% WG, ANTERLEX, MOXYL MK, VANTEX — todos com vencimento nac','Cymoxanil: a EFSA finalizou a conclusão; a avaliação de risco NÃO identificou nenhuma área crítica de preocupação, mas a avaliação das propriedades desreguladoras endócrinas não pôde ser finalizada (modalidade esteroidogênese), assim como definição de resíduo, risco ao consumidor e exposição de águas subterrâneas.','horizonte 24 meses'::date,false,'15. Cymoxanil The Commission informed Member States that EFSA finalised its Conclusion for cymoxanil which were commented by the two applicants. […] The risk assessment did not identify any critical area of concern. However, the assessment of the endocrine disrupting properties could not be finalised, specifically the steroidogenesis modality. Other issues that could not be finalised were the residue definition, the consumer risk assessment and the groundwater exposure. The co-formulants were also assessed and no concerns were identified by EFSA.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30; EFSA Conclusion de 2026-07'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova que a renovação está garantida — quatro itens ficaram por finalizar, e o item endócrino é justamente o que derrubou outras substâncias. E os 6 produtos ADAMA têm vencimento nacional de 15/08/2026, ANTERIOR à nossa data de referência: não sei o estado administrativo deles hoje.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026, ponto A.06 Confirmatory Information, item 2','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','CEREAIS — 2 produtos ADAMA Itália: EDAPTIS e MEZAYO (vencimento nacional 31/12/2029; aprovação UE até 31/12/2029)','Pinoxaden: a Comissão propôs restringir o uso a uma aplicação a cada três anos no mesmo campo, com base em estudos de monitoramento em que a substância só era aplicada de três em três anos na maioria dos locais amostrados.','horizonte 12 a 24 meses'::date,false,'2. Pinoxaden The Commission announced that a draft revised renewal report would be shared via CIRCABC shortly after the meeting. The Commission proposed restricting the use of pinoxaden to one application every three years on the same field.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que a restrição foi adotada; é proposta em relatório de renovação revisto, ainda em circulação. E não sei se os rótulos italianos do EDAPTIS e do MEZAYO já preveem intervalo plurianual.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026, ponto 13','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','6 produtos ADAMA Itália com pirimicarb: PIRIMOR 50, PIRIMOR 17,5, APHOX, APHOX 50, XINTECH 50, MAVRIK JET (vencimentos n','Pirimicarb entrou na ata europeia por comparação com formetanate: a Comissão registrou que ambas pertencem à classe dos carbamatos e que as avaliações de risco das duas identificaram preocupações de saúde humana semelhantes, e que para o formetanate a EFSA confirmou risco alto para trabalhadores, operadores, residentes e circunstantes em todos os usos representativos, mesmo com todas as medidas de mitigação disponíveis.','horizonte 12 meses'::date,false,'13. Formetanate The Commission explained that formetanate and pirimicarb both belong to the carbamate class and that the risk assessments for both substances identified similar human health concerns. […] To ensure consistent decision-making among both substances, the Commission shared a summary of revised risk assessment of formetanate for operators, workers, residents and bystanders using the OPEX Guidance of 2022 that was provided by the RMS.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30'::date,'MEDIA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova que o pirimicarb terá o mesmo desfecho do formetanate. A ata descreve o risco ALTO como conclusão sobre o FORMETANATE; sobre o pirimicarb diz apenas ''preocupações semelhantes'' e registra que a avaliação dele usou a orientação OPEX de 2022 enquanto a do formetanate usava a de 2014. Confiança MÉDIA por isso.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026, pontos 7 e 8','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','fosetyl: 5 produtos (MOMENTUM, MOVER, VANGUARD, RIMENSIS, MOMENTUM PFNPE, venc. nacional 31/10/2026; UE 31/01/2028) · di','Duas substâncias do portfólio estão explicitamente em espera na agenda europeia até que a EFSA atualize a conclusão: fosetyl e diflufenican. Para o diflufenican a Comissão informou que virá um novo mandato à EFSA para refinar a avaliação de risco do compartimento aquático, avaliar estudos de TFA e checar os co-formulantes.','horizonte 12 a 24 meses'::date,false,'7. Fosetyl (on hold until updated of EFSA Conclusion) […] 8. Diflufenican (on hold until update of EFSA Conclusion) The Commission informed the Member States on the upcoming mandate to EFSA to refine the aquatic compartment risk assessment, assess some TFA studies and check the co-formulants.','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova quando a EFSA voltará, nem em que direção. ''On hold'' é ausência de decisão, não sinal de resultado. TFA (ácido trifluoroacético) aparece no texto sem definição — não sei o peso que a Comissão dá a esses estudos.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Ministero della Salute, DGISAN Ufficio 7 — COMUNICATO de 23 de julho de 2026 (publicado no portal em 13/08/2026)','https://www.trovanorme.salute.gov.it/norme/renderFitoPdf?codleg=113880&anno=2026&parte=1',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.trovanorme.salute.gov.it/norme/renderFitoPdf?codleg=113880&anno=2026&parte=1' or 'https://www.trovanorme.salute.gov.it/norme/renderFitoPdf?codleg=113880&anno=2026&parte=1' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','produtos com METALAXYL-M que tenham uso de tratamento de sementes','O Ministero della Salute publicou comunicado exigindo que os titulares de autorizações de produtos com metalaxyl-M apresentem, em até 30 dias da publicação, rótulo adequado ao Reg. (UE) 2026/1353; e, enquanto o processo de reetiquetagem corre, a frase antiga sobre semear apenas em estufa passa a ser substituída pela obrigação de usar semeadura de precisão. Para espinafre, densidade máxima de 2.000.000 de sementes/ha.','horizonte 3 meses'::date,false,'per i prodotti attualmente autorizzati che riportano in etichetta utilizzi conformi alle disposizioni riportate negli allegati del regolamento 2026/1353, le Imprese titolari delle autorizzazioni sono tenute a presentare, entro e non oltre 30 giorni dalla pubblicazione del presente comunicato, per ogni prodotto fitosanitario autorizzato un''etichetta adeguata […] "L''utilizzo per la concia delle sementi ai fini della semina in campo delle sementi conciate comporta obbligatoriamente l''uso di attrezzature per la semina di precisione."','https://www.trovanorme.salute.gov.it/norme/renderFitoPdf?codleg=113880&anno=2026&parte=1','2026-07-23 (comunicado); 2026-08-13 (publicação no portal)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova que os 2 produtos ADAMA com metalaxy-M (FOLPAN GOLD e SESTO GOLD, ambos FOLPET+METALAXYL-M) sejam atingidos: na leitura de rótulo do pacote os dois aparecem como fungicidas de VIDEIRA, não como conciantes de sementes. A obrigação vale para quem tem uso de concia no rótulo. NÃO SEI se algum dos dois tem.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Ministero della Salute, DGISAN Ufficio 7 — Decreto direttoriale de 31/08/2026 (Trovanorme id 114233)','https://www.trovanorme.salute.gov.it/norme/dettaglioAtto?id=114233',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.trovanorme.salute.gov.it/norme/dettaglioAtto?id=114233' or 'https://www.trovanorme.salute.gov.it/norme/dettaglioAtto?id=114233' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','MECANISMO_NACIONAL','A revogação italiana por falta de apoio à renovação está viva e é recente: decreto direttoriale de 31/08/2026 revoga duas autorizações depois de o titular comunicar por PEC, em 04/08/2026, que renunciava aos produtos.','2 dias antes da data de referência'::date,false,'Sono revocate, a seguito della manifesta volontà di non supportare ulteriormente il rinnovo secondo Art. 43 del Regolamento 1107/2009, le autorizzazioni dei prodotti fitosanitari CLOUD TUTA (aut. n. 18112) e CLOUD LOBE (aut. n. 18113), UPL HOLDINGS COÖPERATIEF U.A.','https://www.trovanorme.salute.gov.it/norme/dettaglioAtto?id=114233','2026-08-31'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não tem relação com a ADAMA: os dois produtos são da UPL, à base de feromônios. É o mecanismo que interessa, não o caso. E não é oportunidade comercial: não sei se havia demanda, nem quem atendia esses usos.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database cruzado com adama-italy-products.json (registro Ministero PROD_FTS_6_20260824)','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances',ARRAY['REGULATORIO','CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','dicamba: MILHO (PYXIDES WG, DICAMBA+NICOSULFURON+MESOTRIONE, reg. 015909)','Em seis substâncias a data nacional italiana do produto vai ALÉM da data europeia da substância. A maior distância é do dicamba: aprovação UE até 31/03/2027, produto italiano com vencimento em 31/05/2033 — mais de seis anos de diferença.',NULL::date,false,'"AS_NAME":"Dicamba","APPROVAL_DT":"01\/01\/2009","EXPIRY_OF_APPROVAL_DT":"31\/12\/2021","EXTENSION_OF_APPROVAL_DT":"31\/03\/2027","EXPIRY_DT":"31\/03\/2027"','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances','2026-09-02 (leitura da base) vs 2026-08-24 (dataset nacional)'::date,'MEDIA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova irregularidade nem erro de ninguém. A data nacional de uma autorização de produto e a data europeia de aprovação de uma substância são coisas diferentes, com relógios diferentes; a nacional costuma ser revista quando a europeia se resolve. Também não sei se o dataset nacional de 24/08/2026 já incorporou as prorrogações europeias de junho e julho de 2026 — para phenmedipham e fludioxonil claramente não incorporou. Confiança MÉDIA.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('EU Pesticides Database — busca completa (1.483 registros) e lista de tipos','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances',ARRAY['REGULATORIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' or 'https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','cloquintocet-mexyl acompanha os 10 produtos de clodinafop; mefenpir-dietil e isoxadifen-etil, 1 produto cada','Três substâncias declaradas em produtos ADAMA Itália não aparecem nos 1.483 registros da lista europeia de substâncias ativas, protetores e sinérgicos: cloquintocet-mexyl (10 produtos), isoxadifen-etil (1) e mefenpir-dietil (1). As três são protetores (safeners) — e a própria base tem um tipo ''Safener'' entre os filtros.',NULL::date,false,'"altTypes": [{"bitmap": 1, "type": "Basic Substance Application"}, {"bitmap": 2, "type": "Low risk Active substance"}, {"bitmap": 3, "type": "Candidate for Substitution"}, {"bitmap": 4, "type": "Safener"}, {"bitmap": 8, "type": "Microorganism"}, {"bitmap": 5, "type": "Synergist"}]','https://ec.europa.eu/food/plant/pesticides/eu-pesticides-database/start/screen/active-substances','2026-09-02 (leitura da base)'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','AUSÊNCIA NA NOSSA LEITURA NÃO É AUSÊNCIA NO MUNDO. Não prova que esses protetores não estejam regulados na UE, nem que não tenham data. NÃO SEI onde o estado deles é publicado — pode ser em outra tela da mesma base, ou pode ser que o programa de trabalho para protetores ainda não tenha produzido decisões.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Retificação do Regulamento de Execução (UE) 2023/2660 (JO L, 2026/90622, 24.7.2026)','http://data.europa.eu/eli/reg_impl/2023/2660/corrigendum/2026-07-24/oj',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='http://data.europa.eu/eli/reg_impl/2023/2660/corrigendum/2026-07-24/oj' or 'http://data.europa.eu/eli/reg_impl/2023/2660/corrigendum/2026-07-24/oj' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','11 produtos ADAMA Itália com glifosato (venc. nacional 15/12/2034; aprovação UE até 15/12/2033)','Saiu em 24/07/2026 uma retificação do regulamento que renovou o glifosato. É correção puramente tipográfica: a especificação de impureza N-nitroso-glifosato tinha sido publicada com o sinal de ''menor que'' escapado como código de HTML.',NULL::date,false,'On page 7, in the third column of the table of Annex I, second paragraph, first indent: for: ''N-nitroso-glyphosate (NNG): &amp;lt; 1 mg/kg'', read: ''N-nitroso-glyphosate (NNG): < 1 mg/kg''.','http://data.europa.eu/eli/reg_impl/2023/2660/corrigendum/2026-07-24/oj','2026-07-24'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não muda nada de substantivo. Vale registrar exatamente para que ninguém leia ''retificação do regulamento do glifosato em 2026'' e imagine mudança de mérito. Este ato não seria pego por busca de CELEX começando em 32026 — ele é 32023R2660R(02).') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SCoPAFF Phytopharmaceuticals – Legislation, Summary Report 29-30/06/2026, ponto A.19; e planeamento de reuniões 2026 do PAFF','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' or 'https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','CALENDARIO_DE_DECISAO','A próxima reunião do comitê europeu que decide sobre aprovação de substâncias (SCoPAFF, secção Fitofarmacêuticos-Legislação) está marcada para 24 e 25 de setembro de 2026. Até 02/09/2026 não há agenda nem relatório publicados para ela na nossa leitura.','horizonte 3 meses'::date,false,'A.19 Date of next meeting(s): The Commission confirmed that the next meeting of this Committee would take place on 24 and 25 September 2026 (hybrid meeting).','https://food.ec.europa.eu/document/download/e1f018bc-7c71-4a00-8880-bb58829b91ee_en?filename=sc_phyto_20260629_ppl_sum.pdf','reunião de 2026-06-29/30'::date,'ALTA','ver o_que; a conversao em oportunidade comercial NAO e automatica','não prova que qualquer um desses itens entrará na pauta desse dia. A tabela de planeamento de 2026 mostra ainda colunas de reunião em novembro e dezembro, mas a associação coluna-mês foi lida por alinhamento visual e não é citação literal — só as datas de 24-25/09 estão confirmadas por duas fontes.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('adama-italy-products.json, derivado de Ministero della Salute — PROD_FTS_6_20260824','https://www.dati.salute.gov.it',ARRAY['REGULATORIO','CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.sinal_regulatorio_futuro (fonte_id, tipo, substancia_literal, o_que, quando, decisao_tomada, citacao_literal, source_url, publicado_em, confianca, por_que_pode_importar, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.dati.salute.gov.it' or 'https://www.dati.salute.gov.it/' like url_base||'%' order by length(url_base) desc limit 1),'PRORROGACAO_DE_APROVACAO','CAUTELA_DE_LEITURA','No dataset nacional usado pelo pacote (PROD_FTS_6_20260824), 11 registros ADAMA têm vencimento em 15/08/2026 — data ANTERIOR à data de referência de 02/09/2026. São os 6 de cymoxanil e parte dos de azoxystrobin e tebuconazole.',NULL::date,false,'"NOTE": "Registro do Ministero della Salute, versao PROD_FTS_6_20260824, capturado em 2026-08-30. 163 vigentes."','https://www.dati.salute.gov.it/','2026-08-24 (dataset) / 2026-08-30 (captura)'::date,'MEDIA','ver o_que; a conversao em oportunidade comercial NAO e automatica','NÃO prova que esses produtos saíram do mercado. Vencimento de autorização costuma vir acompanhado de prazo de escoamento de estoque, e o Ministero publica prorrogações. NÃO SEI o estado administrativo atual desses 11 registros — isso exigiria reler a banca dati hoje.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('European Commission, Joint Research Centre — European Drought Observatory (EDO), "Current drought situation in Europe"','https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en' or 'https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en' like url_base||'%' order by length(url_base) desc limit 1),'Italia — norte, centro e localmente centro-sul','MACROAREA','OUTRA',NULL,'alert (norte) / warning (norte e centro) / watch (Italia) / normal-recovery (local centro-sul)','classe do CDI (watch, warning, alert)',coalesce('2026-08-26'::date,'2026-08-01'),coalesce('2026-08-26'::date,'2026-09-02'),'CURRENT','https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en','2026-08-26'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: um nivel de alerta de seca nao indica, nem sugere, que exista peronospora, oidio, repilo, ferrugem, percevejo ou qualquer outro organismo em qualquer lavoura. Tambem nao prova perda de produtividade nem area afetada. "Norte da Italia" e uma area no mapa, nao a regiao Veneto, nem Lombardia, nem Piemonte, nem Emilia-Romagna: o CDI e uma grade de cerca de 5 km e nao respeita fronteira administrativa, entao NAO se pode dizer "Veneto esta em alerta" a partir desta linha. E uma decada de 10 dias, nao o estado de hoje.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('European Commission, Joint Research Centre — EDO, nota metodologica da analise de meados de agosto de 2026','https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en' or 'https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en' like url_base||'%' order by length(url_base) desc limit 1),'dominio europeu do EDO (impacto declarado como maior na Russia ocidental)','REGIONAL','OUTRA',NULL,'cautela na leitura do CDI, da anomalia de umidade do solo e do LFI','ressalva metodologica',coalesce('2026-08-26'::date,'2026-08-01'),coalesce('2026-08-26'::date,'2026-09-02'),'CURRENT','https://joint-research-centre.ec.europa.eu/european-and-global-drought-observatories/current-drought-situation-europe_en','2026-08-26'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA — e esta linha nem sequer e uma condicao climatica, e uma ressalva sobre o instrumento. Nao prova que o CDI da Italia esteja errado; a fonte aponta a Russia ocidental como area mais afetada. Nao prova magnitude do erro.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('JRC MARS Bulletin — Crop monitoring in Europe, Vol. 34 No 7, "Long-lasting dry and hot weather slashes summer crop yields"','https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf' or 'https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf' like url_base||'%' order by length(url_base) desc limit 1),'Italia (com o dado de chuva referido ao NOROESTE do pais)','REGIONAL','OUTRA',NULL,'~2 de 3 dias com Tmax > 35 °C; precipitacao ~50% abaixo da media de longo prazo (noroeste)','dias (proporcao) e por cento em relacao a media de longo prazo (LTA)',coalesce('2026-08-24'::date,'2026-08-01'),coalesce('2026-08-24'::date,'2026-09-02'),'CURRENT','https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf','2026-08-24'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: calor e falta de chuva nesta linha nao provam que exista qualquer praga ou patogeno em campo, nem que a pressao de doenca tenha subido ou caido. "Italia" e o pais inteiro: esta linha NAO representa Veneto, Puglia ou qualquer regiao especifica, e o numero de chuva vale so para o noroeste. O periodo termina em 15 de agosto: nao descreve o fim de agosto nem setembro. Nao e sell-in, sell-out, demanda nem oportunidade comercial.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('JRC MARS Bulletin, Vol. 34 No 7, secao "Areas of concern"','https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf' or 'https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf' like url_base||'%' order by length(url_base) desc limit 1),'norte e centro da Italia','MACROAREA','OUTRA',NULL,'impacto SEVERO (categoria mais alta do boletim, ao lado de "moderate" e "alerts")','classe qualitativa de impacto do boletim',coalesce('2026-08-24'::date,'2026-08-01'),coalesce('2026-08-24'::date,'2026-09-02'),'CURRENT','https://publications.jrc.ec.europa.eu/repository/bitstream/JRC146187/JRC146187_01.pdf','2026-08-24'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: "impacto severo" aqui e sobre estresse abiotico (calor e agua), nao sobre organismo vivo; nenhuma praga ou doenca e citada. Nao prova perda medida em campo — sao simulacoes e sensoriamento remoto do proprio JRC, nao levantamento de lavoura. Nao prova nada sobre a Puglia nem sobre a Sicilia, que nao estao nesta categoria.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Autorita di Bacino Distrettuale del Fiume Po — Aggiornamento settimanale situazione idrologica','https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026' or 'https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026/' like url_base||'%' order by length(url_base) desc limit 1),'distrito hidrografico do rio Po (Piemonte, Lombardia, Emilia-Romagna, Veneto)','REGIONAL','OUTRA',NULL,'SFI = seca extrema; vazao em Pontelagoscuro = 787; limiar critico de intrusao salina = 450','classe do indice SFI; metros cubicos por segundo (m3/s)',coalesce('2026-08-27'::date,'2026-08-01'),coalesce('2026-08-27'::date,'2026-09-02'),'CURRENT','https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026/','2026-08-27'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: vazao de rio nao diz nada sobre presenca de patogeno ou inseto em lavoura. Tambem nao prova disponibilidade de agua para uma fazenda especifica: vazao no rio nao e agua no hidrometro do produtor. Um valor de um dia (25 de agosto) nao descreve o mes; a propria fonte diz que nas duas primeiras decadas de agosto as vazoes estiveram constantemente abaixo da vazao caracteristica de estiagem.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Autorita di Bacino Distrettuale del Fiume Po — Aggiornamento settimanale situazione idrologica','https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026' or 'https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026/' like url_base||'%' order by length(url_base) desc limit 1),'norte da Italia — lagos que servem Piemonte, Lombardia e Veneto','AREAL','OUTRA',NULL,'Maggiore 39; Como 55; Iseo 44; Idro 20; Garda 34','por cento de enchimento do volume regulado; classe do indice SVI',coalesce('2026-08-27'::date,'2026-08-01'),coalesce('2026-08-27'::date,'2026-09-02'),'CURRENT','https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026/','2026-08-27'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: nivel de lago nao mede praga nem patogeno. Nao prova restricao de irrigacao em nenhuma propriedade — a mesma fonte informa que a razao entre captacao efetiva e concedida estava em torno de 40 por cento, ou seja, a demanda ja estava caindo por fim de ciclo. Porcentagem de enchimento nao e volume absoluto comparavel entre lagos de tamanhos diferentes.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Autorita di Bacino Distrettuale del Fiume Po — Scenario di Severita Idrica dal 27 agosto','https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026' or 'https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026/' like url_base||'%' order by length(url_base) desc limit 1),'distrito do rio Po; mencao especifica as subbacias alpinas do territorio lombardo','REGIONAL','OUTRA',NULL,'melhora observada sobre fundo de seca extrema; captacao efetiva sobre concedida ~40 por cento; nas subbacias alpinas lombardas as reservas subiram a um estado de severidade MEDIA','classe de severidade hidrica; por cento (razao de captacao)',coalesce('2026-08-27'::date,'2026-08-01'),coalesce('2026-08-27'::date,'2026-09-02'),'CURRENT','https://www.adbpo.it/aggiornamento-settimanale-situazione-idrologica-27-08-2026/','2026-08-27'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: nem a seca nem a chuva forte descritas aqui provam presenca de qualquer organismo em lavoura. Nao converter em oportunidade comercial: melhora hidrica nao e sinal de compra, e criticidade nao e sinal de venda. Nao prova o estado de setembro — a reuniao seguinte do Osservatorio so estava marcada para 15/09/2026.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Arpae Emilia-Romagna — Bollettino AgroMeteorologico Settimanale n. 34/2026','https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf' or 'https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf' like url_base||'%' order by length(url_base) desc limit 1),'Emilia-Romagna','REGIONAL','OUTRA',NULL,'ate ~300 mm em um dia (local, cume centro-ocidental); anomalia semanal de +200 a +300 mm (cume parmense); >50 mm em Romagna em 17/08; >100 mm no Apenino ocidental em 20/08','milimetros (mm) de chuva',coalesce('2026-08-24'::date,'2026-08-01'),coalesce('2026-08-24'::date,'2026-09-02'),'CURRENT','https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf','2026-08-24'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: chuva intensa NAO prova infeccao, NAO prova peronospora, NAO prova pressao de doenca subindo. Chuva e condicao, nao evento biologico. O valor de quase 300 mm e LOCAL, no cume centro-ocidental: nao vale para a planicie, nao vale para a regiao, e a propria fonte diz que entre Rimini e Forli-Cesena os valores ficaram na media. Uma semana nao e o mes nem a estacao.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Arpae Emilia-Romagna — Bollettino AgroMeteorologico Settimanale n. 34/2026','https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf' or 'https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf' like url_base||'%' order by length(url_base) desc limit 1),'Emilia-Romagna','REGIONAL','OUTRA',NULL,'fracao de agua disponivel 0 a 0,2 na planicie; balanco hidrico anual ate -200 mm; anomalia de chuva acumulada desde o inicio do ano de ate -35 por cento na planicie e +15 por cento no ferrarese','fracao adimensional (0 a 1); milimetros; por cento',coalesce('2026-08-24'::date,'2026-08-01'),coalesce('2026-08-24'::date,'2026-09-02'),'CURRENT','https://www.arpae.it/it/temi-ambientali/meteo/report-meteo/bollettini-e-rapporti-agrometeo/bollettini-agrometeo/bollettini-2026/34_boll_agro_20260824.pdf','2026-08-24'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: umidade de solo, seja baixa ou alta, nao prova presenca de patogeno de solo, de nematoide ou de qualquer praga. Nao prova estresse de uma lavoura especifica: a fracao e um mapa modelado, nao uma leitura na raiz do talhao. "Toda a planicie" e a planicie da Emilia-Romagna, nao a planicie padana inteira.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPA Lombardia — Bollettino Agrometeorologico della Lombardia','https://starpaumbracoprdprd.blob.core.windows.net/bollettini/archivio/agrometeo/bollettino/bollettino.pdf',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://starpaumbracoprdprd.blob.core.windows.net/bollettini/archivio/agrometeo/bollettino/bollettino.pdf' or 'https://starpaumbracoprdprd.blob.core.windows.net/bollettini/archivio/agrometeo/bollettino/bollettino.pdf' like url_base||'%' order by length(url_base) desc limit 1),'Lombardia','REGIONAL','OUTRA',NULL,'Tmax 34,2 (Brescia, 28/08) e 34,0 (Cremona, 28/08); chuva 73,0 (Tremezzo-CO, 25/08), 70,2 (Ardesio-BG, 25/08), 66,6 (Gordona-SO, 28/08), 43,8 (Landriano-PV, 28/08); rajadas proximas de 120 km/h em Pavia, Cremona e Mozzanica-BG em 28/08','graus Celsius; milimetros; quilometros por hora',coalesce('2026-08-31'::date,'2026-08-01'),coalesce('2026-08-31'::date,'2026-09-02'),'CURRENT','https://starpaumbracoprdprd.blob.core.windows.net/bollettini/archivio/agrometeo/bollettino/bollettino.pdf','2026-08-31'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: nem o calor nem os 73 mm de chuva provam presenca de qualquer praga ou patogeno. Cada numero vale para UMA estacao em UM dia — 73 mm em Tremezzo nao e 73 mm na Lombardia. A data de publicacao 2026-08-31 e inferida do periodo coberto: o PDF e sobrescrito a cada semana e nao traz data de emissao no cabecalho extraido; a URL nao contem data. Isso reduz a rastreabilidade se alguem quiser reabrir a mesma versao depois.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPAV — Bollettino Agrometeorologico Regionale N. 21 del 01.09.2026','https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file' or 'https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file' like url_base||'%' order by length(url_base) desc limit 1),'Veneto','REGIONAL','OUTRA',NULL,'temperaturas "bem superiores a norma"; precipitacao ausente na planicie, salvo chuvas locais na montanha','descricao qualitativa oficial (a fonte nao publica o desvio em graus nesta secao)',coalesce('2026-09-01'::date,'2026-08-01'),coalesce('2026-09-01'::date,'2026-09-02'),'OUTLOOK','https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file','2026-09-01'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: previsao de calor e tempo seco nao prova nem ausencia nem presenca de peronospora, oidio, botrytis ou qualquer outro organismo. Isto e PREVISAO, nao observacao: o que esta escrito e o que o modelo esperava em 02/09/2026, nao o que aconteceu. "Bem superiores a norma" e frase, nao numero: sem o desvio em graus, nao da para comparar com outra regiao nem com outro ano. O arquivo PDF e sobrescrito a cada semana.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPA Piemonte — Bollettino Meteo n. 279/2026','https://www.arpa.piemonte.it/rischi_naturali/boll/bollettino_meteotestuale.pdf',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpa.piemonte.it/rischi_naturali/boll/bollettino_meteotestuale.pdf' or 'https://www.arpa.piemonte.it/rischi_naturali/boll/bollettino_meteotestuale.pdf' like url_base||'%' order by length(url_base) desc limit 1),'Piemonte','REGIONAL','OUTRA',NULL,'maximas de 33 a 35 na planicie; zero termico ate 4.800; confiabilidade declarada de 95 por cento para 02/09 e 90 por cento para 03/09','graus Celsius; metros; por cento de confiabilidade',coalesce('2026-09-02'::date,'2026-08-01'),coalesce('2026-09-02'::date,'2026-09-02'),'OUTLOOK','https://www.arpa.piemonte.it/rischi_naturali/boll/bollettino_meteotestuale.pdf','2026-09-02'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: calor previsto nao prova infestacao nem infeccao em videira, milho, arroz ou qualquer cultura do Piemonte. E PREVISAO, nao medicao — a propria fonte da confiabilidade de 80 a 95 por cento. E boletim de TEMPO, nao agrometeorologico: nao traz ETP, umidade do solo nem molhamento foliar. O arquivo e sobrescrito a cada emissao, entao esta URL nao devolvera este mesmo boletim depois.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Piemonte / ARPA Piemonte — Bollettino Agrometeorologico','https://www.regione.piemonte.it/bollettinoAgrometeorologico',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.regione.piemonte.it/bollettinoAgrometeorologico' or 'https://www.regione.piemonte.it/bollettinoAgrometeorologico/' like url_base||'%' order by length(url_base) desc limit 1),'Piemonte','REGIONAL','OUTRA',NULL,'ultima emissao publicada: 20/02/2025; 5 areas devolvendo 12.185 bytes identicos','data de emissao declarada na propria pagina',coalesce('2025-02-20'::date,'2026-08-01'),coalesce('2025-02-20'::date,'2026-09-02'),'CURRENT','https://www.regione.piemonte.it/bollettinoAgrometeorologico/','2025-02-20'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA — e este registro nem e uma condicao climatica: e o estado de um canal de publicacao. NAO prova que o Piemonte deixou de medir agrometeorologia: prova apenas que ESTA pagina publica nao foi atualizada. Os dados podem existir em outro canal (por exemplo a Banca Dati Storica da ARPA Piemonte) que nao foi testado aqui. Ausencia na nossa leitura nao e ausencia no mundo.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SIAS — Servizio Informativo Agrometeorologico Siciliano, consultazione per grandezza, precipitazioni','http://www.sias.regione.sicilia.it/NHEOWL0060_00.html',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='http://www.sias.regione.sicilia.it/NHEOWL0060_00.html' or 'http://www.sias.regione.sicilia.it/NHEOWL0060_00.html' like url_base||'%' order by length(url_base) desc limit 1),'Sicilia','REGIONAL','OUTRA',NULL,'95 de 96 estacoes com 0,0; Riposto com 6,6; Catania, Siracusa, Lentini, Caltagirone, Palermo, Marsala e Trapani todas em 0,0','milimetros de chuva no dia',coalesce('2026-08-31'::date,'2026-08-01'),coalesce('2026-08-31'::date,'2026-09-02'),'CURRENT','http://www.sias.regione.sicilia.it/NHEOWL0060_00.html','2026-08-31'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: dia sem chuva nao prova ausencia de repilo na oliveira, nem presenca de acaro, nem nada de biologico. Um dia nao e o mes: 30 de agosto sem chuva nao diz o que ocorreu no resto de agosto. A pagina foi lida em 02/09/2026 mas o ultimo dia fechado era 30/08 — ha atraso de dois dias entre a data de referencia e o dado disponivel. 96 estacoes com dado nao e a rede inteira: estacoes sem dado nao foram contadas e nao sabemos por que faltaram.') on conflict do nothing;
