insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://wmo.int/media/update/global-seasonal-climate-update-july-august-september-2026' or 'https://wmo.int/media/update/global-seasonal-climate-update-july-august-september-2026' like url_base||'%' order by length(url_base) desc limit 1),'sul da Europa (macro-regiao; a Italia nao e tratada isoladamente)','REGIONAL','OUTRA',NULL,'probabilidade aumentada de chuva acima do normal no sul da Europa (concordancia baixa a moderada); Nino 3.4 ~2,0','probabilidade relativa (terços climatologicos); graus Celsius (indice Nino 3.4)',coalesce('2026-07-03'::date,'2026-08-01'),coalesce('2026-07-03'::date,'2026-09-02'),'OUTLOOK','https://wmo.int/media/update/global-seasonal-climate-update-july-august-september-2026','2026-07-03'::date,'⚠️ A CONDICAO CLIMATICA NAO ESTABELECE PRESENCA DE PRAGA OU DOENCA: uma probabilidade sazonal nao produz e nao indica praga nem doenca em lavoura nenhuma. ⚠️ CHOCA-SE COM O QUE FOI MEDIDO: o sinal era de chuva acima do normal no sul da Europa, e na pratica Foggia somou 2,5 mm e a Sicilia teve 95 de 96 estacoes secas em 30/08 — previsao sazonal de chuva tem baixa habilidade e nao deve virar afirmacao. "Sul da Europa" nao e a Italia, e a Italia nao e uma regiao. Confidence BAIXA.') on conflict do nothing;
