insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Bayer Crop Science Italia — Magazine / News / Estensione d''impiego eccezionale','https://www.cropscience.bayer.it/Magazine/News/Estensione-Eccezionale/Challenge-pomodoro-post-trapianto',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','concorrente','organizacao_e_conteudo','pomodoro da industria','Italia (nacional — decreto do Ministero della Salute)','Bayer Italia publica no proprio site que o Ministero della Salute autorizou, em 25/05/2026, a extensao de uso excepcional do herbicida Challenge em tomate de industria em campo aberto, pos-transplante, valida por 120 dias','120','dias de validade da autorizacao','autorizacao valida de 2026-05-25 a 2026-09-21','CURRENT','Il Ministero della Salute in data 25 maggio 2026 ha autorizzato l''estensione d''impiego eccezionale del formulato Challenge su pomodoro in pieno campo in post-trapianto. La presenta autorizzazione ha validita di 120 giorni (dal 25 maggio al 21 settembre 2026).','https://www.cropscience.bayer.it/Magazine/News/Estensione-Eccezionale/Challenge-pomodoro-post-trapianto','2026-06-10'::date,'ALTA','NAO prova que o produto foi aplicado, nem em que area. NAO prova presenca da doenca ou da infestante no campo. Extensao excepcional de uso NAO e registro definitivo, e o fim da janela em 21/09/2026 sera EXPIRY, nunca WITHDRAWAL. NAO prova nada sobre venda, estoque ou participacao de mercado.',false) on conflict do nothing;
