insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','concorrente','organizacao_e_conteudo','nocciolo, barbabietola da zucchero, mais, pero, erba medica, pomodoro, melanzana, cipolla, melo','Italia (nacional)','Um unico artigo da AgroNotizie de 21/05/2026 lista 12 autorizacoes em derrogacao e 6 mudancas de rotulo comunicadas pelas empresas entre 16/04 e 14/05/2026, nomeando BASF, Corteva, Syngenta e UPL entre outras','12','autorizacoes em derrogacao no periodo (mais 6 mudancas de rotulo)','comunicacoes obrigatorias de 2026-04-16 a 2026-05-14','CURRENT','Basf Italia : dal 28 aprile 2026 al 25 agosto 2026 deroga per il fungicida Revysion , a base di mefentrifluconazolo , per il contenimento dell''oidio del nocciolo ( Erysiphe corylacearum e Phyllactinia corylicola ). Corteva agriscience : con Decreto Ministeriale del 20 Aprile 2026 e stato autorizzato l''uso di emergenza di Univoq , a base di fenpicoxamid e protioconazolo , per il controllo della cercosporiosi su barbabietola da zucchero, da foraggio e da seme. [...] Syngenta Italia : dal 7/05/2026 al 3/09/2026 e stato autorizzato in deroga Nermady 2026 , contenente 8-metildecan-2-il propanoato , feromone per la confusione sessuale di Diabrotica virgifera nel mais. [...] Upl Italia : dal 28 aprile al 25 agosto 2026, deroga per Folder 80 WG , contenente folpet , per l''impiego su pero contro maculatura bruna ( Stemphylium vesicarium ).','https://agronotizie.imagelinenetwork.com/difesa-e-diserbo/2026/05/21/agrofarmaci-inampout-cosa-entra-cosa-esce-cosa-cambia/89287','2026-05-21'::date,'ALTA','NAO prova aplicacao no campo nem presenca da avversita. Derrogacao e autorizacao temporaria (art. 53), NAO e registro definitivo — e o fim da janela sera EXPIRY, nunca WITHDRAWAL. A lista de «Out» do mesmo artigo mistura ultima comercializacao com ultimo uso permitido: sao datas diferentes e nao devem ser somadas. NAO prova volume, venda nem intencao comercial.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Bayer Crop Science Italia — Magazine / News — «Arriva Mais Lab, il nuovo podcast dedicato alla coltivazione del Mais!»','https://www.cropscience.bayer.it/Magazine/News/Generica/Mais-Lab',ARRAY['CATALOGO_FABRICANTE']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','concorrente','organizacao_e_conteudo','mais','Italia (nacional; canal YouTube «Bayer Crop Science Italia»)','A Bayer Italia montou o podcast «Mais Lab» em tres episodios sobre diserbo do milho (10/03, 19/03 e 09/04/2026) e depois uma segunda temporada gravada em campo — e esta campanha explica dois videos que ja estavam soltos no pacote','3','episodios na primeira temporada','2026-03-10 a 2026-04-09, mais uma segunda temporada sem data declarada','HISTORICAL','Mais Lab e il podcast firmato Bayer Crop Science che mette a disposizione di tecnici, agronomi e aziende maidicole esperienze di campo, dati e raccomandazioni operative sul diserbo del mais. [...] Nella prima puntata, in uscita il 10 marzo 2026 [...] online dal 19 marzo sul canale YouTube di Bayer Crop Science Italia. [...] In data 9 aprile e previsto il lancio della terza puntata, in cui vengono condivise strategie concrete per la gestione della sorghetta in post-emergenza','https://www.cropscience.bayer.it/Magazine/News/Generica/Mais-Lab','2026-03-10 (data do primeiro episodio declarada na propria pagina; a pagina nao mostra data de publicacao separada)'::date,'ALTA','NAO prova audiencia, alcance nem efeito. NAO prova que agricultor italiano ouviu ou mudou de conduta. NAO prova presenca de infestante resistente em nenhum campo especifico — o texto fala de tendencia, nao de medicao. NAO prova venda de Adengo Xtra.',false) on conflict do nothing;
