insert into public.fonte_externa (nome, url_base, natureza, pais) values ('AgroNotizie (Image Line) — Agronomia — «Pignatelli Day 2026: una giornata dedicata a mais e soia»','https://agronotizie.imagelinenetwork.com/agronomia/2026/08/03/pignatelli-day-2026-una-giornata-dedicata-a-mais-e-soia/89596',ARRAY['IMPRENSA_TECNICA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','concorrente','organizacao_e_conteudo','mais e soia','Piemonte — Villafranca Piemonte (TO)','Os dias de campo italianos de 2026 que consegui documentar sao organizados por consorzio, cooperativa e fundacao — e as paginas publicas que li NAO nomeiam nenhuma das 6 empresas do universo monitorado','90 e 30','hibridos de milho e variedades de soja expostos nos campos prova','evento em 2026-08-28','HISTORICAL','Venerdi 28 agosto 2026 alla Fondazione Podere Pignatelli a Villafranca Piemonte (To) si terra il tradizionale "Pignatelli Day: Mais e Soia", la giornata dimostrativa dedicata alle due coltivazioni. L''iniziativa riunira tecnici, agricoltori, rivenditori, contoterzisti, professionisti e studenti [...] sara possibile visitare i campi prova, con l''esposizione di 90 ibridi di mais e oltre 30 varieta di soia.','https://agronotizie.imagelinenetwork.com/agronomia/2026/08/03/pignatelli-day-2026-una-giornata-dedicata-a-mais-e-soia/89596','2026-08-03'::date,'ALTA','⚠️ NAO prova que BASF, Bayer, Corteva, Syngenta, FMC ou UPL estiveram ou nao estiveram nesses dias de campo. A materia nao cita empresa de defensivo nenhuma. NAO inferir participacao a partir de «sementeiras e as maiores empresas do setor». E NAO concluir que os concorrentes nao fazem field day — concluir apenas que nao encontrei publicacao propria deles sobre isso; a lacuna continua aberta e vale coleta dirigida por empresa.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('l''OlivoNews — artigo assinado por Enzo Gambin, secao ''aipo''','https://olivonews.it/lotta-mosca-2026-nuove-norme-oliva-matura-in-anticipo',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','OLIVE','NAO DECLARADA no artigo','O diretor da AIPO (associacao interregional de produtores olivicolas, sede em Verona) escreveu em 27/08/2026 que, apesar de o clima ter voltado a favorecer a mosca da azeitona, os dados de campo mostravam pressao ainda baixa e desigual.',NULL,NULL,'fim de agosto de 2026','CURRENT','i dati di campo mostrano una pressione ancora bassa e disomogenea','https://olivonews.it/lotta-mosca-2026-nuove-norme-oliva-matura-in-anticipo/','2026-08-27'::date,'ALTA','Nao diz QUAIS areas foram observadas, nao traz numero de capturas nem denominador (quantas armadilhas, quantos olivais), nao prova ausencia de mosca em nenhum olival concreto, nao representa a Italia nem uma regiao, e ''pressao baixa em 27/08'' nao vale para setembro nem para a colheita. Clima favoravel tambem nao e presenca do inseto.',false) on conflict do nothing;
