insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','MAIZE','Ravalle, provincia de Ferrara, Emilia-Romagna','Um agricultor de terceira geracao, com propriedade em Ravalle (Ferrara), declarou em 11/08/2026 ter perdido toda a colheita de milho em mais de 16 hectares por causa da seca e do calor.','16','hectares (declarados pelo proprio agricultor)','inicio de agosto de 2026','CURRENT','Oltre 16 ettari, ho perso tutto il raccolto, il lavoro di mesi','https://www.ilrestodelcarlino.it/ferrara/economia/viaggio-nel-deserto-padano-mais-249a6029','2026-08-11'::date,'ALTA','NAO prova a perda. E declaracao do proprio interessado, sem laudo, sem pericia, sem medicao de terceiro. Nao prova perda na provincia nem na regiao — e uma propriedade. E a causa declarada e seca e calor, ou seja, NAO e presenca de doenca nem de praga.',false) on conflict do nothing;
