insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','RICE','Delta do Po — Le Contane, Riva del Po, Berra (provincia de Ferrara)','Um rizicultor que e vice-presidente do Consorzio Riso del Delta del Po e presidente regional dos rizicultores da Confagricoltura declarou em 11/08/2026 que quem estava com o arroz ainda em seco quando veio o temporal perdeu tudo.',NULL,NULL,'final de julho / inicio de agosto de 2026','CURRENT','Chi aveva il riso nel campo ancora in secca quando si è abbattuto il maltempo ha perso tutto','https://www.ilrestodelcarlino.it/ferrara/economia/viaggio-nel-deserto-padano-mais-249a6029','2026-08-11'::date,'ALTA','Nao mede area nem perda: nao ha hectares, nao ha percentual, nao ha laudo. Nao diz quantas lavouras estavam ''em seco''. E dano de granizo e vento — nao e doenca, nao e praga, e nao gera por si nenhuma oportunidade de defensivo.',false) on conflict do nothing;
