insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','MAIZE','Argenta, Anita, Longastrino, Mezzano (provincia de Ferrara)','O presidente da secao de cereais da Confagricoltura, com lavouras na zona de Argenta, declarou em 11/08/2026 perdas de cerca de 40% no milho por granizo, com picos maiores em algumas areas.','40','% de perda declarada, ''se va bene'', com picos maiores','inicio de agosto de 2026','CURRENT','Ingenti i danni al mais, siamo se va bene al 40% di perdite con punte ben più elevate in alcune zone','https://www.ilrestodelcarlino.it/ferrara/economia/viaggio-nel-deserto-padano-mais-249a6029','2026-08-11'::date,'ALTA','O 40% e estimativa declarada por um dirigente, nao medicao — ele mesmo diz ''se va bene''. Nao ha metodo, nem area total, nem denominador. Vale para as localidades citadas, nao para a provincia, nao para a Emilia-Romagna, nao para a Italia. E dano de granizo e seca, nao de doenca.',false) on conflict do nothing;
