insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','RICE (com mencao a MAIZE e SOYBEAN como alternativas)','Pianura Padana — Vercelli, Novara, Mortara','A presidente do Ente Nazionale Risi alertou em 15/06/2026 que, se o arroz deixar de ser remunerativo, os agricultores serao forcados a mudar para culturas alternativas como milho ou soja.',NULL,NULL,'junho de 2026','OUTLOOK','Se il riso smette di essere remunerativo, gli agricoltori saranno costretti a fare scelte drastiche, virando su colture alternative come mais o soia','https://askanews.it/2026/06/15/ente-risi-la-risicoltura-italiana-sta-morendo-filiera-sia-unita/','2026-06-15'::date,'ALTA','E previsao e alerta politico, NAO medicao de troca de cultura. Nao ha hectares convertidos. Para o dado real de area do arroz em 2026 ver o registro do Il Risicoltore (233.500 ha estimados, com denominador de 79% da area de 2025). Nao converter esse alerta em oportunidade comercial de milho ou soja.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Agrapress — comunicado da COPROB Italia Zuccheri','https://www.agrapress.it/2026/06/coprob-italia-zuccheri-stagione-bieticolo-saccarifera-anticipata-a-causa-del-clima-torrido',ARRAY['OUTRA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','SUGAR_BEET','areas de conferencia da COPROB, usina de Minerbio (Bolonha) e outras regioes italianas','O presidente da COPROB Italia Zuccheri (unica cooperativa acucareira italiana) anunciou em 30/06/2026 a antecipacao da campanha da beterraba para 9 de julho, justificando pelo calor torrido e pelo estado ja avancado de maturacao da cultura.',NULL,NULL,'junho/julho de 2026','CURRENT','questa decisione straordinaria è motivata dalle condizioni climatiche di caldo torrido e dunque dallo stato della coltura','https://www.agrapress.it/2026/06/coprob-italia-zuccheri-stagione-bieticolo-saccarifera-anticipata-a-causa-del-clima-torrido/','2026-06-30'::date,'ALTA','Nao mede maturacao (nenhum grau de polarizacao, nenhuma data fenologica). Nao diz nada sobre presenca de cercospora nesta safra — cercospora aparece so como tema de pesquisa, nao como ocorrencia observada. Calor NAO e doenca.',false) on conflict do nothing;
