insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','RICE','Sezione di Novara (Novarese, Piemonte)','O Servico de Assistencia Tecnica do Ente Nazionale Risi registrou, em atualizacao de 20/07/2026 publicada na revista de setembro/2026, que no Novarese as populacoes de Alisma plantago-aquatica multirresistentes continuam a se expandir e que nao existe herbicida de pos-emergencia capaz de controla-las.',NULL,NULL,'situacao atualizada a 20 de julho de 2026','CURRENT','le popolazioni di Alisma plantago aquatica multiresistenti continuano a espandersi significativamente. Queste popolazioni mostrano resistenza sia agli erbicidi ALS inibitori sia al florpyrauxifen-benzyl','https://www.enterisi.it/central/servizi/funzioni/download.aspx?type=inline&ID=118839&IDc=784&nomefile=8.Risisettembre2026_784_118839.pdf','2026-08-14'::date,'ALTA','Nao ha numero de campos, nem hectares, nem percentual de area afetada — e observacao dos tecnicos das secoes, nao levantamento com denominador. ''Multirresistente'' aqui e leitura de campo do servico tecnico, nao ensaio de resistencia publicado com metodologia. Vale para a secao de Novara; NAO vale para Vercelli, Pavia, Codigoro nem para a Italia. E nao prova falha de nenhum produto comercial especifico.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Il Risicoltore (Ente Nazionale Risi), setembro de 2026','https://www.enterisi.it/central/servizi/funzioni/download.aspx?type=inline&ID=118839&IDc=784&nomefile=8.Risisettembre2026_784_118839.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','RICE','Sezione di Vercelli (provincias de Vercelli, Biella, Alessandria e Cuneo)','O mesmo servico tecnico registrou que na secao de Vercelli ha infestacoes significativas de arroz vermelho nao controlado por inibidores de ALS e de ACCase, presenca difusa de giavone mal manejado, e que ate com a tecnologia Provisia houve casos de controle parcial.',NULL,NULL,'situacao atualizada a 20 de julho de 2026','CURRENT','anche con la tecnologia Provisia®, si sono verificati casi di controllo parziale','https://www.enterisi.it/central/servizi/funzioni/download.aspx?type=inline&ID=118839&IDc=784&nomefile=8.Risisettembre2026_784_118839.pdf','2026-08-14'::date,'ALTA','''Casos'' nao tem numero nem denominador. Nao prova falha do produto — o texto nao separa efeito de dose, momento de aplicacao, manejo de agua ou resistencia confirmada em laboratorio. Nao mede quantas lavouras. Nao autoriza dizer que a tecnologia falhou na regiao.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Il Risicoltore (Ente Nazionale Risi), setembro de 2026','https://www.enterisi.it/central/servizi/funzioni/download.aspx?type=inline&ID=118839&IDc=784&nomefile=8.Risisettembre2026_784_118839.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','RICE','Sezione di Vercelli e Sezione di Pavia (Piemonte e Lombardia)','O mesmo boletim tecnico registrou que em 20/07/2026 nao havia ataques perigosos de brusone nas secoes de Vercelli e Pavia, e que a partir de 2026 os tecnicos usam um novo modelo de previsao desenvolvido pelo Ente Nazionale Risi com a Universidade de Torino.',NULL,NULL,'situacao atualizada a 20 de julho de 2026','CURRENT','attualmente non si riscontrano pericolosi attacchi di Brusone','https://www.enterisi.it/central/servizi/funzioni/download.aspx?type=inline&ID=118839&IDc=784&nomefile=8.Risisettembre2026_784_118839.pdf','2026-08-14'::date,'ALTA','Ausencia de ataque perigoso em 20 de julho NAO e ausencia de brusone: o proprio texto lembra que o ''mal del collo'' e o episodio de agosto e pede vigilancia. Nao ha numero de campos observados. Nao vale para as demais secoes nem para a Italia inteira. E os 233.500 ha sao estimativa parcial, com denominador declarado de 79%.',false) on conflict do nothing;
