insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','vozes','pessoa_e_origem','VINE','Veneto','Tecnico da Unidade Organizativa Fitossanitaria da Regiao Veneto sustentou, em encontro de 18/06/2026, que e preciso insistir em 2026 com os tratamentos inseticidas nas janelas indicadas e com o arranquio das plantas sintomaticas, apos os censos de 2025 terem encontrado Scaphoideus titanus em cerca de 92% das areas viticolas venetas.','92','% das areas viticolas venetas com presenca de Scaphoideus titanus, segundo censos de 2025','censo de 2025; recomendacao para a safra 2026','HISTORICAL','i censimenti del 2025 hanno rivelato una presenza diffusa di Scaphoideus Titanus... in gran parte delle aree viticole del Veneto (circa il 92%)','https://argav.org/2026/06/27/stagione-vitivinicola-2026-in-veneto-le-stime-produttive-reggono-nonostante-gli-sbalzi-climatici-molto-attenzione-alla-flavescenza-dorata/','2026-06-27'::date,'MEDIA','Confianca MEDIA porque a fala esta em discurso indireto do redator, nao em citacao direta dele. Os 92% sao presenca do INSETO VETOR, nao presenca da doenca flavescencia dourada — sao coisas diferentes. E e censo de 2025: nao prova a situacao de 2026. Nao ha aqui o numero de vinhedos censados.',false) on conflict do nothing;
