insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Emilia-Romagna — Bollettino di produzione integrata e biologica, Forli-Cesena, Ravenna e Rimini, N. 27','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/forli-cesena-ravenna-rimini/bollettino-27-del-19-agosto-2026-di-forli-cesena-ravenna-rimini.pdf/@@download/file',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Cereali autunno-vernini (frumento tenero e duro, orzo)','Forli-Cesena, Ravenna, Rimini (Emilia-Romagna)','O mesmo diagnostico de fase e a mesma lista de ativos aparecem, um dia antes, no boletim de outra area interprovincial da Emilia-Romagna (Forli-Cesena, Ravenna, Rimini)','post-raccolta','fase fenologica declarada','corrente em 19/08/2026','CURRENT','CEREALI AUTUNNO VERNINI (FRUMENTO E ORZO) Fase fenologica: post-raccolta Diserbo Per il diserbo delle stoppie da infestanti graminacee e dicotiledoni e possibile intervenire con: - Acido pelargonico - Glifosate - Glifosate + 2,4-D (Max 1 applicazione tra post-emergenza e post-raccolta)','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/forli-cesena-ravenna-rimini/bollettino-27-del-19-agosto-2026-di-forli-cesena-ravenna-rimini.pdf/@@download/file','2026-08-19'::date,'ALTA','Duas provincias nao fazem a regiao, e a regiao nao faz o pais. NAO prova a fase fenologica em Puglia, Sicilia, Basilicata (onde esta o trigo duro e a resistencia de Avena sterilis e Lolium rigidum que o acervo ja registra), nem no Norte fora da Emilia-Romagna. NAO prova qualquer data futura de abertura da janela de pre-semeadura.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Emilia-Romagna — Bollettino di produzione integrata e biologica, Forli-Cesena, Ravenna e Rimini, N. 27','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/forli-cesena-ravenna-rimini/bollettino-27-del-19-agosto-2026-di-forli-cesena-ravenna-rimini.pdf/@@download/file',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Barbabietola da zucchero','Forli-Cesena, Ravenna, Rimini (Emilia-Romagna)','A beterraba esta em accrescimento fittone / maturacao nos dois boletins de 19 e 20 de agosto de 2026, e nenhum dos dois abre secao de diserbo para ela — so difesa contra Cercospora','sem diserbo nesta data','secao ausente no boletim','corrente em 19/08/2026','CURRENT','BARBABIETOLA DA ZUCCHERO Fase fenologica: accrescimento fittone Difesa Cercospora: intervenire con Prodotti rameici eventualmente in miscela con Zolfo.','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/forli-cesena-ravenna-rimini/bollettino-27-del-19-agosto-2026-di-forli-cesena-ravenna-rimini.pdf/@@download/file','2026-08-19'::date,'ALTA','NAO prova quando a proxima janela abre — nenhum documento que li fixa data de semeadura da beterraba. NAO prova ausencia de infestantes no campo: o boletim so nao trata do assunto nesta data. NAO prova nada fora da Emilia-Romagna.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Emilia-Romagna — Bollettino di produzione integrata e biologica, Reggio Emilia, N. 27','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/modena-reggio-emilia/bollettini-di-reggio/bollettino-27-del-20-agosto-2026-reggio-emilia.pdf/@@download/file',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Patata e pomodoro (post-raccolta)','Emilia-Romagna (todo o territorio regional)','A Emilia-Romagna concedeu em 09/07/2026 uma derroga regional para sulfosulfuron (MONITOR) em post-raccolta de batata e tomate, com uso permitido de 22/06/2026 a 19/10/2026','22 giugno 2026 – 19 ottobre 2026','janela de uso autorizada por derroga','22/06/2026 a 19/10/2026','CURRENT','In data 9 luglio 2026 e stata concessa la deroga valida per l''intero territorio della Regione Emilia-[...] sulfosulfuron, da applicare nella fase di post-raccolta della patata e del pomodoro, per il controllo [...] pp. - impiego consentito dal 22 giugno 2026 fino al 19 ottobre 2026.','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/modena-reggio-emilia/bollettini-di-reggio/bollettino-27-del-20-agosto-2026-reggio-emilia.pdf/@@download/file','2026-08-20'::date,'ALTA','NAO e cultura do bloco (nao e cereal, arroz, beterraba nem milho). A especie-alvo nao foi recuperada pela nossa extracao do PDF (o texto sai truncado em ''per il controllo ... pp.'') — NAO_SEI qual daninha e; nao inventei. NAO prova que a mesma derroga exista em outra regiao. Derroga NAO e autorizacao de rotulo.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Emilia-Romagna — Bollettino di produzione integrata e biologica, Reggio Emilia, N. 27','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/modena-reggio-emilia/bollettini-di-reggio/bollettino-27-del-20-agosto-2026-reggio-emilia.pdf/@@download/file',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Colture non arboree (inclui cereais, mais, bietola)','Emilia-Romagna','A Emilia-Romagna limita o glifosate a 2 l/ha por ano por hectare de culturas nao arboreas, e declara que a aplicacao em pre-semina e ALTERNATIVA a de pre-emergencia, nao adicional','2','l/ha/ano (formulados 360 g/l), por hectare de cultura nao arborea','ano civil 1 gennaio – 31 dicembre 2026','CURRENT','Limite aziendale di impiego del glifosate su colture non arboree Ogni azienda per singolo anno (1 gennaio - 31 dicembre) puo disporre di un quantitativo massimo di glifosate (riferimento ai formulati 360 g/l) pari a 2 l/ha per ogni ettaro di colture non arboree [...] Si fa presente che le applicazioni di glifosate in pre-semina diventano alternative alle applicazioni in pre-emergenza (nelle colture dove e autorizzato questo impiego, es. bietola, mais, cipolla).','https://agricoltura.regione.emilia-romagna.it/fitosanitario/difesa-sostenibile/bollettini/bollettini-interprovinciali-di-produzione-integrata-e-biologica-2026/modena-reggio-emilia/bollettini-di-reggio/bollettino-27-del-20-agosto-2026-reggio-emilia.pdf/@@download/file','2026-08-20'::date,'ALTA','NAO prova o teto de nenhuma outra regiao — Lombardia, Veneto e as regioes do Sul tem disciplinari proprios que nao li nesta parte. NAO prova o teto para culturas arboreas (o boletim traz numeros diferentes para essas). NAO e regra de rotulo, e regra do disciplinare de producao integrada.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('GIRE — Gruppo Italiano di lavoro sulla Resistenza agli Erbicidi, ''Gestione della resistenza nei cereali autunno-vernini — Linee guida''','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf',ARRAY['CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Cereali autunno-vernini','Italia (nacional)','O flufenacet — o graminicida de pre-emergencia/pos-precoce classico dos cereais de outono, HRAC 15 (K3) — tem uso permitido apenas ate 10 de junho de 2026, segundo as linhas-guia GIRE atualizadas em marco de 2026','10 giugno 2026','data limite de uso declarada','corte em 10/06/2026','CURRENT','Flufenacet (*) Graminacee e Dicotiledoni Pre o post emergenza precoce [...] (*) Impiego consentito non oltre il 10 giugno 2026','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf','2026-03 (documento datado ''aggiornate a Marzo 2026'')'::date,'ALTA','⛔ Uso permitido ate uma data NAO e o mesmo que expiry de registro nem que withdrawal do produto — e um prazo de esgotamento declarado pela linha-guia tecnica. NAO prova que exista estoque, demanda ou substituicao de mercado. NAO converto isso em oportunidade comercial: e um fato regulatorio e agronomico. NAO verifiquei essa data na fonte primaria regulatoria (regulamento UE / decreto), so na linha-guia GIRE.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('GIRE — ''Gestione della resistenza nei cereali autunno-vernini — Linee guida (aggiornate a Marzo 2026)''','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf',ARRAY['CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Cereali autunno-vernini','Italia (nacional)','A tabela GIRE de marco de 2026 declara a EPOCA DE USO de cada principio ativo autorizado nos cereais de outono, por grupo HRAC — e essa e a definicao oficial de ''quando'', em fase fenologica','epoca por grupo HRAC','fase fenologica','safra 2026/2027','CURRENT','Gruppo 1 (A) Inibitori Acetil-CoA Carbossilasi (ACCasi) Principi attivi Epoca di impiego Clodinafop-propargil Graminacee Post-emergenza [...] Gruppo 3 (K1) Pendimetalin Dicotiledoni e Graminacee Pre- o post-emergenza precoce [...] Gruppo 9 (G) Glifosate Dicotiledoni e Graminacee Pre-semina, post raccolta','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf','2026-03'::date,'ALTA','NAO da nenhuma data de calendario: o GIRE nao escreve mes nem dia para essas epocas. NAO e rotulo — CROP_TERM_PRESENT/epoca na linha-guia nao e AUTHORIZED_ON_CROP no rotulo do produto. NAO prova o que esta autorizado em cada regiao: os disciplinari regionais podem restringir mais.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('GIRE — ''Gestione della resistenza nei cereali autunno-vernini — Linee guida (aggiornate a Marzo 2026)'', secao ''Cosa fare se ho biotipi di Loietto''','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf',ARRAY['CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Frumento (loietto / Lolium spp.)','Italia (nacional)','Para Lolium spp. com resistencia multipla aos grupos 1 (A) e 2 (B), o GIRE de marco de 2026 diz que o tratamento so de pos-emergencia NAO e possivel','pos-emergencia isolada nao e possivel','recomendacao tecnica','safra 2026/2027','CURRENT','Impiegare erbicidi dei gruppi 5 (C2), 3 (K1), 15 (K3) e 12 (F1) [...] in pre-emergenza o post-emergenza precoce, con infestanti a 2-3 foglie. [...] Se vi e resistenza multipla ad 1 (A) e 2 (B), non e possibile il trattamento di sola post-emergenza.','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf','2026-03'::date,'ALTA','NAO prova que exista resistencia dupla em nenhum campo especifico nem em nenhuma regiao especifica nesta safra — a ficha de especie do GIRE ja registrada no acervo e que localiza os biotipos. NAO prova pressao corrente de loietto. NAO e argumento comercial para nenhum produto: nao converto evento agronomico em oportunidade.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('GIRE — ''Gestione della resistenza nei cereali autunno-vernini — Linee guida (aggiornate a Marzo 2026)'', secao Avene','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf',ARRAY['CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Frumento (avena / Avena spp.)','Italia (nacional)','Para Avena spp. com resistencia multipla a 1 (A) e 2 (B), o GIRE de marco de 2026 recomenda explicitamente aplicar em pre-emergencia ou pos-emergencia precoce','pre-emergenza ou post-emergenza precoce','epoca recomendada','safra 2026/2027','CURRENT','Se vi e resistenza multipla ad 1 (A) e 2 (B), non e possibile il trattamento di sola post-emergenza, e raccomandato applicare in pre-emergenza o post-emergenza precoce con gli strumenti indicati','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf','2026-03'::date,'ALTA','NAO prova presenca corrente de avena resistente em campo nesta safra. NAO prova area afetada. NAO prova que os produtos ADAMA do acervo (clodinafop, HRAC 1(A), pos-emergencia) sejam ou deixem de ser adequados: isso depende do rotulo de cada produto, que continua sem AUTHORIZED_USE_ROWS lidas.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('GIRE — ''Gestione della resistenza nei cereali autunno-vernini — Linee guida (aggiornate a Marzo 2026)'', secao Alopecuro/Falaride','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf',ARRAY['CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Frumento (alopecuro / Alopecurus myosuroides e falaride / Phalaris spp.)','Italia (nacional)','Para alopecuro e falaride, o GIRE de marco de 2026 diz que e boa pratica integrar sempre a pos-emergencia com aplicacoes preventivas de pre-emergencia ou pos-precoce','integrar pos-emergencia com pre-emergencia/pos-precoce','recomendacao tecnica','safra 2026/2027','CURRENT','E buona pratica in ogni caso, nelle situazioni accertate, integrare gli interventi di post emergenza con applicazioni preventive in fase di pre-emergenza o di post precoce.','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_cereali.pdf','2026-03'::date,'ALTA','NAO prova presenca corrente. Alopecurus myosuroides aparece em 14 rotulos ADAMA no acervo, mas rotulo NAO e uso autorizado nem prova de janela. NAO prova nada por regiao — o texto e nacional.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('GIRE — ''Gestione infestanti resistenti nel riso — Linee guida (aggiornate a marzo 2026)''','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_riso.pdf',ARRAY['CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Riso (giavone / Echinochloa spp.)','Italia (arroz: Piemonte e Lombardia sao as areas do acervo)','O GIRE confirma que em 2024 apareceram os dois primeiros casos italianos de Echinochloa spp. com resistencia cruzada aos QUATRO inibidores de ACCase autorizados no arroz — cyhalofop-ethyl, profoxydim, cicloxydim e quizalofop-ethyl','2','populacoes de Echinochloa com resistencia cruzada aos 4 ACCase autorizados','primeiros casos confirmados em 2024; documento de marco de 2026','CURRENT','Nel 2024, inoltre, e stata confermata la presenza dei primi due casi di Echinochloa spp con resistenza incrociata a tutti e quattro gli inibitori ACCasi autorizzati per il riso in Italia (cyhalofop-ethyl, profoxydim, cicloxydim e quizalofop-ethyl).','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_riso.pdf','2026-03'::date,'ALTA','⛔ Dois casos confirmados NAO sao a situacao do parque risicola italiano — NAO_SEI a extensao. NAO prova em que provincias estao. NAO prova perda produtiva. NAO prova que o HIGHCARD tenha deixado de funcionar em lugar nenhum: a linha-guia lista quizalofop-P-ethyl como ativo para variedades de arroz TOLERANTES a esse herbicida, e a resistencia confirmada e da daninha, nao do produto. NAO converto isso em argumento comercial contra nem a favor de ninguem.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('GIRE — ''Gestione infestanti resistenti nel riso — Linee guida (aggiornate a marzo 2026)''','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_riso.pdf',ARRAY['CIENCIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Riso','Italia (nacional)','A tabela GIRE de marco de 2026 organiza todos os herbicidas autorizados no arroz por EPOCA — pre-semina, pre-semina+post-emergenza, pre-semina/pre-emergenza/post-emergenza, pre-emergenza, e post-emergenza — com o grupo HRAC de cada um','epoca por grupo HRAC','fase fenologica','safra 2026','CURRENT','PRE-SEMINA 1 (A) Cicloxydim Inibitore ACCasi G [...] 9 (G) Gliphosate Inibitore EPSP G D [...] POST-EMERGENZA 1 (A) Cyhalofop butyl Inibitore ACCasi G [...] 1 (A) Quizalofop-P-ethyl 2 Inibitore ACCasi G [...] 2 (B) Imazamox 3 Inibitore ALS G C D','http://gire.mlib.cnr.it/documentsSource/pubblicazioni/linee_guida_diserbo/Linee_guida_riso.pdf','2026-03'::date,'ALTA','NAO da data de calendario nenhuma. NAO prova que a janela esteja aberta agora — nao esta (ver registro seguinte). Imazamox e quizalofop-P-ethyl aparecem com nota de rodape restringindo-os a variedades de arroz tolerantes; NAO prova uso livre em arroz convencional.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Ente Nazionale Risi — Notizie (homepage)','https://www.enterisi.it/servizi/notizie/notizie_homepage.aspx',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Riso','Italia (areas risicolas)','O Ente Nazionale Risi nao publicou, em agosto nem no inicio de setembro de 2026, nenhuma comunicacao sobre diserbo ou infestantes — as unicas publicacoes tecnicas do periodo sao os bollettini de risco de brusone','nenhuma publicacao sobre diserbo','itens de noticia no periodo','julho a 01/09/2026','CURRENT','lunedi 10 agosto — ''Bollettini di rischio del brusone del riso'' ; martedi 01 settembre — ''Denuncia di rimanenza e dichiarazione delle scorte al 31 agosto 2026''','https://www.enterisi.it/servizi/notizie/notizie_homepage.aspx','2026-09-01 (item mais recente lido)'::date,'MEDIA','⛔ Ausencia na nossa leitura NAO e ausencia no mundo: o ENR presta assistencia tecnica por SAT (servico de campo) que nao publica na home; pode existir orientacao corrente que nao passa pelo site. NAO prova que nenhum arrozal esteja fazendo diserbo. NAO_SEI se ha boletim de infestantes em canal fechado.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Emilia-Romagna — ''Integrazione alle norme tecniche di coltura di difesa integrata e di controllo delle infestanti — Disciplinari di Produzione Integrata 2026'', Aprile 2026 (prot. 08/04/2026.03','https://agricoltura.regione.emilia-romagna.it/produzioni-agroalimentari/agricoltura-sostenibile/agricoltura-integrata/Collezione-dpi/dpi_2026/norme-in-vigore/integrazione_alle_norme_tecniche_di_coltura_del_8_aprile_2026_timbrato.pdf/@@download/file',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Frumento, orzo, avena, segale, mais, barbabietola da zucchero, girasole','Emilia-Romagna','A Emilia-Romagna aprovou os Disciplinari di Produzione Integrata 2026 com a Determinazione n. 3130 de 16/02/2026 e os integrou com um ato de 08/04/2026 que insere ativos de diserbo NOMEANDO A EPOCA por cultura','epoca por cultura','fase fenologica declarada em ato regional','ano agrario 2026','CURRENT','Le indicazioni di seguito riportate integrano le norme tecniche di coltura di difesa integrata e di controllo delle infestanti approvate con la determinazione n. 3130 del 16/02/2026 [...] CONTROLLO DELLE INFESTANTI COLTURE ERBACEE — Avena Pre-semina, Pre-emergenza Pyraflufen-etile [...] Frumento Post-raccolta per il controllo di infestanti dicoltiledoni Pyraflufen-etile Inserita [...] Barbabietola da zucchero Post-emergenza per la risoluzione di casi particolari Florpyrauxifen-benzyl Inserita','https://agricoltura.regione.emilia-romagna.it/produzioni-agroalimentari/agricoltura-sostenibile/agricoltura-integrata/Collezione-dpi/dpi_2026/norme-in-vigore/integrazione_alle_norme_tecniche_di_coltura_del_8_aprile_2026_timbrato.pdf/@@download/file','2026-04-08'::date,'ALTA','⛔ Corrige a premissa do bloco: o disciplinare NAO fixa data de calendario. Fixa epoca fenologica. Procurei ''epoca di semina'' com mes/dia no DPI 2026 do Abruzzo (documento equivalente, 823 mil caracteres extraidos) e nao ha nenhuma ocorrencia. NAO prova o que vale em outra regiao. NAO e rotulo: o disciplinare restringe, nao autoriza.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Lombardia — Servizio Fitosanitario Regionale, ''Disciplinari di produzione integrata''','https://fitosanitario.regione.lombardia.it/wps/portal/site/sfr/DettaglioRedazionale/protezione-delle-colture-e-del-verde/norme-tecniche-difesa-diserbo/disciplinari-produzione-integrata',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Todas (parte difesa e diserbo)','Lombardia','A Lombardia aprovou seus Disciplinari di Produzione Integrata 2026 com o D.d.s. n. 3864 de 25 de marco de 2026, e publicou em 05/05/2026 as schede tecniche di diserbo','D.d.s. n. 3864 del 25 marzo 2026','ato de aprovacao','ano agrario 2026','CURRENT','Con D.d.s. n. 3864 del 25 marzo 2026 sono stati approvati i Disciplinari di Produzione integrata per la Regione Lombardia, validi per il 2026. I disciplinari, costituiti da una sezione relativa alle tecniche agronomiche e una specifica per la difesa e il diserbo, costituiscono il riferimento regionale [...]','https://fitosanitario.regione.lombardia.it/wps/portal/site/sfr/DettaglioRedazionale/protezione-delle-colture-e-del-verde/norme-tecniche-difesa-diserbo/disciplinari-produzione-integrata','2026-03-25 (ato); schede diserbo publicadas 05/05/2026'::date,'ALTA','NAO li o conteudo das schede di diserbo da Lombardia — elas estao publicadas so como arquivo compactado (.zip, 346 KB) e eu nao baixei arquivo compactado. NAO_SEI quais epocas a Lombardia fixa por cultura. NAO prova nada sobre janela corrente: e um ato de marco de 2026, nao um boletim de setembro.',false) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ERSA Friuli-Venezia Giulia — Bollettini fitosanitari, colture erbacee e orticole, bollettini 2026 e 2024','http://difesafitosanitaria.ersa.fvg.it/difesa-e-produzione-integrata/difesa-integrata-obbligatoria/bollettini-fitosanitari/colture-erbacee-orticole/bollettini-2026',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','herbicida','issue_window','Cereali autunno-vernini','Friuli-Venezia Giulia (e Veneto, serie propria)','A serie de boletins de cereais de outono para a semeadura de 2026 ainda nao saiu em Friuli-Venezia Giulia nem no Veneto: em 02/09/2026 o ultimo boletim de colture erbacee do FVG e o n.15 sobre milho, de 12/08/2026, e o do Veneto e o Erbacee n.02 de 05/06/2026','nenhum boletim de cereais de outono na serie 2026','boletins publicados','serie 2026 ate 12/08/2026','CURRENT','Boll_15_MAIS_120826.pdf (ultimo da serie 2026, colture erbacee, FVG) ; Boll_17_Cereali autunno-vernini_13092024.pdf (serie 2024)','http://difesafitosanitaria.ersa.fvg.it/difesa-e-produzione-integrata/difesa-integrata-obbligatoria/bollettini-fitosanitari/colture-erbacee-orticole/bollettini-2026','2026-08-12 (ultimo item da serie 2026)'::date,'ALTA','⛔ Sazonalidade historica NAO prova janela corrente: o boletim de 13/09/2024 nao autoriza dizer que o de 2026 saira em 13/09/2026. NAO_SEI quando sai. ⛔ Ausencia de boletim NAO e ausencia de operacao no campo — o produtor pode ja estar fazendo falsa semina sem que exista boletim. NAO prova nada sobre Emilia-Romagna, que publica em serie semanal propria.',false) on conflict do nothing;
