insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola',NULL,'Italia','O dataflow ISTAT 101_1015 e o cubo de superficie e producao por cultura e por territorio. Estrutura de dados DCSP_COLTIVAZIONI v1.1. Chave de consulta: FREQ.REF_AREA.DATA_TYPE.TYPE_OF_CROP.DESTINATION_WINEGRAPES. Serie anual de 2006 a 2026. Ultima atualizacao registrada na anotacao LAST_UPDATE: 2026-07-28T09:04:47.207Z.',NULL,NULL,'2006-2026','HISTORICAL','<common:Name xml:lang="it">Coltivazioni</common:Name> ... <Ref id="DCSP_COLTIVAZIONI" version="1.1" agencyID="IT1" package="datastructure" class="DataStructure" />','https://esploradati.istat.it/SDMXWS/rest/dataflow/IT1/101_1015','2026-07-28'::date,'ALTA','Nao prova nada sobre praga, doenca, uso de defensivo ou mercado. E so o mapa de onde ha area plantada e quanto se colheu.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — Coltivazioni (101_1015)','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT+ITC1+ITC2+ITC3+ITC4+ITDA+ITD1+ITD2+ITD3+ITD4+ITD5+ITE1+ITE2+ITE3+ITE4+ITF1+ITF2+ITF3+ITF4+ITF5+ITF6+ITG1+ITG2.ART+PA+TP_QUIN_EXT+HP_Q_EXT+TP_HECT_EXT+TPT.MAIZE+GRAIZE+WHEATD+COMMEAT+RICE+SOYA+BEETS.?startPeriod=2024',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola','frumento duro','Italia (com quebra pelas 20 regioes)','Frumento duro — a maior area de cultura anual da Italia. Concentracao muito forte no Sul: Puglia 294.300 ha (25,9%), Sicilia 275.895 ha (24,3%), Basilicata 115.160 ha (10,2%), Marche 79.072 ha (7,0%), Emilia-Romagna 68.065 ha (6,0%).','1.134.227 ha; 36.182.505 q de producao colhida (= 3.618.250 t)','ha / quintali','2025','HISTORICAL','WHEATD: frumento duro | ART: superficie totale - ettari | HP_Q_EXT: produzione raccolta - quintali','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT+ITC1+ITC2+ITC3+ITC4+ITDA+ITD1+ITD2+ITD3+ITD4+ITD5+ITE1+ITE2+ITE3+ITE4+ITF1+ITF2+ITF3+ITF4+ITF5+ITF6+ITG1+ITG2.ART+PA+TP_QUIN_EXT+HP_Q_EXT+TP_HECT_EXT+TPT.MAIZE+GRAIZE+WHEATD+COMMEAT+RICE+SOYA+BEETS.?startPeriod=2024','2026-07-28'::date,'ALTA','Area grande nao e sinonimo de problema grande nem de demanda. E o denominador, nao o numerador.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — Coltivazioni (101_1015)','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT+ITC1+ITC2+ITC3+ITC4+ITDA+ITD1+ITD2+ITD3+ITD4+ITD5+ITE1+ITE2+ITE3+ITE4+ITF1+ITF2+ITF3+ITF4+ITF5+ITF6+ITG1+ITG2.ART+PA+TP_QUIN_EXT+HP_Q_EXT+TP_HECT_EXT+TPT.VINEFORTHE+WINESQ+WINESO+WINEES+TABLEGRAPES+OLIV+OLIVTAB_OIL+APPLET.?startPeriod=2024',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola','olivo','Italia (com quebra pelas 20 regioes)','Olive da tavola e da olio (olivo) — praticamente empatado com o frumento duro como maior area da Italia. Puglia 347.350 ha (31,4%), Calabria 184.682 ha (16,7%), Sicilia 161.751 ha (14,6%), Toscana 81.729 ha (7,4%), Lazio 78.991 ha (7,1%). Presente nas 20 regioes, inclusive Valle d''Aosta com 1 ha.','1.107.789 ha; 24.357.826 q de producao colhida (= 2.435.783 t)','ha / quintali','2025','HISTORICAL','OLIVTAB_OIL: olive da tavola e da olio | ART: superficie totale - ettari','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT+ITC1+ITC2+ITC3+ITC4+ITDA+ITD1+ITD2+ITD3+ITD4+ITD5+ITE1+ITE2+ITE3+ITE4+ITF1+ITF2+ITF3+ITF4+ITF5+ITF6+ITG1+ITG2.ART+PA+TP_QUIN_EXT+HP_Q_EXT+TP_HECT_EXT+TPT.VINEFORTHE+WINESQ+WINESO+WINEES+TABLEGRAPES+OLIV+OLIVTAB_OIL+APPLET.?startPeriod=2024','2026-07-28'::date,'ALTA','A area total do olivo inclui plantas jovens que ainda nao produzem; por isso a resa que calculei (2,20 t/ha nacional) e um piso, nao a produtividade do olival produtivo.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — Coltivazioni (101_1015)','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT+ITC1+ITC2+ITC3+ITC4+ITDA+ITD1+ITD2+ITD3+ITD4+ITD5+ITE1+ITE2+ITE3+ITE4+ITF1+ITF2+ITF3+ITF4+ITF5+ITF6+ITG1+ITG2.ART+PA+TP_QUIN_EXT+HP_Q_EXT+TP_HECT_EXT+TPT.VINEFORTHE+WINESQ+WINESO+WINEES+TABLEGRAPES+OLIV+OLIVTAB_OIL+APPLET.?startPeriod=2024',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola','vite (uva da vino)','Italia (com quebra pelas 20 regioes)','Uva da vino (vite para vinificacao) — Sicilia 118.329 ha (17,0%), Veneto 104.398 ha (15,0%), Puglia 93.655 ha (13,5%), Toscana 60.785 ha (8,8%), Emilia-Romagna 53.169 ha (7,7%). O contraste de produtividade e enorme: Veneto 14,05 t/ha contra Sicilia 4,77 t/ha (calculo meu).','694.333 ha; 66.793.717 q de producao colhida (= 6.679.372 t)','ha / quintali','2025','HISTORICAL','WINEES: uva da vino | ART: superficie totale - ettari | HP_Q_EXT: produzione raccolta - quintali','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT+ITC1+ITC2+ITC3+ITC4+ITDA+ITD1+ITD2+ITD3+ITD4+ITD5+ITE1+ITE2+ITE3+ITE4+ITF1+ITF2+ITF3+ITF4+ITF5+ITF6+ITG1+ITG2.ART+PA+TP_QUIN_EXT+HP_Q_EXT+TP_HECT_EXT+TPT.VINEFORTHE+WINESQ+WINESO+WINEES+TABLEGRAPES+OLIV+OLIVTAB_OIL+APPLET.?startPeriod=2024','2026-07-28'::date,'ALTA','A diferenca de t/ha entre Veneto e Sicilia e diferenca de sistema produtivo, clima e destino do vinho — NAO e evidencia de perda por praga nem de doenca. Nao usar como sinal sanitario.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — Coltivazioni (101_1015)','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT..MAIZE.?startPeriod=2023',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
