insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola','orzo, girasole, patata','Italia (com quebra pelas 20 regioes)','Bonus, nao pedidos mas coletados porque vinham na mesma chamada: orzo (cevada) 228.832 ha, muito espalhado — maior regiao e Piemonte com so 9,7%; girasole 109.397 ha, com Marche 33.558 ha (30,7%); patata comune 33.253 ha, com Campania 5.458 ha (16,4%). Kiwi e pesca tambem foram baixados e estao no CSV.','orzo 228.832 ha / 8.439.955 q; girasole 109.397 ha / 2.904.825 q; patata 33.253 ha / 10.200.377 q','ha / quintali','2025','HISTORICAL','BARLEY: orzo | SUNFLO: girasole | POTA: patata comune','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT+ITC1+ITC2+ITC3+ITC4+ITDA+ITD1+ITD2+ITD3+ITD4+ITD5+ITE1+ITE2+ITE3+ITE4+ITF1+ITF2+ITF3+ITF4+ITF5+ITF6+ITG1+ITG2.ART+PA+TP_QUIN_EXT+HP_Q_EXT+TP_HECT_EXT+TPT.APPLE+BARLEY+POTA+SUNFLO+KIWI+PEACH.?startPeriod=2024','2026-07-28'::date,'ALTA','Nao foram conferidos linha a linha como as culturas do pedido. Confidence media para os numeros regionais de kiwi e pesca, que eu nao inspecionei.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — Coltivazioni (101_1015)','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT..MAIZE.?startPeriod=2023',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola','todas','Italia','O ano 2026 aparece no cubo com superficie E producao para TODAS as culturas, incluindo oliveira, uva da vino e mais — colheitas de setembro a dezembro. A data de atualizacao do dataflow e 28/07/2026. Exemplos de 2026 na Italia: mais 530.296 ha e 54.376.129 q; olive 1.109.392 ha e 24.883.536 q; uva da vino 681.842 ha e 71.076.128 q; mela 55.012 ha e 23.913.152 q. Verifiquei o campo OBS_STATUS em todas as 2.945 linhas baixadas: vem VAZIO em 100% delas, sem nenhum flag de provisorio.','2026 presente para todas as culturas; OBS_STATUS vazio em 2.945/2.945 linhas',NULL,'2026','HISTORICAL','IT1:101_1015(1.0),A,IT,HP_Q_EXT,MAIZE,ALL,2026,54376129,,,,TIPO_DATO5__HP_Q_EXT_N1,C1500,,,,,,','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT..MAIZE.?startPeriod=2023','2026-07-28'::date,'MEDIA','NAO SEI qual e o rotulo oficial do ISTAT para 2026 — a API nao marca. O que sei e que producao de oliveira publicada em julho nao pode ser colheita observada. Tratar 2026 como estimativa. Para comparacao de escala, usar 2025, que e o ultimo ano com ciclo fechado.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — codelist CL_TIPO_DATO5','https://esploradati.istat.it/SDMXWS/rest/codelist/IT1/CL_TIPO_DATO5',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola','todas','Italia','A resa (t/ha) NAO e publicada neste cubo. Eu a calculei: produzione raccolta em quintais / 10 / superficie totale em hectares. O campo PA (superficie in produzione - ettari) existe na estrutura mas veio VAZIO em todas as linhas baixadas, entao o denominador correto para culturas perenes nao esta disponivel.','resa derivada, nao publicada','t/ha','2024-2026','HISTORICAL','PA | superficie in produzione - ettari','https://esploradati.istat.it/SDMXWS/rest/codelist/IT1/CL_TIPO_DATO5',NULL::date,'ALTA','Para olivo, vite, melo e uva da tavola minha resa e um PISO, porque a area total inclui plantas jovens que ainda nao produzem. Nao publicar essas resas como se fossem numero oficial do ISTAT.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — Coltivazioni (101_1015)','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A..ART.MAIZE.?startPeriod=2025&endPeriod=2025',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.lastmile_registro_pendente (missao, bloco, destino_pretendido, crop_literal, geografia_literal, o_que, valor_texto, unidade, periodo, classe, citacao_literal, source_url, publicado_em, confianca, o_que_nao_prova, exige_rota_italiana) values ('LAST-MILE-2026-09-02','istat-area-producao','estatistica_agricola','melo, vite, olivo, frumento duro','Italia','Checagem de coerencia que passou: para APPLE, WINEES, OLIVTAB_OIL e WHEATD, a soma das 20 regioes bate EXATAMENTE com o total nacional publicado (ex.: melo, 55.110 ha somando as regioes contra 55.110 ha no total Italia). Atencao a uma armadilha do codigo de territorio: ITDA e a regiao Trentino-Alto Adige, e ITD1 (Bolzano) e ITD2 (Trento) sao as duas provincias autonomas DENTRO dela. Somar os tres duplica a area.','soma das 20 regioes = total nacional, em 4 culturas testadas',NULL,'2025','HISTORICAL','ITDA: Trentino Alto Adige / Südtirol | ITD1: Provincia Autonoma Bolzano / Bozen | ITD2: Provincia Autonoma Trento','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A..ART.MAIZE.?startPeriod=2025&endPeriod=2025','2026-07-28'::date,'ALTA','O cubo tambem traz nivel provincial (ITC11, ITD51 etc.) e macroareas (ITC, ITD, ITE, ITF, ITG). Boletim provincial nao representa a regiao, e macroarea nao representa o pais — nao misturar niveis.',true) on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ISTAT — Coltivazioni (101_1015)','https://esploradati.istat.it/SDMXWS/rest/data/IT1,101_1015,1.0/A.IT.ART.MAIZE.?startPeriod=1990',ARRAY['ESTATISTICA_OFICIAL']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
