insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPAV - Report meteoclimatico mensile Veneto, Luglio 2026','https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file' or 'https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file' like url_base||'%' order by length(url_base) desc limit 1),'Veneto, separado em montanha/pedemontana, planicie e planicie meridional','REGIONAL','OUTRA',NULL,'-9% no total regional; montanha/pedemontana entre -20% e -30% (pontas de -50%); planicie cerca de +20%','percentual em relacao a norma 1991-2020',coalesce('2026-08'::date,'2026-08-01'),coalesce('2026-08'::date,'2026-09-02'),'HISTORICAL','https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file','2026-08'::date,'CLIMA E CONDICAO. Deficit de chuva nao e perda de produtividade e nao e doenca. Este registro serve justamente para desmontar media: o numero unico de -9% esconde -50% na montanha e +20% na planicie. Quem usar so o -9% para falar do Veneto inteiro esta apagando a metade da historia. E julho, nao agosto.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPAV - Report meteoclimatico mensile Veneto, Luglio 2026, secao 6.4','https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file' or 'https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file' like url_base||'%' order by length(url_base) desc limit 1),'Legnaro, provincia de Padova, Veneto (UMA estacao)','PROVINCIAL','OUTRA',NULL,'cerca de 15 dias de adiantamento','dias de antecipacao na soma termica base 10',coalesce('2026-08'::date,'2026-08-01'),coalesce('2026-08'::date,'2026-09-02'),'HISTORICAL','https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file','2026-08'::date,'CLIMA E CONDICAO. Soma termica adiantada nao e presenca de doenca, nao e praga e nao e perda de produtividade. E de UMA estacao (Legnaro): nao representa Padova, nem o Veneto, nem a Italia. E indicador de calor acumulado, nao de lavoura medida.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPAV - Report meteoclimatico mensile Veneto, Luglio 2026, secao 6.3','https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/rapporti-mensili/report_meteoclima_07-2026.pdf/@@download/file',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
