insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPAV - nota Meteo Veneto de 31/08/2026','https://www.arpa.veneto.it/temi-ambientali/meteo/documenti-meteo/notizia_meteo_20260831.pdf/@@download/file',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
