insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPAV - Bollettino Agrometeorologico Regionale n.21','https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file' or 'https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file' like url_base||'%' order by length(url_base) desc limit 1),'Regione Veneto','REGIONAL','OUTRA',NULL,'temperaturas bem acima da norma; chuva ausente ou local em montanha','descricao qualitativa',coalesce('2026-09-02'::date,'2026-08-01'),coalesce('2026-09-02'::date,'2026-09-02'),'OUTLOOK','https://www.arpa.veneto.it/temi-ambientali/agrometeo/file-e-allegati/bollettino_agrometeo_regionale_settimanale.pdf/@@download/file','2026-09-02'::date,'Isto e PREVISAO, nao medicao — pode nao acontecer. E CLIMA E CONDICAO: nao e presenca de doenca, nao e incidencia de praga, nao e perda. Nao misturar com os registros CURRENT: previsao de calor para sexta nao e calor medido.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARPAV Open Data - Principali variabili meteorologiche','https://www.arpa.veneto.it/dati-ambientali/open-data/clima/principali-variabili-meteorologiche',ARRAY['AGROMETEOROLOGIA']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.clima_observacao (fonte_id, geografia_literal, nivel, variavel, valor, valor_texto, unidade, periodo_inicio, periodo_fim, classe, source_url, publicado_em, o_que_nao_prova) values ((select id from public.fonte_externa where url_base='https://www.arpa.veneto.it/dati-ambientali/open-data/clima/principali-variabili-meteorologiche' or 'https://www.arpa.veneto.it/dati-ambientali/open-data/clima/principali-variabili-meteorologiche' like url_base||'%' order by length(url_base) desc limit 1),'Veneto (rede completa)','REGIONAL','OUTRA',NULL,'1994 a 2024, 210 estacoes em 2023','serie mensal e anual por estacao',coalesce('2025-07-24'::date,'2026-08-01'),coalesce('2025-07-24'::date,'2026-09-02'),'HISTORICAL','https://www.arpa.veneto.it/dati-ambientali/open-data/clima/principali-variabili-meteorologiche','2025-07-24'::date,'CLIMA E CONDICAO, e alem disso PASSADO. Esta serie termina em 2024 — nao diz absolutamente nada sobre 2026. Sazonalidade historica NAO prova presenca corrente. Serve para comparar, nunca para afirmar o que esta acontecendo agora. Eu mapeei o dataset mas NAO baixei o zip.') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Fondazione Edmund Mach - Centro Trasferimento Tecnologico','https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base' or 'https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino Difesa Integrata di Base N.25, Fondazione Edmund Mach - Centro Trasferimento Tecnologico. Preenche TRENTINO-ALTO ADIGE (lado Trento), que estava em zero. Culturas no documento: MELO, ACTINIDIA, SUSINO, OLIVO, FRAGOLA, CILIEGIO, VITE.',coalesce('2026-08-28'::date,'2026-09-02'),'Trentino-Alto Adige (Provincia di Trento)','PROVINCIAL',ARRAY['olivo']::text[],true,NULL,'Stadio fenologico: L''olivo presenta l''endocarpo della drupa indurito e i frutti si stanno accrescendo per distensione cellulare. / Mosca olearia: Generalmente la popolazione della mosca dell''olivo e bassa in tutti i punti di monitoraggio; solo nelle zone piu umide si osserva una presenza piu elevata. / In questo momento non e consigliata un''azione diretta di contenimento.','https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Fondazione Edmund Mach - Centro Trasferimento Tecnologico','https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base' or 'https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base' like url_base||'%' order by length(url_base) desc limit 1),'Mesmo boletim FEM N.25, secao MELO - colpo di fuoco batterico (Erwinia amylovora) na macieira do Trentino.',coalesce('2026-08-28'::date,'2026-09-02'),'Trentino-Alto Adige (Provincia di Trento)','PROVINCIAL',ARRAY['melo']::text[],true,NULL,'Colpo di fuoco batterico: Nell''ultimo periodo e stato riscontrato qualche caso di colpo di fuoco batterico (Erwinia amylovora). La sorveglianza dei frutteti e di fondamentale importanza al fine di individuare tempestivamente le piante colpite. (...) In questo periodo la comparsa dei sintomi e in continua evoluzione, e pertanto importante monitorare i frutteti con frequenza (ogni 7 giorni).','https://ctt.fmach.it/Divulgazione/Messaggistica-tecnica-e-bollettini/Bollettini-Difesa-integrata-di-base','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Giunta Regionale della Campania, UOS 207.03.03 Difesa delle Colture - Servizio Fitosanitario Regionale','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/BN-26-08.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/BN-26-08.pdf' or 'https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/BN-26-08.pdf' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino Fitosanitario della Provincia di Benevento N.24, Servizio Fitosanitario Regionale da Campania. Preenche CAMPANIA, que estava em zero. Traz ponto UTM, comune, localita, variedade, fase fenologica e CONTAGEM POR ARMADILHA - tem denominador de verdade.',coalesce('2026-08-26'::date,'2026-09-02'),'Campania (Provincia di Benevento)','PROVINCIAL',ARRAY['vite']::text[],true,'4 adultos/armadilha (Lobesia botrana) e 3 Scaphoideus titanus em Benevento loc. Acquafredda; 3 adultos de Lobesia botrana em Castelvenere','Stadio fenologico: Invaiatura. Presenza di sintomi di erinosi sulla superficie fogliare, causata dall''acaro fitofago Colomerus vitis. Dal monitoraggio dei voli, mediante trappole a feromoni, e stata rilevata una presenza media: di n. 4 adulti per trappola di Tignoletta della vite (Lobesia botrana); nessuna presenza di adulti di Tignola rigata della vite (Cryptoblabes gnidiella); di n. 3 Scafoideo (Scaphoideus titanus) su trappole cromotropiche.','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/BN-26-08.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Giunta Regionale della Campania - Servizio Fitosanitario Regionale','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' or 'https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino Fitosanitario della Provincia di Salerno N.24 - a provincia com o leque mais largo de culturas: ACTINIDIA, AGRUMI, CILIEGIO, VITE, FRAGOLA, NOCCIOLO, NOCE, OLIVO, POMODORO. Registro do OLIVO.',coalesce('2026-08-26'::date,'2026-09-02'),'Campania (Provincia di Salerno)','PROVINCIAL',ARRAY['olivo']::text[],true,NULL,'COLTURA OLIVO - 1 Campagna, Localita Santa Maria La Nova, varieta Rotondella / Salella-Frantoio-Leccino, Stadio Fenologico: Completo indurimento nocciolo, Stato Fitosanitario: Minime cattura di mosca. 2 Agropoli, Palombe, Stadio: Accrescimento del frutto, Stato Fitosanitario: Nulla.','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/SA-26-08.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('OP LATIUM Soc. Coop. Agr. / Agroambiente Lazio (dados climaticos ARSIAL-SIARL)','https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204' or 'https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204/' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino Fitosanitario zona SABINA n.09/2026, mosca da oliveira - Lazio. Preenche LAZIO, que estava em zero. E o documento mais rigoroso da coleta: declara metodologia de amostragem, soglia de intervencao, estadio BBCH e o ataque MEDIDO.',coalesce('2026-08-31'::date,'2026-09-02'),'Lazio (zona progettuale Sabina)','AREAL',ARRAY['olivo']::text[],true,'Attacco rilevato: 0-1%','AVVERSITA'': Mosca dell''olivo - Bactrocera oleae. Fase fenologica: SVILUPPO DEI FRUTTI (Scala BBCH Olio 79) ''Le drupe hanno raggiunto circa il 90% delle dimensioni finali.'' Condizioni meteo: NON FAVOREVOLI. Rilievo infestazione: Si esaminano 20 olive a pianta su 10 piante scelte a caso per cultivar per ettaro, un totale di 200 olive. Soglia di intervento - Metodo Adulticida Olive da olio: 4-5% di punture fertili o 2 femmine ovigere/trappola/settimana. Attacco rilevato: 0-1%. PRESCRIZIONE: NON EFFETTUARE TRATTAMENTO.','https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('OP LATIUM Soc. Coop. Agr. / Agroambiente Lazio','https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204' or 'https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204/' like url_base||'%' order by length(url_base) desc limit 1),'As outras 4 zonas do Lazio na MESMA semana. Serve como prova interna de que zona nao representa regiao: elas discordam em fase fenologica, em ataque medido e ate no numero da edicao.',coalesce('2026-08-31'::date,'2026-09-02'),'Lazio (Lago di Bolsena, Litorale Viterbese, Entroterra Viterbese-Tuscia, Pianura Interna Viterbese)','AREAL',ARRAY['olivo']::text[],true,'Lago di Bolsena 0-1%; Entroterra Tuscia 0-1%; Litorale Viterbese 0-2%; Pianura Interna Viterbese 0%','Litorale Viterbese: ''Attacco rilevato: 0-2%'' - PRESCRIZIONE: NON EFFETTUARE TRATTAMENTO. Pianura Interna Viterbese: ''Attacco rilevato: 0%'' e fase fenologica ''Le drupe hanno raggiunto circa il 70% delle...'' (contra ''...circa il 90% delle dimensioni finali'' nas outras quatro zonas).','https://www.agroambientelazio.it/lotta-guidata/news/bollettini-fitosanitari-per-la-lotta-guidata-alla-mosca-dell-olivo/204/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARSAC - Azienda Regionale per lo Sviluppo dell''Agricoltura Calabrese, su mandato da Regione Calabria','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026' or 'https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino agrometeorologico e fitosanitario ARSAC - agrumi, olivo, vite e kiwi, semana 36. Preenche CALABRIA, que estava em zero. E um dos poucos boletins REGIONAIS de verdade da coleta: cobre o territorio todo dividido em 8 areas climaticamente homogeneas.',coalesce('2026-09-01'::date,'2026-09-02'),'Calabria (8 zonas: Cosenza Tirrenica, Cosenza Ionica, Piana di Lamezia e Vibo, Catanzarese, Crotonese, Ionio Reggino, Tirreno Reggino, Locride)','AREAL',ARRAY['olivo']::text[],true,NULL,'Olivo: tutti gli oliveti osservati hanno completato l''indurimento nocciolo ed alcuni hanno iniziato l''invaiatura. Le temperature alte hanno inibito gli attacchi di mosca, l''umidita molto alta ha favorito lo sviluppo di tardive infezioni fungine come l''occhio di pavone.','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-1-8-settembre-2026/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ARSAC / Regione Calabria','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026' or 'https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026/' like url_base||'%' order by length(url_base) desc limit 1),'Mesmo boletim ARSAC, semana 35, secao VITE - a unica linha da coleta inteira com um quantificador regional explicito.',coalesce('2026-08-25'::date,'2026-09-02'),'Calabria','REGIONAL',ARRAY['vite']::text[],true,'oltre il 90% dei vigneti osservati em fase de maturacao','Vite: In oltre il 90% dei vigneti osservati la coltura si trova nella fase fenologica di maturazione, mentre dal punto di vista fitopatologico, si osservano infestazioni di cicalina anche gravi, in buona parte dei vigneti monitorati. Le probabili cause dell''incremento delle popolazioni di questo insetto sono da ricercare nella significativa riduzione della biodiversita (...) insieme alla riduzione dei trattamenti insetticidi per il controllo della Tignoletta, sostituiti dall''adozione delle tecniche di confusione sessuale.','https://www.arsacweb.it/bollettino-agrometeorologico-e-fitosanitario-agrumi-olivo-vite-e-kiwi-valido-dal-25-agosto-al-1-settembre-2026/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Liguria - Centro di Agrometeorologia Applicata Regionale (C.A.A.R.), Settore Servizi alle Imprese Agricole e Florovivaismo','https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16' or 'https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16/' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino Olivo n.16 do C.A.A.R. da Regione Liguria. Preenche LIGURIA, que estava em zero.',coalesce('2026-08-27'::date,'2026-09-02'),'Liguria (4 provincias separadas: Genova, Imperia, La Spezia, Savona)','PROVINCIAL',ARRAY['olivo']::text[],true,NULL,'Attualmente dalle attivita di monitoraggio non emergono infestazioni rilevanti in corso, nonostante nel corso della settimana le condizioni meteo siano risultate piu favorevoli all''attivita della mosca. Si rilevano comunque alcune situazioni di allerta per le quali si consiglia di prestare attenzione al prossimo comunicato, preparandosi eventualmente ad intervenire in maniera tempestiva.','https://sia.regione.liguria.it/index.php/bollettino-olivo-n-16/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Liguria - C.A.A.R.','https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2' or 'https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2/' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino Vite n.25 do mesmo C.A.A.R. da Liguria, mesma data. Registro separado porque e outra cultura.',coalesce('2026-08-27'::date,'2026-09-02'),'Liguria (4 provincias separadas: Genova, Imperia, La Spezia, Savona)','PROVINCIAL',ARRAY['vite']::text[],true,NULL,'Questa settimana non si e osservato un aumento rilevante della concentrazione zuccherina, anche a causa delle recenti precipitazioni, ma si continua a rilevare un progressivo calo delle acidita, generalmente piu accentuato nei vitigni bianchi. In alcuni casi i valori sono gia idonei alla vendemmia e in diverse aree proseguono le raccolte, anche per evitare cali troppo marcati delle acidita.','https://sia.regione.liguria.it/index.php/bollettino-vite-n-24-2/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('ALSIA - Agenzia Lucana di Sviluppo e di Innovazione in Agricoltura','https://www.alsia.it/opencms/opencms/Servizi/Fito/Metapontino.html',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.alsia.it/opencms/opencms/Servizi/Fito/Metapontino.html' or 'https://www.alsia.it/opencms/opencms/Servizi/Fito/Metapontino.html' like url_base||'%' order by length(url_base) desc limit 1),'Bollettino Fitosanitario ALSIA n.16, area Metapontino. Preenche BASILICATA, que estava em zero. Li o INDICE oficial com o numero e o intervalo; o PDF em si fica atras de um botao JavaScript que eu nao consegui resolver.',coalesce('2026-08-19'::date,'2026-09-02'),'Basilicata (area Metapontino, provincia di Matera)','PROVINCIAL','{}',true,NULL,'Bollettino n.16 - Mese di Agosto Intervallo : dal 19.08.2026 al 02.09.2026 - Scarica Bollettino','https://www.alsia.it/opencms/opencms/Servizi/Fito/Metapontino.html','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione Molise, Presidenza della Giunta Regionale, Servizio Fitosanitario Regionale','https://www.regione.molise.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/18077',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.molise.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/18077' or 'https://www.regione.molise.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/18077' like url_base||'%' order by length(url_base) desc limit 1),'Comunicato fitosanitario n.5/2026 do Servizio Fitosanitario Regionale do Molise. Preenche MOLISE no sentido de que existe canal ativo - MAS NAO e boletim de campo. Registro justamente para impedir que alguem conte isso como boletim.',coalesce('2026 (o PDF nao traz dia; e o n.5 da serie de 2026)'::date,'2026-09-02'),'Molise','REGIONAL','{}',true,NULL,'Oggetto: Comunicato fitosanitario 5 - Con D.D. 1951/26 e successiva integrazione degli aggiornamenti approvati per l''anno 2026 di cui alla DD n. 2546 del 5 Maggio 2026, si e provveduto alla formale approvazione dei Disciplinari di Produzione Integrata 2026 - Difesa e Tecniche Agronomiche. (...) la Regione Molise, aderisce integralmente alle LGNPI 2026.','https://www.regione.molise.it/flex/cm/pages/ServeBLOB.php/L/IT/IDPagina/18077','HISTORICAL') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('SIAS - Servizio Informativo Agrometeorologico Siciliano, Regione Siciliana','http://www.sias.regione.sicilia.it/corpo_difesa_20190722.htm',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='http://www.sias.regione.sicilia.it/corpo_difesa_20190722.htm' or 'http://www.sias.regione.sicilia.it/corpo_difesa_20190722.htm' like url_base||'%' order by length(url_base) desc limit 1),'SICILIA: o canal oficial de boletim de difesa fitossanitaria, que o diretorio nacional aponta para TODAS as 9 provincias sicilianas, esta congelado em 2019. O achado aqui e a PARADA, nao o conteudo.',coalesce('2019-07-22'::date,'2026-09-02'),'Sicilia','REGIONAL',ARRAY['olivo']::text[],true,'percentuale di frutti attaccati inferiore al 2% (dado de 2019, area do Agrigentino)','Sono state riscontrate le prime catture del dittero negli areali piu freschi dell''Agrigentino: pertanto si consiglia di attenzionare anche le drupe alla ricerca delle prime punture fertili. I tecnici dell''Assessorato Agricoltura hanno finora riscontrato una percentuale di frutti attaccati inferiore al 2%, per cui si consiglia di non effettuare alcun intervento.','http://www.sias.regione.sicilia.it/corpo_difesa_20190722.htm','HISTORICAL') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Agrometeopuglia - ARIF Puglia (Agenzia Regionale Attivita Irrigue e Forestali) / Regione Puglia','https://www.agrometeopuglia.it/bollettini',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.agrometeopuglia.it/bollettini' or 'https://www.agrometeopuglia.it/bollettini' like url_base||'%' order by length(url_base) desc limit 1),'A EXPLICACAO da lacuna do FRUMENTO DURO. A Puglia, maior produtora nacional de trigo duro, declara na propria pagina do servico agrometeorologico que suspendeu a secao de fitopatologia ha oito anos e que os boletins territoriais nao existem mais.',coalesce('aviso vigente lido em 02/09/2026; refere-se a mudanca de 11/04/2018'::date,'2026-09-02'),'Puglia','REGIONAL',ARRAY['frumento duro']::text[],true,NULL,'Dal Notiziario Agrometeorologico Regionale n. 15 del 11/04/2018, la sezione dedicata alla Fitopatologia non viene piu redatta poiche le competenze sono in fase di trasferimento all''Agenzia Regionale Attivita Irrigue e Forestali (ARIF), come stabilito dalla Legge Regionale n. 33 del 07/08/2017 e ss.mm.ii., cosi come non sono piu disponibili i bollettini territoriali.','https://www.agrometeopuglia.it/bollettini','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('verificacao propria sobre os 15 PDFs capturados','https://www.agrometeopuglia.it/bollettini',ARRAY['AGROMETEOROLOGIA','BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.agrometeopuglia.it/bollettini' or 'https://www.agrometeopuglia.it/bollettini' like url_base||'%' order by length(url_base) desc limit 1),'FRUMENTO DURO segue em ZERO depois desta coleta, e eu conferi em vez de supor: rodei grep por ''frumento'', ''grano duro'' e ''cereal'' nos 15 PDFs baixados e o resultado foi nenhum arquivo.',coalesce('2026-09-02'::date,'2026-09-02'),'Italia (as 6 regioes novas desta coleta)','REGIONAL',ARRAY['frumento duro']::text[],true,NULL,'(sem citacao de fonte - este e um registro sobre o que NAO foi encontrado, e esta marcado como tal)','https://www.agrometeopuglia.it/bollettini','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Giunta Regionale della Campania - Servizio Fitosanitario Regionale','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/AV-26-08.pdf',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/AV-26-08.pdf' or 'https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/AV-26-08.pdf' like url_base||'%' order by length(url_base) desc limit 1),'AVISO para quem for cruzar esta coleta com o demo: os boletins da Campania citam a palavra ''carpocapsa'', mas NAO e a carpocapsa da maca. E outra especie, em outra cultura.',coalesce('2026-08-26'::date,'2026-09-02'),'Campania (Provincia di Avellino)','PROVINCIAL',ARRAY['castagno']::text[],true,'presenza media di n. 1 adulto de Pammene fasciana e n. 1 adulto de Cydia splendana por armadilha, em Sorbo Serpico','TORTRICE TARDIVA (Cydia splendana), Lepidottero Tortricidae, noto anche come carpocapsa delle castagne, principale fitofago carpofago del castagno in Italia. (...) Stadio fenologico: Ingiallimento riccio. Diffusa presenza di galle causate dal Cinipide galligeno del Castagno (Dryocosmus kuriphilus).','https://agricoltura.regione.campania.it/difesa/bollettini/bollettini_2026/pdf/AV-26-08.pdf','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Fitogest - Image Line, secao PAN / Bollettini tecnici provinciali e zonali','https://fitogest.imagelinenetwork.com/it/pan-piano-uso-sostenibile/bollettini-tecnici-provinciali-zonali',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://fitogest.imagelinenetwork.com/it/pan-piano-uso-sostenibile/bollettini-tecnici-provinciali-zonali' or 'https://fitogest.imagelinenetwork.com/it/pan-piano-uso-sostenibile/bollettini-tecnici-provinciali-zonali/' like url_base||'%' order by length(url_base) desc limit 1),'O DIRETORIO NACIONAL de boletins - o item mais dificil de refazer de toda a coleta. Lista a URL canonica do boletim fitossanitario de TODAS as 20 regioes e de ~100 provincias italianas. Foi ele que me entregou Molise, Basilicata, Valle d''Aosta, Abruzzo e Sardegna, que eu nao estava achando por busca',coalesce('2026-09-02 (data da captura; a pagina nao declara data de atualizacao)'::date,'2026-09-02'),'Italia (20 regioes, ~100 provincias)','PROVINCIAL','{}',true,NULL,'I bollettini di produzione integrata e biologica sono gli strumenti, previsti dal PAN, creati per informare imprenditori agricoli e tecnici/consulenti sulla situazione fitosanitaria e agronomica delle colture; le indicazioni in essi contenute sono fondamentali per ottenere un uso razionale e sostenibile dei prodotti fitosanitari.','https://fitogest.imagelinenetwork.com/it/pan-piano-uso-sostenibile/bollettini-tecnici-provinciali-zonali/','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Regione del Veneto - Servizio Fitosanitario Regionale','https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026' or 'https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026' like url_base||'%' order by length(url_base) desc limit 1),'VENETO - a regiao de maior prioridade do bloco (3 casos do demo estao la) e a UNICA que a VPN italiana nao resolveu. Explico o motivo tecnico exato para ninguem tentar de novo achando que e geografia.',coalesce('tentativa em 2026-09-02'::date,'2026-09-02'),'Veneto','REGIONAL','{}',true,NULL,'urlopen error [SSL: CERTIFICATE_VERIFY_FAILED] certificate verify failed: unable to get issuer certificate (_ssl.c:1010)','https://www.regione.veneto.it/web/fitosanitario/bollettini-fitosanitari-2026','CURRENT') on conflict do nothing;
insert into public.fonte_externa (nome, url_base, natureza, pais) values ('Agenzia Laore Sardegna / AgroAmbiente Regione Abruzzo / Regione autonoma Valle d''Aosta','https://www.agenzialaore.it/servizionline/notiziarifitosanitari.nsf/xpNotiziariViewArchivio.xsp',ARRAY['BOLETIM_FITOSSANITARIO']::fonte_natureza[],'IT') on conflict (url_base) do nothing;
insert into public.boletim_fitossanitario (fonte_id, titulo, publicado_em, geografia_literal, nivel, crops_declaradas, crop_declarada, fase_declarada, citacao_literal, source_url, classe) values ((select id from public.fonte_externa where url_base='https://www.agenzialaore.it/servizionline/notiziarifitosanitari.nsf/xpNotiziariViewArchivio.xsp' or 'https://www.agenzialaore.it/servizionline/notiziarifitosanitari.nsf/xpNotiziariViewArchivio.xsp' like url_base||'%' order by length(url_base) desc limit 1),'SARDEGNA, ABRUZZO e VALLE D''AOSTA - as tres restantes que ficaram sem boletim, cada uma por um motivo diferente. Registro para nao virar ''nao existe''.',coalesce('tentativa em 2026-09-02'::date,'2026-09-02'),'Sardegna, Abruzzo, Valle d''Aosta','REGIONAL','{}',true,NULL,'Sardegna (Laore): ''502 Proxy Error - The proxy server received an invalid response from an upstream server.'' / Abruzzo (agroambiente.regione.abruzzo.it/node/3): titulo da pagina ''previsioni meteorologiche 27/05/2021 02/06/2021''','https://www.agenzialaore.it/servizionline/notiziarifitosanitari.nsf/xpNotiziariViewArchivio.xsp','CURRENT') on conflict do nothing;
